--
-- Table structure for table `termek`
--

DROP TABLE IF EXISTS `termek`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `termek` (
  `cim` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_hungarian_ci NOT NULL,
  `kiado_id` int NOT NULL,
  `kiadas_eve` year NOT NULL,
  `nyelv_id` int NOT NULL,
  `oldalak_szama` int NOT NULL,
  `borito_id` int DEFAULT NULL,
  `ISBN` bigint NOT NULL,
  `ar` int NOT NULL,
  `raktar` int NOT NULL DEFAULT '1',
  `kategoria_id` int NOT NULL,
  `tipus_id` int NOT NULL,
  `leiras` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_hungarian_ci,
  `illusztracio` int DEFAULT NULL,
  PRIMARY KEY (`ISBN`),
  KEY `FK_termek_kiado_id` (`kiado_id`),
  KEY `FK_termek_nyelv_id` (`nyelv_id`),
  KEY `FK_termek_borito_id` (`borito_id`),
  KEY `FK_termek_kategoria_id` (`kategoria_id`),
  KEY `FK_termek_tipus_id` (`tipus_id`),
  KEY `FK_termek_illusztracio` (`illusztracio`),
  CONSTRAINT `FK_termek_borito_id` FOREIGN KEY (`borito_id`) REFERENCES `borito` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_termek_illusztracio` FOREIGN KEY (`illusztracio`) REFERENCES `illusztracio` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_termek_kategoria_id` FOREIGN KEY (`kategoria_id`) REFERENCES `kategoria` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_termek_kiado_id` FOREIGN KEY (`kiado_id`) REFERENCES `kiado` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_termek_nyelv_id` FOREIGN KEY (`nyelv_id`) REFERENCES `nyelv` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_termek_tipus_id` FOREIGN KEY (`tipus_id`) REFERENCES `tipus` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_hungarian_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

