INSERT INTO `termek` VALUES ('Szlovákia védett ásványai és kövületei ',42,2006,1,134,7,8080623228,1805,1,30,3,NULL,NULL),('The Weight of Zero - Semmi súlya ',1,2018,1,198,1,2399977867906,1430,1,16,3,'Bipoláris zavar olyan, mint egy halálos ítélet.\r\n\r\nA tizenhét éves Catherine Pulaski tudja, hogy Semmi eljön érte. Semmi, a Catherine bipoláris zavarából születő pusztító depresszió egyszer már majdnem győzedelmeskedett felette: ekkor akart először öngyilkos lenni.\r\n\r\nA bipoláris zavar egy életre szól. Soha nem múlik el. Talán pillanatnyilag hat a gyógyszer, de Semmi vissza fog térni. Csak idő kérdése.\r\n\r\nÍgy hát Catherine egy régi balettcipős dobozban gyógyszereket gyűjtöget, és arra készül, hogy kioltja az életét, még mielőtt Semmi újra élőhalottá változtatja. De még mielőtt megtenné, rövid bakancslistába kezd.\r\n\r\nA bakancslista, a család támogatása, az új barátok és egy újfajta kezelés együttesen elkezdi lebontani Catherine elszigeteltségének falait. A probléma csak az, hogy a terv már olyan régen megszületett a fejében, hogy a jövő talán már nem is létezik a számára.\r\n\r\nEz a történet a veszteségről, a bánatról és a reményről szól, valamint arról, hogy a szeretet különféle formái az anyai szeretet és a romantikus, plátói szerelem milyen hatással vannak egy fiatal nő küzdelmére a mentális betegségével és a kezelés stigmájával.\r\n\r\nSosem leszek normális.\r\nA mánia nem zavar. Inkább az ellentéte, Semmi akaszt ki. Halálra rémülök tőle.\r\nAki még soha nem érezte így magát, az nem tudja megérteni, milyen, amikor az érzelmek szabadságra mennek. Az érthetetlen, kimondhatatlan súly reménytelensége.\r\nMégis mennem kellene előre.\r\nÉlni, még ha tudom is, hogy előbb vagy utóbb vissza fog térni.\r\nMagánzárka Semmi fekete tundrájában.\r\nEz nem élet.\r\nSzóval van egy tervem.\r\n\r\nA remény ott lapul, ahol a legkevésbé számítasz rá.\r\n\r\nŐszinte és életigenlő írás egy máig tabutémának számító betegségről. Utat mutathat a mentális betegségekkel élő tinédzsereknek és szeretteiknek.\r\nKépet nyújt egy ismeretlen, rémítő világról.\r\n\r\nKövesd Cath sorsát és éld át a reményt!',NULL),('Egy marék rozs',5,1977,1,231,10,2399987630880,940,1,17,3,'Rex Fortescue rosszul lesz az irodájában, a Cityben, és a kórházban meghal. \"A tea...\" - mondta a halála előtt. De a méreg, ami végzett vele, nem lehetett a teában. A zsebében pedig egy marék rozst találnak. Gyanúsítottban nincs hiány: a néhai pénzmágnás közutálatnak örvendett.\r\nNeele felügyelőnek a nyomozásban segítőtársa is akad hamarosan. A Tiszafa-kunyhóba, a Fortescue család házába megérkezik Miss Marple. Addigra már három hulla van: Adele, Rex felesége és Gladys, a szobalány is gyilkosság áldozata lett. Miss Marple, akinél Gladys régebben szolgált, az ő halála miatt ártja bele magát az ügybe. \"Hat hatosról énekelj\", idézi a gyerekverset, amelyben a pástétomba sütött feketerigókról is szó esik. Tiszafa-kunyhóban pedig néhány hete döglött rigókat találtak!\r\nTalán a legcsavarosabb eset ez, amellyel Jane Marple-nek meg kell birkóznia.',NULL),('Királylány a talpán ',34,2000,1,180,1,2399996859036,940,1,28,3,NULL,NULL),('Nyírd ki a bandát! ',4,2017,1,288,6,2399997101233,940,1,16,3,'Barátok. Rajongók. Marhára elegük van abból, hogy kedvesek legyenek. \"Sokkolóan vicces, okosan megírt regény a rajongói szenvedélyről és a kamaszkorról.\" New York Daily News',NULL),('Stalingrad',21,2007,2,378,9,9780141032405,3999,16,12,1,'In October 1942, a panzer officer wrote:\n\n\'Stalingrad is no longer a town... Animals flee this hell; the hardest stones cannot bear it for long; only men endure\'.\n\nThe battle for Stalingrad became the focus of Hitler and Stalin\'s determination to win the gruesome, vicious war on the eastern front. The citizens of Stalingrad endured unimaginable hardship; the battle, with fierce hand-to-hand fighting in each room of each building, was brutally destructive to both armies.\n\nBut the eventual victory of the Red Army, and the failure of Hitler\'s Operation Barbarossa, was the first defeat of Hitler\'s territorial ambitions in Europe, and the start of his decline.\n\nAn extraordinary story of tactical genius, civilian bravery, obsession, carnage and the nature of war itself, Stalingrad will act as a testament to the vital role of the soviet war effort.',NULL),('An Army At Dawn: The War in North Africa, 1942-1943',22,2004,2,349,9,9780349116365,2999,3,12,1,'The liberation of Europe and the destruction of the Third Reich is a story of courage and enduring triumph, of calamity and miscalculation. In this first volume of the Liberation Trilogy, Rick Atkinson shows why no modern reader can understand the ultimate victory of the Allied powers without a grasp of the great drama that unfolded in North Africa in 1942 and 1943. Beginning with the daring amphibious invasion in November 1942, An Army at Dawn follows the British and American armies as they fight the French in Morocco and Algeria, and then take on the Germans and Italians in Tunisia. Battle by battle, an inexperienced and sometimes poorly led army gradually becomes a superb fighting force. Central to the tale are the extraordinary but fallible commanders who come to dominate the battlefield: Eisenhower, Patton, Bradley, Montgomery and Rommel.\n\n',NULL),('Bobby Fischer Teaches Chess',17,2008,2,295,9,9780553263152,7999,1,23,1,'Bobby Fischer Teaches Chess is a classic self-instruction book designed to build strong chess fundamentals through clear, step-by-step lessons. Using a unique programmed learning approach, Fischer guides readers from basic tactical patterns to more advanced checkmating techniques. Ideal for beginners and improving players, the book helps develop strategic thinking, pattern recognition, and confidence on the board.',NULL),('The Wild Blue: The Men and Boys Who Flew the B-24s over Germany 1944-45',20,2002,2,398,9,9780743223096,3999,2,12,1,'The Wild Blue tells the powerful true story of the young men who flew B-24 bombers over Nazi-controlled Europe during the final, brutal years of World War II. Focusing particularly on future U.S. Senator George McGovern and his crew, the book offers a vivid, human portrait of courage, fear, sacrifice, and camaraderie in the air. Through gripping narrative and detailed research, it reveals what it meant to fight—and survive—in the perilous skies over Germany in 1944–45.',NULL),('Grandpa\'s Christmas Gift ',34,2023,2,22,7,9781326880477,1710,1,28,3,NULL,1),('Five Nights at Freddy\'s: The Silver Eyes - Five Nights at Freddy\'s',24,2018,2,400,9,9781338134377,4999,2,16,1,'The first book in the bestselling Five Nights at\n\nFreddy\'s series, based on the wildly popular horror computer\n\ngame.\n\nTen years after the horrific murders at Freddy Fazbear\'s Pizza\n\nthat ripped their town apart, Charlie, whose father owned the restaurant,\n\nand her childhood friends reunite on the anniversary of\n\nthe tragedy and find themselves at the old pizza place which had\n\nbeen locked up and abandoned for years.\n\nAfter they discover a way inside, they realize that things are\n\nnot as they used to be. The four adult-sized animatronic mascots\n\nthat once entertained patrons have changed. They now have\n\na dark secret . . . and a murderous agenda.\n\nwritten by the creator of the computer game\n\nnot suitable for younger readers',NULL),('Five Nights at Freddy\'s: The Twisted Ones - Five Nights at Freddy\'s',24,2019,2,413,9,9781338139303,4999,2,16,1,'The highly anticipated sequel to the bestselling Five Nights at Freddy\'s:\n\nThe Silver Eyes.\n\nIt\'s been a year since the horrific events at Freddy Fazbear\'s Pizza,\n\nand Charlie is just trying to move on. Even with the excitement\n\nof a new school and a fresh start, she\'s still haunted by nightmares\n\nof a masked murderer and four gruesome animatronic puppets.\n\nCharlie thinks her ordeal is over, but when a series of bodies\n\nare discovered near her school-bearing wounds that are disturbingly\n\nfamiliar-she finds herself drawn back into the world of her father\'s\n\nfrightening creations. Something twisted is hunting Charlie,\n\nand this time if it finds her, it\'s not letting her go.',NULL),('Five Nights at Freddy\'s: The Fourth Closet - Five Nights at Freddy\'s',24,2019,2,417,9,9781338139327,4999,4,19,1,'The pulse-pounding conclusion to the bestselling Five\n\nNights At Freddy’s trilogy.\n\nWhat really happened to Charlie?\n\nIt’s the question that John can’t seem to shake, along\n\nwith the nightmares of Charlie’s seeming death and miraculous\n\nreappearance.\n\nJohn just wants to forget the whole terrifying saga of Freddy\n\nFazbear’s Pizza, but the past isn’t so easily buried.\n\nAlmost twelve years after the horrific murders at Freddy’s,\n\nthere’s a new animatronic pizzeria opening\n\nin Hurricane, along with new rash of kidnappings that feel all\n\ntoo familiar.\n\nBound together by their childhood loss, John reluctantly teams\n\nup with Jessica, Marla, and Carlton to solve the case and find the\n\nmissing children.\n\nAlong the way, they’ll unravel the twisted mystery\n\nof what really happened to Charlie, and the haunting\n\nlegacy of her father’s creations.\n\nOriginal stories based on the hit computer game of the same name\n\nThe perfect gift for all FNAF fans\n\nCheck out the full-colour fact books which acompany the novels',NULL),('Five Nights at Freddy\'s: Survival Logbook - Five Nights at Freddy\'s',24,2020,2,190,7,9781338229301,7999,1,19,1,'Based on the bestselling horror video game series Five Nights at\n\nFreddy\'s, this essential logbook offers night guards new to Freddy\n\nFazbear\'s Pizza a chance for self-reflection during their first\n\nweek on the job. Quizzes, lists, and prompts throughout reinforce\n\ntraining, provide room to log in-game events and allow for introspection\n\non the best qualities of a Freddy\'s employee - namely,\n\na genuine disregard for instinctive self-preservation. It\'s all here\n\nin this logbook - just be sure to fill out your emergency contact\n\ninformation first!',NULL),('Into the Pit (Five Nights at Freddy\'s: Fazbear Frights #1) - Five Nights at Freddy\'s',24,2021,2,289,9,9781338576016,5999,13,19,1,'Five Nights at Freddy\'s fans won\'t want to miss\n\nthis pulse-pounding collection of three novella-length tales\n\nthat will keep even the bravest player up at night...\n\nWhat do you wish for most?\n\nIt\'s a question that Oswald, Sarah and Millie think they know\n\nthe answer to.\n\nOswald wishes his summer wasn\'t so boring, Sarah wishes to be\n\nbeautiful and Millie wishes she could just disappear from the face\n\nof the earth. But in the twisted world of Five Nights at Freddy\'s,\n\ntheir hearts\' deepest desires have an unexpected cost.\n\nIn this volume, horror master Scott Cawthon spins three sinister\n\nnovella-length stories from different corners of his series\'\n\ncanon.\n\nEach story comes complete with accompanying artwork from fan-favourite\n\ngame artist LadyFiszi, who brings the horror to life in\n\nstartling new ways.\n\n \n\nReaders beware: this collection of terrifying tales is enough\n\nto unsettle even the most hardened Five Nights at Freddy\'s\n\nfans.',NULL),('Fazbear Frights #2: Fetch - Five Nights at Freddy\'s',24,2022,2,310,9,9781338576023,5999,12,19,1,'The Fazbear Frights series continues with three more\n\nbone-chilling, novella-length tales to keep even the bravest Five\n\nNights at Freddy\'s player up at night...\n\nAfter years of being kicked around, Greg, Alec and Oscar are ready\n\nto take control of their lives. Greg decides to put the controversial\n\nscience he\'s been studying to the test. Alec launches a\n\nmaster plot to expose his golden sister for the spoiled brat he\n\nknows she is. And Oscar, ever the miniature grown-up his mom needs\n\nhim to be, decides to take something he wants ... even though he\n\nknows it\'s wrong. But as these three will learn, control is a fragile\n\nthing in the sinister world of Five Nights at Freddy\'s.\n\nIn this second volume, horror master Scott Cawthon spins three\n\nsinister novella-length stories from different corners of his series\'\n\ncanon. Each story comes complete with accompanying artwork\n\nfrom fan-favourite game artist LadyFiszi, who brings the horror to\n\nlife in startling new ways.\n\nReaders beware: this collection of terrifying tales\n\nis enough to unsettle even the most hardened Five\n\nNights at Freddy\'s fans.',NULL),('FAZBEAR FRIGHTS #3: 1:35AM - Five Nights at Freddy\'s',24,2024,2,309,9,9781338576030,5999,11,19,1,'Five Nights at Freddy\'s fans won\'t want to\n\nmiss this pulse-pounding collection of three novella-length tales\n\nthat will keep even the bravest FNAF player up at night...\n\nFrom twisted toys to gut-wrenching games, this collection of terrifying\n\ntales is unsettling enough to mess with even the most hardened\n\nFive Nights at Freddy\'s fans. In this volume, horror\n\nmaster Scott Cawthon spins three sinister novella-length stories\n\nfrom different corners of FNAF\'s canon. Each story comes complete\n\nwith accompanying artwork from a fan-favourite game artist\n\nto bring the horror to life in a whole new way.\n\nReaders beware: in this startling world, desperate wishes have\n\nan unexpected cost, beautiful trinkets reveal appalling powers and\n\nharmless pranks can go awry in ghastly ways.',NULL),('Bunny Call (Five Nights at Freddy\'s: Fazbear Frights #5) - Five Nights at Freddy\'s',24,2023,2,315,9,9781338576047,5999,4,19,1,'Five Nights at Freddy\'s fans won\'t want to miss this\n\npulse-pounding collection of three novella-length tales that will\n\nkeep even the bravest FNAF player up at night...\n\nWhen left in darkness, rage festers. Years of frustration with\n\nhis family culminate in a loathsome vacation for Bob, who plots\n\na sinister prank to frighten his wife and kids. Matt redirects the\n\nresidual anger over his many failed relationships into a video\n\ngame, and ends up birthing the horrible consequences. In room 1280\n\nof Heracles Hospital, something evil is keeping a man alive, a\n\nman with gruesome burns all over his body and an iron will to live.\n\nIn this fifth volume, Five Nights at Freddy\'s creator Scott\n\nCawthon spins three sinister novella-length stories from different\n\ncorners of his series\' canon, featuring cover art from fan-favourite\n\nartist LadyFiszi.\n\nReaders beware: this collection of terrifying tales is enough\n\nto unsettle even the most hardened Five Nights at Freddy\'s\n\nfans.',NULL),('Step Closer (Five Nights at Freddy\'s: Fazbear Frights #4) - Five Nights at Freddy\'s',24,2022,2,319,9,9781338576054,5999,9,19,1,'Five Nights at Freddy\'s fans won\'t want to\n\nmiss this pulse-pounding collection of three novella-length tales\n\nthat will keep even the bravest FNAF player up at night...\n\nFrom twisted toys to gut-wrenching games, this collection of terrifying\n\ntales is unsettling enough to mess with even the most hardened\n\nFive Nights at Freddy\'s fans. In this volume, horror\n\nmaster Scott Cawthon spins three sinister novella-length stories\n\nfrom different corners of FNAF\'s canon. Each story comes complete\n\nwith accompanying artwork from a fan-favourite game artist\n\nto bring the horror to life in a whole new way.\n\nReaders beware: in this startling world, desperate wishes have\n\nan unexpected cost, beautiful trinkets reveal appalling powers and\n\nharmless pranks can go awry in ghastly ways.',NULL),('Blackbird (Five Nights at Freddy\'s: Fazbear Frights #6)',24,2023,2,327,9,9781338703894,5999,4,19,1,'ive Nights at Freddy\'s fans won\'t want\n\nto miss this pulse-pounding collection of three novella-length tales\n\nthat will keep even the bravest FNAF player up at night...\n\nHaunted by the past…\n\nTo avoid confronting an ugly truth, Nole falls prey to a monster\n\nthat punishes past transgressions. Growing weaker by the day,\n\nnine-year-old Jake looks back on the time before he was sick, imagining\n\nlife as if he were well again. And, forever desperate to prove\n\nhis worth to his arrogant brother and distant father, Toby chases\n\nvictory at an arcade game with horrifying consequences. But\n\nin the unpredictable world of Five Nights at Freddy\'s,\n\nsometimes the past can take on a life of its own.\n\nIn this sixth volume, Five Nights at Freddy\'s creator\n\nScott Cawthon spins three sinister novella-length stories\n\nfrom different corners of his series\' canon, featuring cover\n\nart from fan-favourite artist LadyFiszi.\n\nReaders beware: this collection of terrifying tales\n\nis enough to unsettle even the most hardened Five Nights at\n\nFreddy\'s fans.',NULL),('The Cliffs (Five Nights at Freddy\'s: Fazbear Frights #7) - Five Nights at Freddy\'s',24,2024,2,326,9,9781338703917,5999,9,19,1,'Five Nights at Freddy\'s fans won\'t want to miss\n\nthis pulse-pounding collection of three novella-length tales\n\nthat will keep even the bravest FNAF player up at night...\n\nSome things must be learned the hard way … Reed sees an\n\nopportunity to teach the school bully not to mess with him, but\n\nends up mangling the lesson. Robert, an exhausted single father,\n\ngets a crash course in parenting when he buys a fancy new teddy bear\n\nto watch and entertain his young son. Chris, eager to join the\n\nScience Club at school, agrees to undergo a grisly experiment to\n\nbe accepted. But in the malevolent universe of Five Nights\n\nat Freddy\'s, there\'s always an education in pain.\n\nIn this seventh volume, Five Nights at Freddy\'s creator\n\nScott Cawthon spins three sinister novella-length stories from\n\ndifferent corners of his series\' canon, featuring cover art from\n\nfan-favourite artist LadyFiszi.\n\nReaders beware: this collection of terrifying\n\ntales is enough to unsettle even the most hardened Five Nights\n\nat Freddy\'s fans.',NULL),('Nana, Vol. 1 - Nana',12,2008,2,192,9,9781421501086,3999,10,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nNana Komatsu is a young woman who\'s endured an unending string of boyfriend problems. Moving to Tokyo, she\'s hoping to take control of her life and put all those messy misadventures behind her. She\'s looking for love and she\'s hoping to find it in the big city.\r\n\r\nNana Osaki, on the other hand, is cool, confident and focused. She swaggers into town and proceeds to kick down the doors to Tokyo\'s underground punk scene. She\'s got a dream and won\'t give up until she becomes Japan\'s No. 1 rock\'n\'roll superstar.\r\n\r\nThis is the story of two 20-year-old women who share the same name. Even though they come from completely different backgrounds, they somehow meet and become best friends. The world of Nana is a world exploding with sex, music, fashion, gossip and all-night parties.',4),('Nana, Vol. 2 - Nana',12,2008,2,200,9,9781421503783,3999,11,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nAnxious to get into a Tokyo groove, both women are on the prowl for a funky and cheap place to live. But inexpensive apartments in Japan\'s capital city are hard to find. Thank goodness each Nana has a clique of cool friends willing to help out. Too bad these friends are a little wiggy!',4),('Nana, Vol. 3 - Nana',12,2008,2,192,9,9781421504797,3999,12,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nThings are slowly coming together for Nana Osaki. The guitarist and drummer from her old band have joined her in Tokyo and she\'s finally found a ripping new bass player to replace Ren Honjo. The Black Stones are back and they\'re ready to kick some ass.\r\n\r\nNana Komatsu, however, can\'t shake her old nemesis, the Demon Lord. She\'s stuck in a dead-end job and there\'s trouble brewing with her boyfriend, Shoji. He\'s been working late and hasn\'t exactly been the most attentive lover. Poor Nana. Life in Tokyo is turning out to be a total bummer.',4),('Nana, Vol. 4 - Nana',12,2008,2,192,9,9781421504803,3999,20,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nNana K.\'s perfect Tokyo life is crumbling around her. She can\'t keep a job, she can\'t keep any money, and now it looks like she can\'t even keep her boyfriend! But luckily, a tasty nugget of gossip about Nana O.\'s past love life helps Nana K. keep her mind off her own troubles. If she can play the role of cupid for her best friend, can Nana K. get closer to her own happy ending?',4),('Nana, Vol. 5 - Nana',12,2008,2,200,9,9781421510194,3999,6,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nNana K. is going home--for an awesome Trapnest concert! She drags Nana O. along, convinced that somehow Ren will sense his ex-flame in the audience. But life is never that easy, and Nana O. isn\'t sure if she even wants Ren back. As for Nana K., is she prepared for Trapnest to come down off the stage and into her life, or will her fan-girl attitude land her in a heap of trouble?',4),('Nana, Vol. 6 - Nana',12,2008,2,192,9,9781421510200,3999,30,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nNana\'s band Blast is taking off in a big way--from sold-out club dates to a record label waving a contract at them. But the Trapnest menace still lurks, stealing away everything she cares for. Trapnest took her boyfriend, and even though Ren is back in her life, his band still comes first. And now her trusty sidekick Hachi is being lured away by Trapnest bassist Takumi. But this time, Nana won\'t give up without a fight!',4),('Nana, Vol. 7 - Nana',12,2008,2,208,9,9781421510217,3999,21,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nHachi was happy to be Blast\'s biggest cheerleader, but now that the band is taking off, she\'s discovering that there are hordes of fans eager to take her place. At the same time, her involvement with Trapnest hottie Takumi is turning into a romantic entanglement she hadn\'t expected. When a chance for another kind of happiness presents itself, will Hachi be strong enough to face the difficult choices that result?',4),('Nana, Vol. 8 - Nana',12,2008,2,200,9,9781421515397,3999,12,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nHachi\'s happiness with Nobu is slipping through her fingers as an unexpected complication with Takumi threatens to upend her entire life. And unlike her past romantic woes, the choice she makes now will change the lives of everyone around her.',4),('Nana, Vol. 9 - Nana',12,2008,2,280,9,9781421517452,3999,8,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nTakumi and Hachi are getting married, but it\'s far from a joyous announcement. Nobu and Nana are devastated, and even Takumi\'s bandmates take the news hard. With paparazzi skulking around for a new scandal to exploit and tensions between Trapnest and Blast on high alert, will Hachi ever get her happily ever after?',4),('Nana, Vol. 10 - Nana',12,2008,2,280,9,9781421517469,3999,22,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nBeing engaged isn\'t as wonderful as Hachi thought it would be. She has a trendy new apartment, but she\'s isolated from all her friends and Takumi is hardly ever home. When scandal hits hard, Trapnest (and her fiancé) flee to Europe, and Hachi is left to watch Blast suffer in the scandal rags and tabloid shows.',4),('Nana, Vol. 11 - Nana',12,2008,2,256,9,9781421517476,3999,19,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nWith the tabloids still out for blood, Nana and her Blast bandmates move into a weird dorm building run by their agency. But they\'ve barely got enough time to settle into their new digs because their crammed schedule has them running from music studio to TV interview. The stress of band life and dealing with a disintegrating Ren have started to take their toll on Nana. If she collapses now, will she ever get back up?',4),('Nana, Vol. 12 - Nana',12,2009,2,208,9,9781421518794,3999,20,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nHachi tells herself that she\'s got her eye on the future and her life with Takumi, but she just can\'t let go of the past and her friendship with Nana and the rest of Blast--especially Nobu. And the tangle gets thicker when Hachi\'s wedding has to be postponed in favor of Nana and Ren\'s nuptials. Can Hachi handle another delay in her happily-ever-after?',4),('Nana, Vol. 13 - Nana',12,2009,2,200,9,9781421518800,3999,13,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nHachi hasn\'t seen Nana or the rest of Blast since she moved in with Takumi, and Shin and Reira\'s joint birthday party seems like the perfect chance for a little reunion. But Takumi is furious at Hachi for crashing the event, and she is forced to choose Takumi over Nana one more time. But was this Hachi\'s last chance to get back in Nana\'s life?',4),('Nana, Vol. 14 - Nana',12,2009,2,200,9,9781421519722,3999,3,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nAs Blast gears up for their major label debut, their fan club starts mobilizing. Led by the chic Shion, these ladies are serious fans who won\'t let anyone mess with their band. But the fan club has it out for Misato, a maverick fan who has gotten too close to Nana. What will they say when they find out Misato is applying for a job with Blast?!',4),('Nana, Vol. 15 - Nana',12,2009,2,200,9,9781421523743,3999,7,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nOne of the tabloids hounding Blast and Trapnest has photos that make it look like Reira and Ren are having an affair. With Nana and Ren’s engagement recently made public, the photos could spell doom for both bands. Takumi’s willing to do whatever it takes to save his band, but how will it affect Hachi and the happily ever after she’s still hoping for?',4),('Nana, Vol. 16 - Nana',12,2009,2,264,9,9781421523750,3999,10,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nBlast is at the top of the charts, and the band is making all kinds of P.R. appearances. Nana just wants to sing though, and all the marketing is starting to wear on her. A party planned for the loyal fans might be just what she needs to cheer her up. But there are secrets about her past lurking in Osaka, and the magazine Search Weekly is determined to bring them to light!',4),('Nana, Vol. 17 - Nana',12,2009,2,200,9,9781421523767,3999,21,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nEver since she got engaged to Takumi and moved out of apartment 707, Hachi has felt like she\'s slipping out of Nana\'s life. When the tabloids start digging up Nana\'s troubled family history, Hachi tries to step in and take care of things. But the price for bringing down Blast keeps going up. Will Hachi\'s good intentions just make things worse?!',4),('Nana, Vol. 18 - Nana',12,2009,2,256,9,9781421526706,3999,13,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nThings aren\'t looking good for Blast. Shin, under extreme stress from the band\'s rising success and his relationship with Reira, seeks out reconciliation wherever he can. Reestablishing ties with his own family turns out to be a horrible failure, and before he can connect Nana with her unknown little sister, Shin gets arrested! Is this the end of Blast?!',4),('Nana, Vol. 19 - Nana',12,2009,2,194,9,9781421526713,3999,3,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nThe tabloid feeding frenzy has finally brought Blast down, but Nana is determined to keep hope alive. She\'s going to take a gig as a solo artist and even accept acting jobs she has no interest in. As long as she keeps herself in the spotlight, she knows there\'s a chance Blast can make a comeback. But while all eyes are on Nana, what\'s happening to her friends in the background?!',4),('Nana, Vol. 20 - Nana',12,2010,2,194,9,9781421530758,3999,9,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nRen\'s drug use is spiraling out of control and he doesn\'t want to drag Trapnest down with him. Neither Takumi nor Reira are willing to let Ren quit the band, and both do their best to give him the time he needs to get it together. But Ren isn\'t sure this is something he can handle on his own. Will he turn to Nana for help, or will their strained relationship make him try to face his demons alone?',4),('Nana, Vol. 21 - Nana',12,2010,2,192,9,9781421533087,3999,18,11,1,'A chance meeting on a train to Tokyo sends two girls named Nana on a collision course with destiny!\r\n\r\nNana \"Hachi\" Komatsu hopes that moving to Tokyo will help her make a clean start and leave her capricious love life behind her. Nana Osaki, who arrives in the city at the same time, has plans to score big in the world of rock\'n\'roll. Although these two young women come from different backgrounds, they quickly become best friends in a whirlwind world of sex, music, fashion, gossip and all-night parties!\r\n\r\nTragedy strikes as the Search Weekly team takes their snooping too far! Hounded to the limit by remorseless reporters, Ren spins his car off the icy road in a horrible accident that will change the course of everyone\'s future...',4),('Edgar Allen Poe: Classic Stories - Barnes & Noble Flexibound Editions',19,2018,2,215,9,9781435166189,6900,2,16,1,'Edgar Allan Poe was a master of the tale of psychological horror and the author of what is considered the first modern detective story. This anthology gathers more than 20 of Poe’s groundbreaking tales of the macabre, among them “The Tell-Tale Heart,” “The Masque of the Red Death,” and “The Fall of the House of Usher.” It also includes his trilogy of stories featuring detective C. Auguste Dupin: “The Murders in the Rue Morgue,” “The Mystery of Marie Rôget,” and “The Purloined Letter.”',NULL),('Band Of Brothers',20,2017,2,346,9,9781471170058,4999,15,12,1,'**THE INTERNATIONAL BESTSELLER**\n\nForeword by Tom Hanks.\n \nThe book that inspired Steven Spielberg’s acclaimed TV series, and its sequel, Masters of the Air. \n \nIn Band of Brothers, Stephen E. Ambrose pays tribute to the men of Easy Company, a crack rifle company in the US Army. From their rigorous training in Georgia in 1942 to the dangerous parachute landings on D-Day and their triumphant capture of Hitler’s ‘Eagle’s Nest’ in Berchtesgaden. Ambrose tells the story of this remarkable company. Repeatedly sent on the toughest missions, these brave men fought, went hungry, froze and died in the service of their country. Celebrating the 25th anniversary since the original publication, this reissue contains a new foreword from Tom Hanks who was an executive producer on the award-winning HBO series.\n \nA tale of heroic adventures and soul-shattering confrontations, Band of Brothers brings back to life, as only Stephen E. Ambrose can, the profound ties of brotherhood forged in the barracks and on the battlefields.\n \n‘History boldly told and elegantly written . . . Gripping’ Wall Street Journal\n \n‘Ambrose proves once again he is a masterful historian . . . spellbinding’ People',NULL),('Borzoi - Comprehensive Owner\'s Guide (Hardback)',2,2006,2,155,7,9781593783044,7000,12,6,1,'He\'s amazing an white reason for',NULL),('Fate/grand Order -mortalis:stella- 1 (manga)',14,2023,2,217,6,9781632368843,6800,11,11,1,'The official manga adaptation of one of the most popular mobile games in the world! Dive into the time-traveling fantasy story that has enthralled millions! Fans, return to where it all began - 2004 A.D., the Fuyuki Singularity. The story of FGO has never looked better. From 28, the artist of the Tales of Zestiria manga!',4),('Fate/Grand Order -mortalis:stella- 2 (Manga) - Fate/Grand Order (Manga) 2',14,2023,2,205,6,9781632369079,7000,12,11,1,'One of the most popular mobile games in the world makes its long-awaited return with Vol. 2! Continue the time-traveling fantasy story that has enthralled millions, in a new adaptation from 28, the artist behind Tales of Zestiria!\nA NEW GRAND ORDER\nThe year is 2016, and glitches found in humanity\'s past threaten the sustainability of its future. The Chaldea Security Organization-tasked with preserving human history for as long and as strongly as possible-has developed a new method of time travel to repair these events, stabilizing humanity\'s future. But when an unknown threat pushes mankind to the brink of extinction, young recruits Mash Kyrielight and Ritsuka Fujimaru find themselves at the helm of the rescue mission: Obtain the Holy Grail in a face off against fate itself...\nThe official adaptation of the 9 phenomenon that has become one of the most popular mobile games in the world!',4),('Fate/Grand Order -mortalis:stella- 3 (Manga) - Fate/Grand Order (Manga) 3',14,2023,2,208,6,9781646513604,6700,13,11,1,'The year is 2016, and glitches found in humanity\'s past threaten the sustainability of its future. The Chaldea Security Organization-tasked with preserving human history for as long and as strongly as possible-has developed a new method of time travel to repair these events, stabilizing humanity\'s future. But when an unknown threat pushes mankind to the brink of extinction, young recruits Mash Kyrielight and Ritsuka Fujimaru find themselves at the helm of the rescue mission: Obtain the Holy Grail in a face off against fate itself...',4),('Persona 4 Volume 8 Volume 8 - Persona 4',13,2025,2,165,5,9781772940763,4350,14,11,1,'Rise turns the Investigation Team into a music band! …no, really! It’s Yosuke on guitar! Yukiko on saxophone! Teddie on bongos! It’s a symphonic scheme to help save Junes from financial disaster! Based on the popular Persona 4 video game!',4),('Persona 3 Volume 9 Volume 9 - Persona 3',13,2025,2,170,7,9781772940800,4674,23,11,1,'In the wake of a miraculous happening, it becomes apparent that hope lives on. There is a reason to go on fighting. The destruction of the Dark Hour may erase all memories of their days fighting together... but they will not forget.',4),('Persona 3 Volume 11 Volume 11 - Persona 3',13,2025,2,154,7,9781772940824,4532,12,11,1,'The final chapter of Persona 3! Nyx\'s influence is breaking down the barrier between the Dark Hour and reality. Only the Specialized Extracurricular Execution Squad stand in the way of the end of everything.',4),('Persona 4 Volume 9 Volume 9 - Persona 4',13,2025,2,186,7,9781772940886,3565,21,11,1,'The school festivities continue as the gang participates in the Miss Yasogami Contest – a beauty pageant for the girls, and a drag queen competition for the boys! It’s a golden opportunity for fun in the latest volume of the Persona 4 manga!',4),('Persona 4 Volume 10 Volume 10 - Persona 4',13,2025,2,180,5,9781772940893,4500,12,11,1,'Detective Dojima has been hospitalized, while young Nanako has been kidnapped to the TV World. Soji leads the investigation team on an urgent mission to save his smallest family member. Based the Persona 4 video game!',4),('Persona 4 Volume 12 Volume 12 - Persona 4',13,2025,2,165,5,9781772941333,5000,13,11,1,'The true murderer has been revealed, and the Investigation Team must return to the Midnight Channel to finally bring the case to an end. Based the Persona 4 video game!',4),('Persona 4 Arena Volume 1 Volume 1 - Persona 4 Arena',13,2025,2,143,7,9781772942521,4353,12,11,1,'The casts of PERSONA 3 and PERSONA 4 collide!\n\nA dormant anti-shadow suppression weapon named Labrys has been stolen! Mitsuru Kirijo and Aigis begin investigating its whereabouts. Meanwhile Yu Narukami returns to Inaba to reunite with his friends, the Investigation Team. What he finds waiting for him there is a strange fighting tournament held inside the TV World!',4),('Persona 4 Arena Volume 2 Volume 2 - Persona 4 Arena',13,2025,2,165,7,9781772942538,4500,21,11,1,'The casts of PERSONA 3 and PERSONA 4 collide!\n\nSomeone has stolen the anti-shadow suppression weapon named Labrys, and the trail leads into the TV World. There, all the persona users on the chase are forced to participate in the strange \"P-1 Grand Prix\" tournament. It\'s Aigis VS Kanji, and Yosuke VS Chie! Who will walk away in the end?!',4),('Persona 4 Arena Volume 3 Volume 3 - Persona 4 Arena',13,2025,2,163,7,9781772942545,5000,67,11,1,'The casts of PERSONA 3 and PERSONA 4 collide!\n\nThe P-1 Grand Prix reaches its climax! Though it hurt them to fight against their friends, both physically and emotionally, the Investigation Team slowly gets closer to the truth. What shocking secrets are hidden in the stolen Labrys\' past?! And how will the P-1 Grand Prix end?!',4),('Persona 4 Arena Ultimax Volume 1 Volume 1 - Persona 4 Arena Ultimax',13,2025,2,156,7,9781772942552,4678,32,11,1,'The action continues for the united casts of PERSONA 3 and PERSONA 4!\n\nIt began two months after the end of 3\' smash hit RPG Persona 4, when the Investigation Team was promptly swept up in a strange fighting tournament run by the mysterious General Teddie. After a long series of vicious battles the Team defeated the mastermind. But the peace hasn\'t lasted long! General Teddie returns and proclaims the start of the P-1 Climax! Then there\'s the mysterious boy Sho Minazuki, and even Tohru Adachi joins the tournament. Where will the story go next?!',4),('Persona 4 Arena Ultimax Volume 2 Volume 2 - Persona 4 Arena Ultimax',13,2025,2,176,7,9781772942569,2343,2,11,1,'The action continues for the united casts of PERSONA 3 and PERSONA 4!\n\nThe mysterious General Teddie has returned, and he drags the Investigation Team into a new tournament; the P-1 Climax! With no way to back out, they have no choice but to keep winning or the world will be destroyed! With the fate of several of his friends unknown, Yu breaches the enemy base, learning the secrets of Sho Minazuki, and the truth behind the vicious death matches.',4),('Persona 4 Arena Ultimax Volume 3 Volume 3 - Persona 4 Arena Ultimax',13,2025,2,176,7,9781772942576,3787,12,11,1,'The action continues for the united casts of PERSONA 3 and PERSONA 4!\n\nThe Kingpin of Steel rages! The Queen of Executions advances! The Cabbage Cop smirks! While some of his teammates are still missing, Yu confronts Sho and meets the other \"Sho Minazuki\" living inside Sho\'s mind. Meanwhile, Tohru Adachi discovers the terrifying reason that he was invited to the P-1 Climax!',4),('Persona 4 Arena Ultimax Volume 4 Volume 4 - Persona 4 Arena Ultimax',13,2025,2,154,7,9781772942583,2345,12,11,1,'The action continues for the united casts of PERSONA 3 and PERSONA 4!\n\nYu Narukami, who faces off against the true mastermind behind the tournament… Tohru Adachi, whose life was in danger thanks to a hidden power he held... and Shu Minazuki, who desperately wanted to forge a bond with his foster father Shuji Ikutsuki. When these three meet at the final battlefield, the full truth behind the P-1 Climax will come to light!',4),('Six of Crows - Book 1 ',11,2016,2,494,8,9781780622286,6165,42,13,1,'Criminal prodigy Kaz Brekker is offered a chance at a deadly heist that could make him rich beyond his wildest dreams - but he can\'t pull it off alone.\r\n\r\nA convict with a thirst for revenge.\r\nA sharpshooter who can\'t walk away from a wager.\r\nA runaway with a privileged past.\r\nA spy known as the Wraith.\r\nA Heartrender using her magic to survive the slums.\r\nA thief with a gift for unlikely escapes.\r\n\r\nSix dangerous outcasts. One impossible heist.\r\n\r\nKaz\'s crew is the only thing that might stand between the world and destruction - if they don\'t kill each other first.',NULL),('Crooked Kingdom - Six of Crows Book 2 ',11,2017,2,536,8,9781780622316,6165,43,13,1,'Welcome to the world of the Grisha.\r\n\r\nKaz Brekker and his crew of deadly outcasts have just pulled off a heist so daring even they didn\'t think they\'d survive. But instead of divvying up a fat reward, they\'re right back to fighting for their lives.\r\n\r\nDouble-crossed and badly weakened, the crew is low on resources, allies, and hope. As powerful forces from around the world descend on Ketterdam to root out the secrets of the dangerous drug known as jurda parem, old rivals and new enemies emerge to challenge Kaz\'s cunning and test the team\'s fragile loyalties.\r\n\r\nA war will be waged on the city\'s dark and twisting streets - a battle for revenge and redemption that will decide the fate of the Grisha world.',NULL),('Persona: The Official Cookbook',23,2025,2,144,7,9781835414835,6999,4,1,1,'It\'s time to find your true self-with food! Delve into heartwarming, culinary moments from the Persona series, from Fuuka\'s cooking club to the booths of Cafe Leblanc!\n\nDo you have the stats to take on the Rainy Day Mega Beef Bowl Challenge? Are you prepared to face the Cosmo Tower Burger? Find out with Persona: The Official Cookbook, a collection of iconic recipes from across the Persona franchise. From Tatsumi Port Island to Inaba to Tokyo, experience the incredible meals that bring the series\' beloved characters closer and strengthen them for the fight ahead.\n\nExperience your favorite moments captured in mouthwatering recipes-try the Mystery Food X concocted by Yukiko and Chie, gift and eat Valentine\'s Day chocolates, and learn to create the Master Curry and Master Coffee from the beloved Cafe Leblanc!\n\nWith step-by-step instructions and stunning photography, these recipes will boost your skills in no time, preparing you to take on whatever the collective unconscious of humanity has in store for you!',4),('Persona 4 Volume 1 Volume 1 - Persona 4',13,2025,2,160,5,9781927925577,3999,15,11,1,'Following a string of mysterious murders, transfer student Soji Seta and his\nnew friends have followed the legend of the Midnight Channel and found\n\nthemselves pulled into another dimension! In this twisted TV world, a\n\nperson’s innermost secrets materialize as a Shadow — an entity that\n\nmay become a powerful ally, or something much worse...\n\nBased on the popular Persona 4 video game!\n',4),('Persona 4 Volume 2 Volume 2 - Persona 4',13,2025,2,194,5,9781927925669,4600,15,11,1,'Soji, Yosuke, and Chie are hot on the trail of the Inabi kidnapping victims... which now include Chie\'s best friend Yukiko! Now, with the help of their strange new ally Teddie, our heroes venture into the TV World again to get Yukiko back. Based on the popular Persona 4 video game!',4),('Persona 4 Volume 3 Volume 3 - Persona 4',13,2025,2,175,7,9781927925799,3567,43,11,1,'Teen brawler Kanji Tatsumi barrels onto the scene! Will this rough & tumble juvenile delinquent help or hinder the search for the truth about the Midnight Channel? Based on the popular Persona 4 video game!',4),('Persona 4 Volume 4 Volume 4 - Persona 4',13,2025,2,170,5,9781927925812,4000,3,11,1,'Superstar teen idol Rise Kujikawa escapes to Inaba for a much-needed break from the limelight, and the usually sleepy town is caught in the grip of celebrity fever! But when Rise suddenly appears on the Midnight Channel and goes missing soon thereafter, it’s up to Soji, Chie, and the rest of the crew to rescue her from the TV World and figure out what – if anything – Rise shares in common with the previous kidnapping victims. Based on the popular Persona 4 video game!',4),('Persona 4 Volume 5 Volume 5 - Persona 4',13,2025,2,167,5,9781927925829,4700,12,11,1,'With Rise rescued and now in possession of her own Persona, Soji and friends welcome a powerful new ally into the fold. But just as things are looking up, the body of Inaba’s latest murder victim is discovered – and the victim’s identity turns our heroes’ investigation upside-down. Meanwhile, Teddie does some much-needed soul searching… and what he finds is much more than anyone bear-gained for! Based on the popular Persona 4 video game!',4),('Persona 4 Volume 6 Volume 6 - Persona 4',13,2025,2,167,5,9781927925836,4500,7,11,1,'With the murderer Mitsuo Kubo apprehended and the case seemingly closed, life in Inaba returns to normal just in time for Soji and his friends to enjoy a well-earned summer vacation. But moving on is proving especially difficult for Naoki Konishi, for whom time has stood still ever since his sister Saki became the second murder victim. Can he and Yosuke find the peace they’re seeking, and is Soji and friends’ investigation truly over? Based on the popular Persona 4 video game!',4),('Persona 3 Volume 1 Volume 1 - Persona 3',13,2025,2,162,2,9781927925850,3999,343,11,1,'Between one day and the next, inserting itself into reality at midnight, sits the Dark Hour. Few know about this special time that separates humans from the dangerous creatures known as Shadows. It is here that a group of students finds the ability to summon their inner selves - their \"Personas\" - to do battle with the Shadows before they can consume the minds of humanity.',4),('Persona 3 Volume 2 Volume 2 - Persona 3',13,2025,2,145,7,9781927925867,4564,11,11,1,'Life isn’t easy when you’re a transfer student – just ask Minato Arisato, Gekkoukan High School’s newest transfer student. Strangers and unfamiliar scenery aside, Minato also has to contend with the fact that his school transforms into a Shadow-filled tower called Tartarus every night during the Dark Hour! Minato and two of his new friends – Yukari and Junpei – set out to investigate Tartarus to see what they can learn about this phenomenon, but can three high school students with little to no combat experience possibly survive the tower’s horrors?',4),('Persona 3 Volume 3 Volume 3 - Persona 3',13,2025,2,165,7,9781927925874,4543,43,11,1,'With the formation of the Specialized Extracurricular Execution Squad (S.E.E.S.), Minato, Mitsuru, Akihiko, and the rest have taken it upon themselves to combat the threat that Tartarus and the Shadows therein represent. When they learn that the soft-spoken Fuuka may have become trapped in Tartarus during the Dark Hour, they mount a desperate rescue attempt – but will they reach Fuuka in time to save her?',4),('Persona 3 Volume 4 Volume 4 - Persona 3',13,2025,2,154,7,9781927925881,5356,32,11,1,'This next thrilling volume of the Persona 3 manga series is all about revelations as the intrepid members of S.E.E.S. visit the Kirijou family cottage and learn some surprising truths from Mitsuru’s father about the events surrounding Tartarus, the Dark Hour, and their own continuing battle against the encroaching Shadows. The weight of these truths proves especially heavy for Yukari and Mitsuru, but if they can bear this burden, their shared struggle may give rise to new power…',4),('Persona 3 Volume 5 Volume 5 - Persona 3',13,2025,2,183,7,9781927925898,2342,12,11,1,'If you thought Shadows were the only enemies S.E.E.S. would ever have to fight, think again! It’s an all-out battle between Persona users as S.E.E.S. comes into direct conflict with Strega, an extremist group using the Dark Hour for their own personal gain. Even with Akihiko’s old friend Shinjiro and the surprisingly mature elementary school student Ken Amada as S.E.E.S.’ newest recruits, Minato and friends are in for their toughest battle yet!',4),('Persona 3 Volume 6 Volume 6 - Persona 3',13,2025,2,165,7,9781927925904,4654,5,11,1,'This next thrilling volume of the Persona 3 manga series is all about revelations as the intrepid members of S.E.E.S. visit the Kirijou family cottage and learn some surprising truths from Mitsuru’s father about the events surrounding Tartarus, the Dark Hour, and their own continuing battle against the encroaching Shadows. The weight of these truths proves especially heavy for Yukari and Mitsuru, but if they can bear this burden, their shared struggle may give rise to new power…',4),('Kaguya-sama: Love Is War, Vol. 1 - Kaguya-sama: Love is War',12,2024,2,216,2,9781974700301,5476,12,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nAs leaders of their prestigious academy’s student council, Kaguya and Miyuki are the elite of the elite! But it’s lonely at the top… Luckily for them, they’ve fallen in love! There’s just one problem—they both have too much pride to admit it. And so begins the daily scheming to get the object of their affection to confess their romantic feelings first…',4),('Kaguya-sama: Love Is War, Vol. 2 - Kaguya-sama: Love is War',12,2024,2,210,2,9781974700318,4353,11,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill a mysterious love letter to Kaguya make Miyuki jealous? Is drinking from a coffee cup with Kaguya’s lipstick on the rim an indirect kiss? How will Miyuki react when Kaguya says she’s “done it” before? Then, Miyuki’s phobia is revealed, the student council VP of Shuchiin Academy’s sister school in France displays epic Gallic rudeness, and the student council tries on some costumes… Nobody can resist cat ears.',4),('Kaguya-sama: Love Is War, Vol. 3 - Kaguya-sama: Love is War',12,2024,2,209,2,9781974700325,3556,1,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya and Miyuki share the shelter of an umbrella in a storm? Is carrying a knife dripping with blood proof that Kaguya is trying to kill a member of the student council? How will Kaguya react when Chika introduces her to potty humor? Then, Chika must intervene when Miyuki dispenses bad advice on a topic he knows nothing about, Miyuki tries to develop his kinesthetic intelligence, and Kaguya and her personal assistant play a practical joke on Miyuki that has dire consequences.\n\nCaffeine is required drinking.',4),('Kaguya-sama: Love Is War, Vol. 4 - Kaguya-sama: Love is War',12,2024,2,214,2,9781974700493,5787,32,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya and Miyuki outsmart a psychological test designed to reveal their true feelings? Is spoon-feeding each other cake the way to each other’s hearts? Then, Miyuki visits Kaguya’s home for the first time, but she is too sick to enjoy it. Kaguya tries to befriend Miyuki’s little sister, but Chika has beaten her to the punch. And summer vacation arrives, but the student council still hasn’t agreed on a destination.\n\nFireworks are supposed to be romantic.',4),('Kaguya-sama: Love Is War, Vol. 5 - Kaguya-sama: Love is War',12,2024,2,267,2,9781974700509,6700,41,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya and Miyuki find a way to see each other sooner rather than later over summer vacation? And is tweeting really an effective way to communicate with your crush? Then, Kaguya’s overprotective staff try to prevent her from going to the fireworks festival with the rest of the student council. Miyuki and Kaguya both try to find a way to enroll in the same elective class. And someone tries to celebrate someone else’s birthday with style!\n\nSome people believe the stars determine your compatibility.',4),('Kaguya-sama: Love Is War, Vol. 6 - Kaguya-sama: Love is War',12,2024,2,231,2,9781974701384,5000,4,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya figure out what Miyuki wants for his birthday plus present him with the perfect cake? Is treasurer Yu flunking out of school and beyond help…or can the one he fears most get him back on track? Then the romantic autumn moon-viewing festival leads to some stellar night moves. The student council plays a role-playing game in which at least one member doesn’t get to play out their fantasy. Ai assumes an alter ego to prove she can get Miyuki to fall in love with her in just one day. And Miyuki’s time as student council president is up!\n\nWe play many roles in life.',4),('Kaguya-sama: Love Is War, Vol. 7 - Kaguya-sama: Love is War',12,2024,2,215,2,9781974701391,5699,9,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Miyuki get reelected as student council president? Is newcomer Miko Ino going to be serious competition…or a school laughingstock? Then, Kaguya and Miyuki draw each other in art class (results may vary). Yu wants to do the right thing. Miyuki catches up on sleep, which has an unexpected effect on his attractiveness to women—especially Kaguya. And Kaguya anxiously awaits a certain invitation.\n\nDoes underwear make the man?',4),('Kaguya-sama: Love Is War, Vol. 8 - Kaguya-sama: Love is War',12,2024,2,275,2,9781974704408,5999,13,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Miyuki’s hormones keep him loyal to Kaguya or lead him astray? Meanwhile, Miko is interpreting everything she observes in the student council as risqué. Then, a shojo manga makes everyone romance crazy. Somebody actually, finally asks somebody out! And Kaguya and Miyuki accidentally get locked inside a room together…\n\nLovesick: figure of speech or actual ailment?',4),('Kaguya-sama: Love Is War, Vol. 9 - Kaguya-sama: Love is War',12,2024,2,250,2,9781974705092,6500,2,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Chika agree to train Miyuki one more time to make up for yet another of his surprising deficiencies? Then, Miyuki’s sister and father meddle in his (mostly hypothetical) love life. Rumors that plague Yu have serious personal and academic consequences. The much-anticipated, much-dreaded Sports Festival finally arrives! And Chika dreams up a new game for the student council to play together—with literally explosive results.\n\nWho cares what other people think?',4),('Kaguya-sama: Love Is War, Vol. 10 - Kaguya-sama: Love is War',12,2024,2,255,2,9781974706631,6700,67,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Ai prove to Kaguya that she can win Miyuki’s heart after all…while singing karaoke? Then the student council engages in some competitive cooking. Yu tries to spare Miko the embarrassment of the others discovering that she likes to listen to sexy voice actors whisper sweet nothings. And Kaguya declines to participate in a group date involving Miyuki—with a predictable impact on her mental stability.\n\nAt some point, you’ve got to upgrade your phone.',4),('Kaguya-sama: Love Is War, Vol. 11 - Kaguya-sama: Love is War',12,2024,2,217,2,9781974707799,5000,12,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nCan Miyuki and Kaguya help Yu escape the aggro of all his female classmates, let alone win the favor of the girl he’s crushing on? Then, it’s Miyuki who is teaching Chika a new skill for a change. Kaguya faces the temptations and pitfalls of her new smartphone and social media. Ai takes on yet another secret identity. And the student council’s parents cross paths at school conferences where they must decide what colleges their children will apply to.\n\nWhen you make plans, the gods laugh.',4),('Kaguya-sama: Love Is War, Vol. 12 - Kaguya-sama: Love is War',12,2024,2,250,2,9781974709571,5600,1,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Miyuki ever admit to his insignificant but seemingly infinite lack of nonacademic talents? And what of the other student council members? Are any of them willing to see themselves objectively? Then it’s time for the school culture festival, which harkens back to a legend of ancient personal sacrifice that inspires the present-day students…symbolically, at least. Plus, a student council arm wrestling competition, balloon animals and a flashback episode to Miyuki’s first awkward weeks as an outsider at Shuchiin High.\n\nCosplay makes the woman.',4),('Kaguya-sama: Love Is War, Vol. 13 - Kaguya-sama: Love is War',12,2024,2,270,2,9781974710713,5699,1,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Yu make a confession of love? Who would date someone who is both an emo gamer and a former school pariah…? Meanwhile, someone is ready to confess her love to Miyuki—and it’s not Kaguya! Then Miko sabotages a romantic tour of a haunted house, Miyuki reveals some unexpected nonacademic skills, Kaguya accidentally dispenses good advice and a fortune-teller foretells an ominous date for our pride-crossed lovers—no, not that kind of date. Plus, heart-themed key rings, cookies, takoyaki and balloons!\n\nBut nobody turns down Stanford.',4),('Persona 5, Vol. 1 - Persona 5',12,2024,2,254,9,9781974711758,5999,12,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of phantom thieves, saving people from the twisted desires of those around them.\n\nAkira Kurusu thought he was doing the right thing when he rescued a woman who was being attacked. Expelled from his school and sent away from home, he is reenrolled in Shujin Academy on probation. Trouble finds him again on his first day when he comes across delinquent Ryuji Sakamoto and the two somehow stumble into a castle in an alternate reality. Caught by the castle’s king, the schoolteacher Kamoshida, Akira discovers his will to rebel and awakens the power of his Persona!',4),('Persona 5, Vol. 2',12,2024,2,195,9,9781974711970,5999,5,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nVolleyball coach Suguru Kamoshida\'s evil acts drive one of Akira\'s classmates to attempt suicide, so Akira and Ryuji resolve to bring him to justice! But to do that, they must infiltrate his palace and steal the treasure within to change his heart! With their Personas—avatars of their will to rebel—as their weapons, Akira and his friends make their way through Kamoshida\'s palace. But before they can make off with the treasure, Shadow Kamoshida finds them! Do Akira and the others stand any chance against Shadow Kamoshida\'s true might?!',4),('Persona 5, Vol. 3',12,2024,2,198,9,9781974714698,5999,12,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nAfter successfully changing Kamoshida\'s heart, Akira and his friends decide to continue operating as the Phantom Thieves. Not long after, they meet famous Japanese artist Ichiryusai Madarame and his student Yusuke Kitagawa. The Phantom Thieves hear rumors that Madarame might be up to some shady stuff. Ann accepts Yusuke\'s request to model for him in the hopes that she can get some information out of him, but Yusuke refuses to hear it! Will the Phantom Thieves be able to expose Madarame\'s crimes? And what is the startling truth about Yusuke\'s past?',4),('Persona 5, Vol. 4',12,2024,2,196,9,9781974714704,5999,4,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nAkira and the gang think they’ve stolen Madarame’s treasure, but before they can escape the palace, its master—Shadow Madarame himself— catches up to them and reveals the true story behind Yusuke’s mother’s death! Back in the real world, sinister agents have begun to investigate the strange events surrounding the Phantom Thieves. Will Akira and the gang be able to stay one step ahead of them?!',4),('Persona 5, Vol. 5',12,2024,2,200,9,9781974714711,5999,4,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nFirst, the Phantom Thieves reformed twisted schoolteacher Suguru Kamoshida. Next, they succeeded in changing the heart of their second target, the master artist Ichiryusai Madarame. But back in the real world, Shujin Academy student council president Makoto Nijima is starting to suspect that Akira and his friends may be more than just average students. Meanwhile, a criminal organization operating in Shibuya has started to target high school students in a new, devious scam. Will the Phantom Thieves be able to prove they’re the good guys while keeping their identities a secret?!',4),('Kaguya-sama: Love Is War, Vol. 14 - Kaguya-sama: Love is War',12,2024,2,255,2,9781974714728,5999,7,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill it be Miyuki or Kaguya who finally breaks down and confesses their love for the other? Will the love confession be terribly bungled or epically orchestrated? And will the recipient respond appropriately, insanely, or in kind? While these questions will have answers, the romantic quandaries of the rest of the members of the student council will raise a whole new set of questions…\n\nThree months is a long time.',4),('Kaguya-sama: Love Is War, Vol. 15 - Kaguya-sama: Love is War',12,2024,2,216,2,9781974714735,5400,2,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nTurns out confessing your feelings is the easy part of a romantic relationship… Now Kaguya and Miyuki have to figure out how to behave in a relationship. Kaguya retreats behind the ice shield she built to protect herself years ago. Miyuki believes only an ideal version of himself is worthy of love. Ai/Haski, as usual, is caught in the middle. Will our two not-star-crossed lovers ever learn to let go and just be themselves…?\n\nFirst, you have to love yourself.',4),('Kaguya-sama: Love Is War, Vol. 16 - Kaguya-sama: Love is War',12,2024,2,219,2,9781974717101,5999,12,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya and Miyuki ever go beyond making out and get around to officially going out?! What game is Miko playing when she interferes with Yu and Tsubame’s fledgling intimacy? Meanwhile, Kaguya tries to choose the perfect gift for Miyuki, Yu tries to choose the perfect gift for Tsubame, and Miyuki’s dad goes into the fortune-telling business!\n\nIndia is the land of spiritual enlightenment.',4),('Kaguya-sama: Love Is War, Vol. 17 - Kaguya-sama: Love is War',12,2024,2,216,2,9781974718740,4999,8,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya tell her family or even her friends that she’s dating Miyuki? Why is Chika pretending to be everyone’s girlfriend while dressed in a bald wig? Hapless Yu gets romantic advice from recently dumped Kazeno, which he passes on to naive Miyuki. Then, semi-repressed Nagisa attempts to school repressed Kaguya. And Kaguya shares (usually sensible) Ai’s theories about men with Maki, who attempts to verify them with flustered Miyuki and Yu. Basically, Shuchiin Academy suffers from a bad case of the blind leading the blind.\n\nYou can’t learn about sex from porn.',4),('Persona 5, Vol. 6',12,2024,2,193,9,9781974719396,5999,2,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nThe Phantom Thieves’ next target is Junya Kaneshiro, a mafia boss scamming high school students in Shibuya. Akira and his friends manage to fight their way through the tough security forces of Kaneshiro’s palace, but the gangster still has some dirty tricks up his sleeve! Will the Phantom Thieves be able to help Makoto get out of Kaneshiro’s clutches? Or will she end up in debt to him forever?!',4),('Kaguya-sama: Love Is War, Vol. 18 - Kaguya-sama: Love is War',12,2024,2,265,2,9781974721009,6000,15,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Ai leave her post as Kaguya’s personal assistant and confidant?! Meanwhile, Kaguya and Yu go to great lengths to prevent their not-so-dark secrets from getting out. A sports tournament provides yet another opportunity for the gang to desperately attempt to impress each other with their athletic prowess—or coaching skills. And then it’s finally time for an educational school trip! Of course all the students view this as just an opportunity to hang out with or spy on the objects of their attraction…\n\nWet hair is better than a wet T-shirt.',4),('Kaguya-sama: Love Is War, Vol. 19 - Kaguya-sama: Love is War',12,2024,2,260,2,9781974722860,5989,12,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill this romantic comedy turn into a thriller? Two warring factions in Kaguya’s family are trying to force her personal assistant, Ai, to abandon Kaguya and serve them. While Miyuki tries to save Ai from getting kidnapped, she sends an urgent message to Kaguya to meet her at the place where their relationship began—but Kaguya can’t figure out where that is! Meanwhile, as Yu and Tsubame grow closer, Miko grows more jealous, and student council factions clash over whom Yu should date!\n\nYou’re never too old to become a YouTube sensation.',4),('Persona 5, Vol. 7',12,2024,2,205,9,9781974723003,5999,5,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nThe Phantom Thieves are celebrating successfully reforming mob boss Kaneshiro when they’re suddenly called out by the international hacker group Medjed! Caught off guard, Akira is further confused when he receives a mysterious message from a person claiming to have knowledge of Medjed, who offers the Phantom Thieves a special deal to help them out with their predicament…',4),('Kaguya-sama: Love Is War, Vol. 20 - Kaguya-sama: Love is War',12,2024,2,210,2,9781974724031,5656,12,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Yu manage to raise his academic ranking this exam period? Unfortunately, his gaming addiction may have an impact not only on his grades but also on how Tsubame views him. Hopefully the diabolical plan concocted by Kaguya, his ruthless academic coach, will keep him from failing. On the other hand, someone else gets unexpectedly low marks this exam period! Then, on Valentine’s Day, which of the gang will give or receive romantic chocolates, friendship chocolates or obligatory chocolates…?\n\nFight rumors with rumors.',4),('Kaguya-sama: Love Is War, Vol. 21 - Kaguya-sama: Love is War',12,2024,2,215,2,9781974725182,6500,12,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Yu be able to handle Tsubame’s answer to his love confession? Then, dropping by Miyuki’s home unannounced surprises Kaguya more than the Shiroganes. As Kaguya’s family interferes with her future plans, she becomes determined to break free of them, but first she must strike a deal with the devil!\n\nSeating arrangements matter.',4),('Persona 5, Vol. 8',12,2024,2,209,9,9781974728053,5999,12,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nThe worldwide cyberterrorism organization Medjed has targeted the Phantom Thieves, threatening to shut down all of Japan if they don’t reveal themselves! But Akira receives a message from the mysterious Alibaba, who has a special offer for the Phantom Thieves—steal a certain person’s heart, and they will take care of Medjed. But that person is none other than Sojiro Sakura’s adopted daughter, Futaba Sakura! With this wrench in their plans, will the Phantom Thieves be able to deliver in time?',4),('Kaguya-sama: Love Is War, Vol. 22 - Kaguya-sama: Love is War',12,2024,2,200,2,9781974728473,5678,2,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Miko’s budding closeness with Miyuki make other interested parties jealous? Then, entertaining a cat in the student council chambers leads to awkward complications. As the war between the Shinomiyas and the Shijos heats up, Kaguya’s new assistant and Mikado both fall under suspicion. And then Kaguya and Miyuki spend the night together…alone!\n\nHow do you know when you’re ready?',4),('Kaguya-sama: Love Is War, Vol. 23 - Kaguya-sama: Love is War',12,2024,2,250,2,9781974732180,5555,4,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Miyuki replace Chika in Kaguya’s heart? When dense Chika belatedly finds out they’re dating, she certainly thinks so. Then, Kaguya discovers an unexpected source of support in her battle against her family, Miko tries various approaches to get Yu to fall in love with her, and Kobachi turns out to be more complicated than she appears.\n\nSometimes, it’s good to play games with people.',4),('Persona 5, Vol. 9',12,2025,2,190,9,9781974734030,5999,7,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nThe battle for the treasure in Futaba’s palace is on! Things take a strange turn as Futaba appears in her own palace— something that shouldn’t even be possible! The truth behind her mother’s death is unraveled as the shackles guarding her memories loosen and the distortions weaken. But that truth only leads to even more mysteries…',4),('Kaguya-sama: Love Is War, Vol. 24 - Kaguya-sama: Love is War',12,2024,2,260,2,9781974734481,3999,14,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Miko and Kobachi ever make up and be friends again? It seems unlikely, especially when they learn they might be competing for the affections of the same boy! Then, Miyuki gets roped into running a school event, Yu needs a date to attend it, the volatile situation with the Shinomiya conglomerate heats up, and Kaguya…disappears!\n\nSometimes you can’t see what’s right in front of your face.',4),('Kaguya-sama: Love Is War, Vol. 25 - Kaguya-sama: Love is War',12,2024,2,265,2,9781974736324,6000,12,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya’s family force her to marry a man she doesn’t love in order to fulfill their political and financial ambitions? As the reign of Kaguya’s father approaches its end, the war of succession between her brothers heats up. Meanwhile, Ai gets a new assignment as a bodyguard, Yu and Miko get cozy on a couch, and…Miyuki accepts a hefty bribe?!\n\nFamily matters.',4),('Persona 5, Vol. 10',12,2025,2,206,9,9781974736980,5999,12,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nThe fun of a school trip fades when Akira and the others come home to the principal’s mysterious death and a sudden Phantom Thief popularity boom. Suddenly, Ryuji and Morgana have a big argument and Morgana leaves in a rage. The crew chases Morgana to a new palace where they find him along with a stranger calling herself the Beauty Thief. What’s her connection to the palace ruler?',4),('Kaguya-sama: Love Is War, Vol. 26 - Kaguya-sama: Love is War',12,2024,2,255,2,9781974738755,5400,56,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya’s friends be able to rescue her from the clutches of her ruthless family? Miyuki does his best to negotiate with Kaguya’s father for his daughter’s freedom to live and love as she chooses. But Miyuki isn’t the only one vying for Kaguya’s hand… Then, the rest of Kaguya’s friends—Chika, Ai, Yu, Miko, and Maki—use everything at their disposal to find and save her, from blackmail to electronic trackers to…skateboards?\n\nWhere there’s a will, there’s a way.',4),('Kaguya-sama: Love Is War, Vol. 27 - Kaguya-sama: Love is War',12,2024,2,220,2,9781974741052,5999,5,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill Kaguya get to the airport in time to say goodbye to Miyuki? First, she and an ally must make one last attempt to repair the rift between the Shinomiya and Shijo families. Then, Miyuki plots what to do with the leftover money from the bribe he received, Miko tries to bridge the distance between her and Yu when he goes abroad for summer break, and Chika leads everyone in one of her signature trauma-inducing games!\n\nWho knows when he’ll be back again.',4),('Persona 5, Vol. 11',12,2025,2,208,9,9781974741106,5999,1,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nAkira and his friends dive into the palace of Kunikazu Okumura, who is Haru’s father and the CEO of the Okumura Foods megacorp. Haru joins the Phantom Thieves, and the battle reaches its climax! Will Haru’s father be able to escape the chains of greed that bind him? Meanwhile, at school, Akira notices something odd about his classmate Kasumi Yoshizawa. Following her leads him to a mysterious palace…',4),('Kaguya-sama: Love Is War, Vol. 28 - Kaguya-sama: Love is War',12,2024,2,243,2,9781974743421,6000,15,11,1,'Two high school geniuses scheme to get the other to confess their love first.\n\nTwo geniuses. Two brains. Two hearts. One battle. Who will confess their love first…?!\n\nWill all our beloved characters get a happy ending? Maki is still trying to get over Tsubasa, Miko is running for student council president, and Chika wants a romantic partner of her own. Then, which couple will wage war to obtain a confession of love, and which will battle for a proposal of marriage…?\n\nIs love really war?',4),('Persona 5, Vol. 12',12,2025,2,210,9,9781974747009,5999,15,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nPraised as heroes of the people, the Phantom Thieves are at the peak of their popularity—that is, until the untimely, gruesome mental shutdown and death of Haru’s father, the CEO of Okumura Foods, during a live TV press conference. Popular sentiment quickly turns against the Phantom Thieves, decrying them as criminals and murderers. To play the role of model students, the group takes on running Shujin Academy’s culture festival, where they hope to invite detective Goro Akechi to their school and glean information from him. But this leads to a new, unexpected Phantom Thief joining the crew…',4),('Persona 5, Vol. 13',12,2025,2,199,9,9781974754885,5999,16,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nThe Phantom Thieves’ next target is none other than the prosecutor investigating their case—and Makoto’s big sister—Sae Nijima! In order to clear their names, they have no choice but to accept Akechi’s help in changing Sae’s heart. But they face one of their trickiest palaces yet—a casino built around cheating!',4),('Persona 5, Vol. 14',12,2025,2,210,9,9781974758173,5999,0,11,1,'Based on the popular video game, this manga’s phantom thieves will steal your heart!\n\nAfter being arrested and having to transfer to a new high school in Tokyo, Akira Kurusu is given the goal of rehabilitation and awakened to a new power—the power of one’s true self, a Persona. Using his Persona and the mysterious navigation app Mementos, Akira and his friends take on the role of Phantom Thieves, saving people from the twisted desires of those around them.\n\nAkira and his friends are up against their toughest foe yet—Sae Nijima. Her palace is a rigged casino where they must outcheat the cheater every step of the way. Their final challenge before reaching Sae is collecting 100,000 coins from the casino. The quickest way to achieve this is a battle arena—but of course, nothing is ever easy. Can Joker face off against a gauntlet of foes alone so they can reach Sae and her treasure, and change her heart?',4),('Viszlát, cukor és fehér liszt! ',32,2022,1,171,7,9786150108292,3990,18,20,1,'A szénhidrát nem az ördögtől való de egyáltalán nem mindegy, mikor, mennyit és milyet fogyasztunk belőle. A helytelen táplálkozás rontja a közérzetünket és teljesítőképességünket, ráadásul a rossz étkezési szokások miatt a lakosság felénél kimutatható az inzulinrezisztencia ez pedig már a cukorbetegség előszobája. Az ezzel összefüggő PCOS a magyar nők közel egyötödét érinti, és ez ma a meddőség legfőbb oka. Dietetikai szaktudása és széleskörű tapasztalatai révén Török Eszter olyan jól használható szakácskönyvet állított össze, amellyel könnyűvé válik az egészséges táplálkozás, a vércukorszint egyenletesen tartása, a megfelelő minőségű és mennyiségű szénhidrát bevitele. Az átgondolt és sokoldalú recepteknek köszönhetően az olvasónak már nem kell azon gondolkodnia, mit mivel párosítson össze, mert az egy főre jutó adag pontosan elegendő tápanyagot tartalmaz. A könyv másik nagy előnye az egyszerűség, mivel a fotókon látható adagok a ténylegesen elfogyasztandó mennyiséget mutatják, így a kitálalásánál sem kell külön lemérni az ételeket. A dietetikus szakember sok éve tervez már étrendeket, így garantáltan finom, változatos és egészséges alternatívát kínál mindazoknak, akik számára fontos a helyes táplálkozás.',7),('Ellenállhatatlan egészséges ételek - Cukormentes, rostban gazdag receptek',30,2023,1,192,7,9786150129631,6555,20,26,1,'Meglepő, de sokszor kapom visszajelzésként \"a pácienseimtől\", hogy az én szakácskönyvem az első, amiből tényleg főznek. Ha belegondolunk, gyakran csak megvásároljuk a szakácskönyveket, az elején belelapozunk, de utána csak a polcon díszelegnek, nem használjuk őket.\r\nEz a könyv valódi ételeket tartalmaz, valódi embereknek! Ebből tényleg lehet főzni! Nem a valóságtól elrugaszkodott recepteket akar bemutatni bonyolult technikákkal, hanem amiket egy hétköznapi háziasszony, vagy egy munkából hazatérő férfi is el tud készíteni a saját konyhájában. Ellenállhatatlan egészséges ételeket tartalmaz, amit bárki jóízűen elfogyasztana, hiszen finomak, de egyúttal egészséges\r\nalapanyagokból készülnek. A receptek összeállításánál fontos szempontom volt, hogy az étkezések után ne jelentkezzen kiugró vércukorszint és inzulintermelés. Az alapanyagok rostban gazdagok és hozzáadott cukrot nem tartalmaznak, így könyvem inzulinrezisztenciában vagy cukorbetegségben is külön ajánlott! A rostok hatására sokáig érezzük majd a jóllakottságot, nem leszünk fél óra múlva újra éhesek, így segítenek a fogyásban, energiát adnak a sportoláshoz. Dietetikusként emberek tízezreinek segítettem már a helyes táplálkozás alapelveinek megismerésében és a jó laboreredmények elérésében. Vallom, hogy mindez szélsőségektől mentesen is megvalósítható! Légy nyitott és lapozz bele a könyvbe, próbálj ki pár új ételt, ígérem nem fogsz csalódni!\r\n\r\nTörök Eszter dietetikus',7),('Babilónia ',15,2026,1,512,4,9786151040867,8091,10,8,1,'Meghalt a király! Éljen a királynő! Ókori Asszíria, Kr. e. 9. század. Egy olyan vidéken, ahol hírből sem ismerik a kegyelmet és a gyengédséget, nehéz sors vár egy rossz hírű anyától született, árván maradt kislányra. Szemiramisz azonban arról álmodozik, hogy származása ellenére olyan magasra emelkedik, amivel csak az istenek versenyezhetnek. Kalhu fellegvárának aranyozott folyosóin egy kedvetlen herceg sétál. Ninosz inkább könyvekkel és költészettel töltené a napjait, de arra született, hogy uralkodjon, és fivére meggyilkolása után el is foglalja a birodalom trónját. Hű tanácsadója és kormányzója, Onnesz sokkal inkább érti a kor kegyetlenségét, a két férfi mély barátsága pedig megingathatatlan. Legalábbis addig, amíg Szemiramisz a kormányzó hitveseként meg nem érkezik Kalhuba... Második regényében Costanza Casati briliánsan ötvözi a mítoszt az ókori történelemmel, hogy bemutassa az asszír birodalom egyetlen ismert női uralkodójának hatalomra jutását. A könyv lapjain egy letűnt világ intrikái szólítják meg az olvasót. Méltatások: Costanza Casati összegyűjtötte erről a rendkívüli nőről szóló történetek töredékeit, és magával ragadó stílusban alkotta újra a világát. - The Times Megható és elbűvölő történet. Casati Babilónia című regényével bebizonyította, hogy ő az egyik legtehetségesebb és legizgalmasabb történelmiregény-író. - Bea Fitzgerald, a Girl, Goddess, Queen - Pokolba a szerelemmel! című könyv szerzője',NULL),('Elit alakulat',15,2025,1,459,6,9786151100363,5690,12,12,1,'A 101. légideszant-hadosztály 506. ejtőernyős ezredének Easy százada a világ legjobb gyalogszázadai közé tartozott.\r\n\r\nAmbrose ennek a roppant figyelemre méltó alegységnek a második világháborús történetét mondja el, az 1942-ben Georgia államban végzett embert próbáló alapkiképzéstől a D-napon át a végső győzelemig.\r\n\r\nAz Easy század mindent végigcsinált. Ejtőernyővel szállt le a D-nap hajnalán, és Hitler berchtesgadeni Sasfészkének elfoglalásával fejezte be a háborút. E könyv annak a gyalogszázadnak állít emléket, amely 150 százalékos veszteséget szenvedett a háború végéig, ahol valóban \"egy falka testvér\" módjára koplaltak, fáztak, éltek és haltak együtt a katonák.',NULL),('Mikulásváró',33,2025,1,35,NULL,9786151130780,2690,1,28,2,NULL,NULL),('Futótűz',8,2024,1,308,6,9786155049729,4731,24,19,1,'Katniss Everdeen túlélte Az éhezők viadalát. A Kapitólium bosszúra éhes. Hiába szólt minden ellenük, Katniss Everdeen és Peeta Mellark életben maradtak. Nem nyugodhatnak azonban meg: lázadásról suttognak a Kapitóliumban, ami az ő hatásukra vette kezdetét. A nemzet szeme Katnissra és Peetára szegeződik, a tétek még nagyobbak, mint korábban. Ha hibáznak, a következmények beláthatatlanok.\r\n',NULL),('Spanyol nyelvkönyv kezdőknek - Munkafüzet - A2 - B1',39,2023,3,230,6,9786155200540,2707,20,31,1,'Több éves szünet után ismét kapható a spanyol nyelvtanulók közkedvelt tankönyve!\r\n\r\nAz elsősorban középiskolások és felnőttek számára készült tankönyv (LX-0223) és munkafüzet egymást kiegészítve, hatékonyan alapozzák meg spanyol nyelvtudásunkat, lépésről lépésre segítve hozzá a B1+ szintű nyelvtudás elsajátításához. Az átgondolt és világosan felépített tananyag leginkább szisztematikus magyarázatai és gondosan egymásra épülő feladatai miatt vált közkedveltté, sikerélményt nyújtva a kezdő tanulók számára mind a nyelvtani alapok, mind az alapszókincs elsajátítása terén.\r\nA munkafüzet legfontosabb jellemzői:\r\n\r\n-a tankönyv leckéihez kapcsolódó, világosan egymásra épülő nyelvtani és szókincs-gyakorlatok;\r\n-a fokozatosság elvének figyelembevételével, az egyszerűen megoldhatótól a bonyolultabbig kísérő feladatok minden egységen belül;\r\n-magyar nyelvről spanyolra fordítás minden lecke végén;\r\n-beépített ismétlő gyakorlatok leckéről leckére;\r\n-ismétlő, ellenőrző feladatok minden 4. lecke után, amelyek segítségével mindenki folyamatosan ellenőrizheti tudásszintjét;\r\n-változatos hallás utáni értést mérő (helyesírási, szövegkitöltős, ún. igaz-hamis stb.) feladatok már a kezdetektől fogva, amelyek alapos felkészülést biztosítanak a középszintű érettségi kapcsolódó feladatához;\r\n-a hallás utáni értést mérő feladatok szövegei spanyol anyanyelvi beszélők jól érthető tolmácsolásában hangzanak el.',2),('Kókusz kutya és a Mikulás ',33,2015,1,120,NULL,9786155368912,890,1,28,2,'Kókusz kutyának, a hófehér szőrű kiskutyának minden álma az, hogy a Mikulás neki is hozzon ajándékot, és nem is akármilyet! A kutyus ugyanis egy szerető kis gazdit szeretne kérni a Mikulástól, hogy ne kelljen magányosan éldegélnie az erdőben. De hol találja meg a Mikulást, hogy elmondhassa neki a kívánságát? És ha meg is találja, vajon a Mikulás nem csak az embergyerekek kívánságát teljesíti?  ',NULL),('Zümmögés a konyhában 3. - ...és végy még több kanál mézet!',10,2022,1,180,11,9786155417993,4275,1,20,3,'Nehéz a mézet megbánni. Szereti, mint galamb a mézes búzát. Mosolyog, mint a mézeskalács. - Csupán néhány régi magyar szólás, mondás, melyek a mézre, annak édességére, kiválóságára utalnak. Az utóbbi évtizedekben azonban méltatlanul a hátsó polcra került ez a különleges alapanyag, ezért a konyhaművészet terén is jeleskedő Rúzsa Magdi énekesnő és Vida József bankár úgy döntöttek, kiteszik a mézesbödönt a konyhapultra, és harmadszor is sütni-főzni fognak a mézzel.\r\nA Zümmögés a konyhában sorozat immár harmadik része - a korábbi kötetek hagyományos és különleges, valamint ínyenc és egészséges ételei után - egy valódi desszertgyűjtemény. A szerzőpáros klasszikus és ínyenc finomságokat kínál mézzel készítve, így például a klasszikusok közül képviselőfánkot, répatortát, márványszeletet, míg az ínyencségek közül mille-feuille-t, panna cottát, vagy a közkedvelt brownie-t.\r\nA receptek mellett az olvasók ezúttal is megismerhetik négy újabb magyarországi méhészet alapítóját, munkájuk szépségét, sajátosságait, örömeit, izgalmait a velük készített interjúkból.',7),('Mesék az állatokról ',34,2020,1,46,7,9786155563294,1710,1,28,3,NULL,1),('A Szent Johanna gimi 1. - Kezdet',9,2025,1,440,5,9786155653087,4369,42,16,1,'\"- Na, Cortez is megtalálta a sulit. Éppen ideje volt, nem fogom életem végéig tartogatni a jegyzeteket - sóhajtotta tettetett unalommal az arcán, és becsapta a szekrényajtaját.\r\nElfordítottam a fejem, hogy odanézzek, és akkor...És akkor történt, hogy először megláttam Antai-Kelemen Ádámot, Cortezt. Abban a pillanatban, ahogy megláttam, görcsbe rándult a gyomrom, és úgy éreztem, muszáj lehajtanom a fejem, és úgy tenni, mintha csinálnék valamit, máskülönben elárulom magam. Deszkás cipőt, farmert, és bőfazonú fehér pólót viselt, fél vállán hanyagul lógott a hátizsákja, másik kezében a gördeszkáját tartotta. Összevissza meredező haja csak látszólag állt szerteszét, egyébként gondosan megcsinálta, és pont úgy nézett ki, ahogy kell, és ahogy jól áll neki. A folyosó végén Ricsivel beszélgetett, aztán szép lassan minden osztálytársunk köré gyűlt, és hallgatták.\r\nZavartan turkáltam a szekrényemben, csak néha néztem fel egy-egy pillanatra. - Nézd, megjött Cortez! - jelentette be Virág.\r\nMintha magamtól nem vettem volna észre.\"\r\n\r\nNév: Rentai Renáta (Reni)\r\nKor: 14\r\nBeszélt nyelv: magyar, francia\r\nMagamról: (Nem publikus adat, hozzáférés korlátozva) Az, hogy elköltöztünk, és sulit váltottam, a lehető legjobb dolog, ami történt velem, mert végre lettek barátaim (kettő is!), nem cikiznek, és találkoztam vele, aki igazán nagyon menő!\r\nÉrdeklődési kör: könyvek, olvasás, filmek, internet, azon belül is: Honfoglaló, KvízPart\r\nKlubtagság: Mit olvasol most?; Kedvenc könyvek; Sims; Mindhalálig Beatles!; Milyen idő lesz holnap?; TeveClub',NULL),('A Szent Johanna gimi 2. - Együtt',9,2025,1,462,5,9786155653117,4369,43,16,1,'\" Felfelé baktattunk a dombon, amikor Virág kérdőn körbefordult, és a tekintete megállapodott rajtam.\r\n- Green Day szól a zsebedben - mondta.\r\n- Zavartan előkerestem a mobilom, és közben azon tanakodtam, hogy ki állíthatta be a telóm a Basket Case-re, és egyáltalán ki csörög arra, mert csak egy embert ismerek, aki szereti...\r\n- A kijelzőn Cortez neve villogott, alatta egy menő deszkás képpel.\r\n- Cortez - suttogtam, és megtorpantam az úton.\r\n- Vedd fel! És lélegezz. De előbb vedd fel. Vagy ne! Előbb lélegezz - ugrált körülöttem Virág.##\r\n- Mit mondjak? - kapkodtam a levegőt.\r\n- Elsősorban ne mondj semmit, várd meg, hogy mit akar. De ha beszélni akarsz vele, javaslom, hogy vedd fel - tanácsolta Arnold.\"\r\n\r\nNév: Rentai Renáta (Reni)\r\nKor: 15\r\nBeszélt nyelv: magyar, francia\r\nMagamról: (Nem publikus adat, hozzáférés korlátozva) Lassan nemcsak Virág és Arnold, hanem mindenki a barátjának tekint. Egyéb sikerélmények: suliújság, irodalomverseny, Cortez kettese magyarból. Ami gáz: rajzból tök béna vagyok + Edina!!!\r\nÉrdeklődési kör: könyvek, olvasás, filmek, internet, azon belül is: Honfoglaló, KvízPart\r\nKlubtagság: Kedvenc könyvek; Mindhalálig Beatles!; Felhőtérkép; Akiken kifogott a gördeszka; Akkor sem tudok rajzolni!',NULL),('A Szent Johanna gimi 3. - Egyedül',9,2025,1,488,5,9786155653148,4369,44,16,1,'\"Cortez kikerült minket, lesétált a lépcsőn, miközben a lány már megindult felé. Tudtam, hogy rá vár, tudtam, hogy ő csak Viki lehet, de a következő jelenetet még én sem tudtam előre. A lány vigyorogva átölelte Cortezt, majd hosszú csókkal köszöntötte. Nem, ez nem olyan volt, mint kilencedikben, a díjugrató napján. Most jól láttam. Mindannyian jól láttuk. Lemerevedtem, nem akartam odanézni, de nem tudtam levenni a szemem róluk. A látvány sokkolt, minden energiámmal azon voltam, hogy akkor fulladjak meg, miután elmentek.\r\n- Sziasztok - köszönt hátra Cortez nekünk, aztán megfogta Viki kezét (összekulcsolt ujjakkal), és elindultak.\"\r\n\r\nNév: Rentai Renáta (Reni)\r\nKor: 15\r\nBeszélt nyelv: magyar, francia\r\nMagamról: (Nem publikus adat, hozzáférés korlátozva) Valami nem stimmel... Mintha visszafordult volna az idő, megint nincs senkim, akire számíthatok. Egyedül vagyok.\r\nÉrdeklődési kör: könyvek, olvasás, gitár, suliújság\r\nKlubtagság: Jalapeno; Kedvenc könyvek; Mindhalálig Beatles!; Oasis; Kezdő gitárosok; Akkor sem tudok rajzolni!',NULL),('A Szent Johanna Gimi 4. - Barátok ',9,2020,1,463,5,9786155653179,4369,45,16,1,'\"- Reni? - kérdezte.\r\n- Igen? - kérdeztem vissza döbbenten.\r\n- Jössz velem?\r\n- Nem! - szólt vissza Arnold helyettem, mire mindenki kérdőn felé fordult.\r\n- Neményi, majd szólok, ha hozzád beszélek - mondta Cortez, és újra rám nézett.\r\n- Kezdődik az olvasókör... - hebegtem, de ez nem tűnt túl népszerű válasznak, egy csomóan \"húúú\"-zni kezdtek.\r\n- Oké - tette fel a kezét Cortez, és röhögve odafordult egy csoport végzőshöz.\r\n- Jó - mondtam hirtelen, mire Arnold megpördült a tengelye körül, és visszanézett rám.\r\n- Reni, ne menj el! Kardos vár. Fogalmad sincs, hogy tud-e egyáltalán vezetni. Veszélyes!\r\n- Csak egy sulikör! - indultam le a lépcsőn, és közben kivettem Ricsi kezéből Virág sisakját, amit direkt nekem nyújtott oda.\r\n- Reni! - kiáltott rám Arnold újra.\r\n- Mindjárt jövök - közöltem egyszerűen, feltettem a sisakot, aztán felültem Cortez mögé. Átöleltem a derekát, amitől a régi ismerőseim (pillangó barátaim) mind feléledtek a gyomromban, és elindultunk.\"\r\n\r\nNév: Rentai Renáta (Reni)\r\nKor: 16\r\nBeszélt nyelv: magyar, francia\r\nMagamról: (Nem publikus adat, hozzáférés korlátozva) Visszakaptam Virágot, elveszítem Arnoldot... Úgy érzem, az előző félévhez képest mindenki egy kicsit közelebb került hozzám. Talán ő is...\r\nÉrdeklődési kör: könyvek, olvasás, színház, fotózás\r\nKlubtagság: Akik utálják Doriánt!!!; Jalapeno; Kedvenc könyvek; Mindhalálig Beatles!; Fotósok',NULL),('A Szent Johanna gimi 5. - Remény',9,2025,1,511,5,9786155653209,4369,46,16,1,'\"A ragyogó napsütésbe kilépve ösztönösen hunyorogtam, majd megtorpantam. Ültek a padomon. Kissé megremegett a térdem, de azért erőt vettem magamon, és továbbmentem.\r\n- Te mit csinálsz itt? - kérdeztem Cortezt, aki a pad támláján ült, és ölébe ejtett kezében tartotta a zenelejátszóját.\r\n- Ülök - felelte olyan stílusban, mintha ez azért elég egyértelmű lenne. Jó, tényleg az volt, a vak is láthatta, csak éppen...\r\n- Miért itt? - kérdeztem cseppet sem kedvesen.\r\n- Tudtommal már nem foglalt ez a hely - nézett mélyen a szemembe, nekem pedig felkeltek a pillangók a gyomromban, és úgy döntöttek, hogy egységes erővel próbálnak kiszabadulni. Kérdőn körbenéztem, remélve, hogy valaki segít, de azonkívül, hogy az udvaron állók kétkedő és sanda pillantásokat vetettek felém, senkire nem számíthattam. Márpedig én le fogok ülni! Ez az én helyem! Pár \"egyik lábamról a másikra állok\" mozdulat után fogtam magam, és felültem Cortez mellé. Ennél furcsább még soha, semmi nem volt.\r\n- Akkor én olvasok - közöltem, de ahogy kimondtam, már meg is bántam. Miért jelentettem be? Mi ütött belém?\r\n- Jó - mondta elég furán. És ezen nem csodálkozom .\"\r\n\r\nNév: Rentai Renáta (Reni)\r\nKor: 16\r\nBeszélt nyelv: magyar, francia\r\nMagamról: (Nem publikus adat, hozzáférés korlátozva) Nem hiszem el, hogy Kinga belerángatott... Hogy fogunk kimászni ebből? És mit mondok neki?\r\nÉrdeklődési kör: könyvek, olvasás, fotózás, C.\r\nKlubtagság: Mindig legyen könyv a táskádban; Beatles; Akik már legalább egyszer hibáztak nagyot; 2+2=5',NULL),('A Szent Johanna gimi 6. - Ketten',9,2025,1,543,5,9786155653230,4369,47,16,1,',,- Mi a diagnózis? - kérdezte Ricsi röhögve, mire a pszichológus ismét elmosolyodott, és a szemével körbepásztázta a társaságot. - Melyikőtök Reni? - Én - emeltem fel a kezem zavartan. A pszichológus szeme körül apró ráncok jelentek meg, és bólintott. - Ő a válasz a kérdésedre - mondta Ricsinek. - Gyógyítható? - kérdezte Dave nevetve. - Szerintem nem - nevetett fel a doki is. Vadul zakatoló szívvel néztem Cortezre, aki a napszemüveg mögül fürkészett. Fél évig járt miattam hétfő délutánonként a pszichológusához. Én ezt romantikusnak találom. Miért, nem az? - Tessék ide ülni - kérlelte Zsolti a dokit, aki végül csatlakozott hozzánk, és lazán elhelyezkedett a fűben, felhúzott térdeire kulcsolta a kezét, és türelmesen hallgatta Zsoltit. - Szóval a visszatérő rémálmom. Bejövők a suliba, és Máday habzó szájjal üvölt, vérben forognak a szemei, és...\"',NULL),('A Szent Johanna gimi 7. - Útvesztő',9,2023,1,592,5,9786155653261,4369,48,16,1,'\"- Bolond vagy - nevetett fel Cortez, mire én is elmosolyodtam. - Na, komolyan. A továbbtanulás?\r\n- Az is. De a jelen helyzetben nagyon úgy tűnik, hogy vadászpilóta leszek.\r\n- El fogom venni tőled azt a könyvet - közölte Cortez.\r\n- De most komolyan. Te látod a jövőt? - váltottam stílust.\r\n- Én nem, de jóban vagyok az orákulummal.\r\nMajd bemutatlak neki - mondta, mire megint felnevettem.\r\nCortez vicces.\r\n- Komolyan kérdezem. Megijesztett, ami Kingáékkal történt.\r\n- Helyben vagyunk - mondta Cortez.\r\n- Nem, mármint... tudod... ők nem illettek össze, és szakítottak. Virág és Ricsi nem illenek össze, de tök jól meg vannak. És mi? - kérdeztem félve.\r\n- Mi van velünk?\r\n- Mi lesz velünk? - javítottam ki a kérdését, és ösztönösen a nyakamban lógó lánc felé nyúltam, elkaptam a gyűrűt, és forgattam az ujjaim között.\"\r\n\r\nNév: Rentai Renáta (Reni)\r\nKor: 17\r\nBeszélt nyelv: magyar, francia\r\nMagamról: (Nem publikus adat, hozzáférés korlátozva) Nem akarom, hogy helyettem döntsenek!!!... De akkor most kihez forduljak?\r\nÉrdeklődési kör: könyvek, olvasás, francia nyelv, fotózás, továbbtanulás\r\nKlubtagság: Hová menjek továbbtanulni?; felvi.hu; Melyik szak illik hozzád?; Beatles; Akiknek elegükvan; Végzősök',NULL),('A Szent Johanna gimi 8. 1-2. - Örökké',9,2025,1,776,5,9786155653322,4369,49,16,1,'\"- Van valami, amiért még mindig haragszol az elmúlt évekből? - néztem a szemébe, amikor megálltunk a kapunkban.\r\n- Nem. Nincs - szólt őszintén, némi töprengés után. - Neked?\r\n- Azt hiszem, nincs - ismertem be, és komolyan is gondoltam. - Viszont - tettem hozzá, amolyan \"azért ne nyugodj meg\" pillantással - nehogy azt hidd, hogy Benoit nem jelentett nekem sokat.\r\n- Gondolom. De a te kitalált barátodat Jérome-nak hívták - emlékeztetett mosolyogva.\r\n- Részletkérdés - nevettem el magam, aztán a vállába fúrva az arcom, szorosan átöleltem. - Örülök, hogy az elmúlt négy évem minden egyes napja rólad szólt - suttogtam alig hallhatóan.\r\nCortez kissé eltolt magától, hogy a szemembe tudjon nézni, majd hosszasan megcsókolt, engem pedig elöntött a forróság a hajnali hűvösben. Azt hiszem, ezt végleg megbeszéltük.\"\r\n\r\nNév: Rentai Renáta (Reni)\r\nKor: 18\r\nBeszélt nyelv: magyar, francia\r\nMagamról: (Nem publikus adat, hozzáférés korlátozva) Mindig azt hittem, hogy az első napok voltak a legnehezebbek. Tévedtem. Az utolsók azok.\r\nÉrdeklődési kör: Szent Johanna Francia Tagozatos Alapítványi Gimnázium\r\nKlubtagság: SzJG; Beatles; Végzősök',NULL),('Bízz bennem',9,2020,1,277,NULL,9786155653766,2849,1,16,2,'Egy év telt el az Iskolák Országos Versenye óta. A Szirtes tavalyi gyozelme után a gimi összes diákja beadta a jelentkezését a következo évi megmérettetésre. Kocsis igazgatón hatalmas a nyomás: melyik négy diákja lehet képes a címvédésre amellett, hogy nem roppan össze a negatív kritikák, kommentek súlya alatt, ami az interneten és a táborban éri oket? Az igazgató úgy dönt, ezúttal nem a tanulmányi versenyeken jeleskedok közül választ...A tizenhét éves Major Sára tehetséges táncos, azonban egy balul sikerült buli után kirúgták a csapatából, a történtek miatt pedig megbélyegzetté vált az iskolájában. Éppen ezért o is meglepodik, amikor Kocsis igazgató esélyt ad neki, és beválogatja a Szirtes Gimnázium csapatába, hogy három hasonló sorsú társával részt vegyen az Iskolák Országos Versenyén',NULL),('Párizs, te édes! - Barangolás a könnyed, francia cukrászremekek birodalmában',31,2021,1,174,4,9786155698057,3493,10,26,1,'Párizsban, délután négy óra tájban egyre több ember élete áll meg egy édes pillanatra: ilyenkor megtelnek a cukrászdák, teázók, hogy az oda betérők átadják magukat a le gouter - késő délutáni csemegézés - élvezetének és örömeinek.\r\nLegyen szó akár egy pompás eklerről, néhány szem bájos makaronról, epres tortácskáról vagy épp egy pillekönnyű ezerlapos krémesről - a \"hivatalos\" francia délutáni nassolás szertartása egyre többek számára jelenti a nap fénypontját.\r\nPárizs, te édes! című, új könyvében Jill Colonna végigkalauzolja a vele tartó \"utazót\" azon a mások számára is könnyedén bejárható, élvezetes úton, ami a francia cukrászremekek titkos birodalmába vezet. Lépésről lépésre, a legapróbb részletekre is kitérve osztja meg tudását édes csemegékre vágyó olvasójával.\r\nEngedjünk bátran szíves invitálásának, amelynek során - 82 mennyei francia cukrászsütemény recept segítségével - profi idegenvezetőként kalauzol végig egy igazi édes, párizsi álomutazáson!',7),('Az ajtó ',27,2024,1,329,5,9786155715433,3490,1,15,3,'Álmában nem, de életében egyszer kinyílik az ajtó az írónő előtt. Szeredás Emerenc ajtaja, amely mások számára örökre zárva marad. A megingathatatlan jellemű, erkölcséhez és hiedelmeihez tántoríthatatlanul ragaszkodó asszony házvezetőnőnek áll az írónőhöz, ám első perctől nyilvánvaló, hogy ő diktál. Gazdája megmérettetik, és nem találtatván könnyűnek, Emerenc nem csupán otthona, hanem lelke ajtaját is megnyitja előtte, ha csak résnyire is. Így sejlik fel Magyarország huszadik századi történelmének kulisszái előtt egy magára maradt nő tragikus, fordulatos sorsa. Vajon mit őrizget az idős asszony a hét lakatra zárt ajtó mögött? A regény a ki- és bezártság, a születés és a halál ősi jelképe. Állandó kettősség jellemzi a két főhős áhítatosan odaadó, máskor szinte gyűlölködő kapcsolatát is. A szeretet kapujában állnak. Sikerülhet-e végül beljebb vagy elengedni egymást? Az ajtó Szabó Magda talán legismertebb regénye: Szabó István forgatott belőle filmet, és 2015-ben felkerült a The New York Times sikerlistájára.',NULL),('Tud rólunk VALAKI a Deákban ',9,2025,1,258,NULL,9786155872280,3890,1,16,2,'Miután kiderült, hogy az X csapathoz éppen az a személy fordult segítségért, aki összetörte az egyikük szívét, Roniék egy időre kénytelenek szüneteltetni a tevékenységet, hogy Benedek átgondolhassa, segít a volt barátnőjén, vagy hagyja, hogy megtörténjen a lánnyal ugyanaz, amit ő átélt?\r\nA döntés után a profil újraélesedik, sorra érkeznek a megkeresések, és a tél beköszöntével egyre sokszínűbb feladatokkal találja szemben magát a csapat, a Deákon belül és kívül is...\r\n\r\nA tagok között az összhang töretlen, és miközben a problémák megoldása, a tanulás, az elmélyülő barátságok és a felszínre törő érzelmek között lavíroznak, kudarccal és nem várt fordulattal is szembe kell nézniük.',NULL),('Helló, slow fashion! - Környezettudatos ruhatár lépésről lépésre',27,2021,1,238,5,9786156326089,4740,12,27,1,',,A változáshoz nem kell sok dolog, de egy kicsit mindenkire szükség van. Ha te is úgy érzed, hogy az egyénnek nagy szerepe van abban, hogy jelenlegi felpörgött világunk kicsit lelassuljon, alakítsd át az öltözködési szokásaidat lépésről lépésre! Változtass ott, ahol tudsz! Óriási erő van az egyén kezében, azaz a te kezedben. Élj vele és használd ki!\"\r\nMengyán Eszter\r\n\r\nA fenntartható divat sokkal többet jelent a textíliák létrehozásánál és annál, hogyan kezeljük az elkészült termékeket. Ezzel a definícióval a divat egész rendszerét határozzuk meg: a textilgyártástól kezdve a kreatív iparágon át az értékesítéssel foglalkozó területekig. Átvilágítva a folyamatokat mára már sokan belátták, hogy baj van, a fast fashion kínálta ruhaáradat rengeteg problémát szül, rendszere fenntarthatatlan. A környezettudatos öltözködés ezzel szemben együtt jár a lassulással, a mérlegeléssel, az életmódunk átalakításával. Ez a változás pedig nagyon felszabadítóan hat. A könyv célja, hogy segítsen az első lépésekben: hogyan tegyük fenntarthatóbbá a ruhatárunkat, milyen megoldások léteznek jelenleg, milyen fordulópontokra számíthatunk a jövőben.',NULL),('Világeleje - A jó élet keresése az ökológiai válság korában',37,2024,1,144,5,9786156326379,3790,10,29,1,'Ugye olvasnál már végre valami lelkesítőt is az ökológiai válság kapcsán? Nem könnyű persze ilyet írni, hiszen nem járunk messze civilizációnk ökológiai öngyilkosságától: ijesztően gyors éghajlatváltozás, a csodás élővilág rohamos elszegényedése, fullasztó települési légszennyezés és még számos hasonló probléma fenyeget bennünket.\r\nEz a könyv sem festi rózsaszínre a képet, még véletlenül sem. Ugyanakkor megmutatja azt is, hogy a zord, keserű Mad Max-világ eljövetele korántsem szükségszerű.\r\nSorsunk ugyanis a saját kezünkben van. A tiédben is. A pazarló piaci-fogyasztói civilizáció helyébe még mindig építhetünk egy újat - különösen, ha közösségeket és hálózatokat alkotva, alulról építkezve vágunk bele ebbe a feladatba.\r\nE könyv több tucat, együtt egy nagy képet kirajzoló mikroesszéje erről a lehetőségről szól: a cselekvő remény rögös, de szép útjáról. A jó élet fogalmának átértékeléséről. Bátrakról, gyógyítókról, hősökről, prófétákról. Azaz remélhetőleg rólad is.',NULL),('Állj mellém ',9,2021,1,243,NULL,9786156340047,2849,1,16,2,'A végéhez közeledik az Iskolák Országos Versenye, a négy kitaszított szirteses diák pedig rendületlenül menetel a dönto felé. Sára, Vivi, Rajmund és Dominik határozott céllal érkeztek a versenyre: meg akarják nyerni a kupát, ezzel bizonyítva, hogy ok többek, mint néhány múltbéli hiba.Napról napra egyre szorosabb barátság fuzi össze a piros csapat tagjait a Hortobágyon, ahol az elszántság, a taktikázás, néha pedig a megérzésük az, ami továbbsegíti oket a következo körbe. Kérdés, hogy ez elegendo-e a végso gyozelemhez.Az Iskolák Országos Versenye befejezo kötetében kiderül, hogy Kocsis jól döntött-e, amikor Sárát, Vivit, Rajmundot és Dominikot választotta a címvédo csapatba, és lesz-e másodszor is ,,Nyertes Szirtes\", emellett arra is fény derül, hogyan alakul a még függoben lévo kapcsolat... ',NULL),('A Titanic elfeledett hangjai',15,2025,1,320,4,9786156355195,4550,7,8,1,'KÜLÖNLEGES, ÉLDEKORÁLT KIADÁS\r\n\r\nEgy történelmi regény, mely olyan titkokat árul el, amelyről eddig nem is tudtál!\r\nDédnagymamám sokat mesélt egy hajóról, melyen az egyik osztálytársa utazott. A gőzös neve Titanic volt. A megdöbbentő történetet az iskolatársa testközelből élte át és mivel az első osztályon utazott túlélte a katasztrófát, de soha többé nem mert vízre szállni. Az ő története inspirált arra, hogy megírjam ezt a regényt, melyben olyan titkokat és részleteket is elolvashatsz, amiről talán eddig nem is tudtál. Bár a Titanic történetét sokan megírták már, de a harmadosztályú utasokról szinte soha senki nem beszélt még. A hősök mind az első osztályon utaztak, pedig a szegények is éppúgy éreztek, szerettek, féltek a hajón, mint a módosabb utastársaik. Ugyanúgy hősök, akikre emlékeznünk kell.',NULL),('Sárkányos mesék',33,2022,1,136,NULL,9786156440013,1990,1,28,2,'Az ember fél a sárkánytól, a sárkány fél az embertől. Lehet-e ebből barátság?\r\nMegfeledkezhet-e a királylány arról, hogy a sárkány az sárkány?\r\nMi lesz, ha a bányász kislánya felneveli a tojásból kikelt gyíkocskát?\r\n\r\nKilencéves kortól ajánljuk ezeket a tanító, elgondolkoztató és szórakoztató történeteket, leginkább a szülő általi felolvasásra. A mesélés, mint minden közös élmény erős kapoccsá válik szülő és gyermek között még akkor is, amikor már a gyermek maga is jól tud olvasni. Ha együtt sírunk és együtt nevetünk­, akkor vagyunk igazán együtt.',NULL),('Stílustérkép - Divat, testkép, önismeret',10,2023,1,237,11,9786156488268,7115,9,27,1,'Csalár Bence immár harmadik könyve a fenntartható divat egyik legfőbb pontjára fókuszál egy nagyot, nevezetesen az önismeretre, amely elengedhetetlen része minden változásnak, legyen szó egy fenntarthatóbb gardróbról, tudatos öltözködésről vagy önmagunk mélyebb megismeréséről. Sokszor beszélünk arról, hogy nem szabad lemondanunk megunt ruháinkról, érdemes új szemmel nézni rájuk, átalakítani, formálni, szeretni minél tovább. Ez hatványozottan igaz önmagunkra is, akár a belsőnkről, akár a külsőnkről van szó. Éppen ezért a szerző ezúttal egy, a selyem és lenvászon alatt rejlő mélyebb utazásra invitálja az olvasót. Egyúttal pedig arra biztat mindenkit, hogy habár lehet egy adott keretrendszer vagy mások elvárásai szerint öltözködni, a nap végén úgyis csak az számít, mi hogyan érezzük magunkat a bőrünkben.\r\n\r\nTippek, hasznos gondolatok, divattörténeti fordulópontok, a szabadság és egyediség érzése egyszerre hatja át Bence világát ebben a személyes hangvételű kötetben. Ha megérted, hogy ruháid milyen érzéseket keltenek benned, az komfortosabbá teheti a testeddel fenntartott kapcsolatodat is, miközben magabiztossá válhatsz. Ha hajlandó vagy egy kis önvizsgálatot tartani, akkor jobban fogsz kötődni a ruháidhoz. Az ezzel kapcsolatos érzések pedig befolyásolhatják önbecsülésedet, mentális egészséged és jóléted. Ha belevágsz a változásba, ruhatárad fontos darabjai világítótoronyként fogják megvilágítani az utat valódi önmagad felé. Elvégre, ahogy Szabó Magda is mondta: \"Nem lehet az életet selyemkesztyűben és báli ruhában végigcsinálni.\"',7),('Magyar superfood - 65 szuperétel, 106 szuperélelmiszer',10,2020,1,229,11,9786156488336,6165,10,20,1,'TUDATOSSÁG - FENNTARTHATÓSÁG - KÖRNYEZETBARÁT TÁPLÁLKOZÁS\r\n\r\nA superfood kifejezés sokak számára egyet jelent az egészséggel, hiszen olyan alapanyagot mutat, amely valamely értékes tulajdonságában kiemelkedik társai közül. A legnépszerűbbek sorát a goji bogyó, az avokádó, a tengeri moszat és a lazac vezeti, ám a vargányáról, a rizsről vagy akár a sárgarépáról, padlizsánról már csak kevesen tudják, hogy szintén igazi szuperélelmiszerek, ráadásul itthon is megteremnek.\r\n\r\nE könyv szerzője nem kevesebbre vállalkozott, minthogy összegyűjtse mindazokat\r\na hazánkban fellelhető zöldségeket, gyümölcsöket, gabonaféléket és olajos magvakat, melyek szupererővel rendelkeznek, így méltán viselhetik a magyar superfood elnevezést. Dietetikusként hitelesen mutatja be értékes tápanyagtartalmukat, egészségünkre gyakorolt pozitív élettani hatásukat és változatos konyhai felhasználásukat. Mindezek mellett ahhoz is kellő bizonyítékkal szolgál, miért érdemes elsősorban a hazai szuperalapanyagokat beépíteni étkezésünkbe, és hogy ezzel a választással milyen sokat tehetünk a fenntartható, környezettudatos táplálkozás és életmód érdekében.\r\n\r\nA látványos, kedvcsináló fotókkal illusztrált kiadványban több mint száz hazai szuperélelmiszer, és a belőlük készült izgalmas, ínycsiklandó és egészséges finomság receptje kapott helyet. S, hogy az alapanyagok beszerzése se okozzon gondot,a hazai termőhelyekről, illetve az aktuálisan elérhető termények listájáról is tájékozódhatnak az olvasók. Tegyük változatossá, értékessé étkezésünket!',5),('Grilldesszertek - Édes és sós finomságok a parázson',10,2025,1,189,7,9786156488497,7990,32,26,1,'Piskóta, pogácsa, gyümölcsös pite. Kedvenc sós és édes süteményeidet ezentúl már nemcsak a konyhában, a sütőben készítheted el, hanem kint a szabadban, a grillsütőben is.\r\nFarkasinszki Ildikó - aki jogászból lett cukrász -, a Grill-ázs Cake House megálmodója egy izgalmas gasztronómiai utazásra hív ezzel a különleges szakácskönyvvel: klasszikus kelt tészták, csokis finomságok, torták és kovászos kenyér készül el a grillen, legyen az faszenes, gázos vagy kerámiasütő. A könyv oldalait lapozgatva 64 grilldesszert receptjét ismerheted meg, és a grillsütés csínját-bínját is egyszerűen elsajátíthatod. Grillezési technikák, módszerek, kellékek és eszközök egész listáját szedte össze a szerző, hogy neked erre már gondod se legyen.\r\nMostantól kezdve a kerti grillezés már nem csak a férfiak kedvelt elfoglaltsága lehet. A grillben készülő desszertek a sütemények és a szabadtéri sütés új korszakát hozzák el. Kalandra fel, találkozzunk a grillsütő mellett!',7),('Lunchbox - Csomagolj tápláló finomságokat az egész családnak!',10,2025,1,126,5,9786156488558,6190,3,20,1,'Neked is gondot okoz, hogy mit csomagolj a családnak és magadnak ebédre? Akár irodában vagy az iskolában, akár útközben kell elfogyasztanod, ebben a könyvben jobbnál jobb ötletekkel szolgálunk a tartalmas, tápláló és ízletes ebédek elkészítéséhez. De nem csak ehhez!\r\n\r\nSzerzőnk, Nagy Zita (a Mit eszik a vega gyerek? és a Vegán reggeli című könyvek írója, akit blogjáról sokan csak Ziziként ismernek) salátákat, leveseket, egytálételeket és szendvicseket alkotott meg úgy, hogy azok könnyen csomagolhatók és napközben egyszerűen elfogyaszthatók legyenek. Hideg és meleg finomságok találhatók a könyvben, de az ebédeken túl tízóraira való energiadús italok, valamint uzsonnára bekapható édes falatok is bőven akadnak. A receptek felnőtteknek és gyerekeknek egyaránt szólnak, emellett külön ajánlás található vegetáriánusok, vegánok, laktóz- és gluténérzékenyek részére. Az ínycsiklandó fogások mellett Zita összegyűjtött néhány alapreceptet és alapanyagot, amelyekből mindig jó, ha van otthon, és megmutatja, melyek a legjobb dobozok a csomagoláshoz.\r\n\r\nA Lunchbox mindenkinek kínál valamit, akár munkába, akár iskolába visszük, vagy csak úgy otthon fogyasztjuk el. Csomagoljunk együtt!',NULL),('Margit néni süteményes könyve ',30,2024,1,115,6,9786156603777,3705,5,26,1,NULL,7),('A desszertet én hozom - Viszkok Fruzsi 50 receptje ',31,2024,1,152,7,9786156709066,6990,12,26,1,'50 kedvenc recept tőlem, amivel nem tudsz mellélőni, hiszen már számtalanszor teszteltem, finomítottam őket. Ha azt érzed, elvesztél a desszertek végeláthatatlan kínálatában, ne aggódj, segítek! Legyen szó\r\njól bevált családi kedvencekről, utazásokról hazahozott sütiötletekről vagy épp a tudatosság jegyében maradékmentő finomságokról. Ha tényleg nem bíznál semmit a véletlenre, válogathatsz a sütésmentes és\r\naz elronthatatlan desszertjeim között is. A recepteket kipróbálva osztozz te is a jelmondatomban, és a következő meghívásnál nyugodtan válaszolj majd így: \"A desszertet én hozom.\"\r\n\r\n- Viszkok Fruzsi',7),('Sütőtök bíró és a kásák csatája',33,2025,1,53,NULL,9786156915344,2600,1,28,2,'A KÁSÁK NAGY CSATÁJA Csatlakozz Sütőtök bíróhoz és barátaihoz, akik egy izgalmas versenyen bíráskodnak! Melyik kása a legfinomabb és a legegészségesebb? Ismerd meg a kásákat, és dönts te is, miért olyan jó egyik vagy másik! A mi mesénkben végül, amikor mindenki megkóstolja a finomságokat, nehéz dönteni - hiszen mindegyik kása nagyon különleges és finom! Készen állsz egy izgalmas kalandra? Indulhat a kásaverseny! Ízletes, egészséges és tele mókával!',NULL),('A természet ízei - 120 szezonális, növényi alapú recept',30,2025,1,320,7,9786156983466,8991,16,20,1,'Hangoljuk ételeinket a természet ritmusához! Tegyük főszereplővé a zöldségeket és az ehető növényeket a tányérunkon, így az ízek, színek és textúrák kavalkádja tárul fel előttünk.\r\nGyökér, szár, virág és levél, őszi cékla, tavaszi spárga és rebarbara, roppanós saláták, édes gyümölcsök és illatos virágok - mindegyikben ott rejlik egy új íz, egy izgalmas élmény, a főzés öröme.\r\nA kötetben 120 egyszerű és inspiráló receptet találunk a könnyű salátáktól a melengető leveseken és egytálételeken át a különleges desszertekig. Megtudhatjuk, hogyan lehet a hétköznapi hozzávalókból színes, változatos és tápláló ételeket készíteni - mindezt úgy, hogy közben a bolygónkat is kíméljük.\r\n\"Ha közelebb kerülünk az ételhez, közelebb kerülünk önmagunkhoz is\" - vallja Gill Meller szakács, író és gasztronómiai tanácsadó, akit a természetes alapanyagok és a szezonális főzés inspirálnak. Tizenöt éven át volt a River Cottage csapatának szakácsa. Több könyvet is írt, amelyekben a növények sokszínűségét ünnepli. Hisz abban, hogy a tudatos étkezés nem lemondás, hanem felfedezés - a jóllét, a természet és az ízek harmóniája.',NULL),('Édes békeidők ',31,2016,1,233,4,9786158057608,9405,3,26,1,'\"Ebben a könyvben csupa kipróbált, bárki által elkészíthető sütemény receptjét gyűjtöttük össze, minden titkot és rafinériát leírtunk. Odafigyelve biztos, hogy sikerülni fog minden egyes édesség.\r\n\r\nPersze tökéletes sütemény nincs. Nem is ez a cél, hanem a teljes szívvel, minden érzékünkkel magunkba szívott, közösen átélt, tökéletes pillanat. Minden szeretettel végzett munka és őszinte élvezettel lenyelt falat egy kis saját, édes békeidő. Tisztelet a nagy cukrászmestereknek és a régi nagymamáknak, hogy megőrizték nekünk a recepteket arról, hogyan is kell igazán élni.\"',7),('Megúszós kaják - 84 ütős cucc',32,2017,1,206,4,9786158161152,7115,5,20,1,'Ezt a könyvet, azt hiszem, pont nektek raktam össze. Nektek, akik szerettek főzni és keresitek az újabb és újabb inspirációkat, de nem tudtok minden alkalommal órákat tölteni a konyhában. Szívesen lepnétek meg valami jó ötlettel a családot, de nem akartok mindig különleges alapanyagokra vadászni. Nektek, akik nem elkummantani akarjátok a főzést, csak meg akarjátok úszni a nagy rumlit, a várakozást, a bonyolultabb lépéseket, az extra hozzávalókat, és a sok mosogatást. Mert még szeretnétek játszani egyet a gyerekkel. Vagy kinyitni egy üveg bort, leülni nyugisan és megnézni egy filmet. Vagy társasozni a haverokkal. A könyvben 84 kipróbált, pik-pak összedobható és mégis isteni finom étel receptje található, mindegyikkel megúszható a nagy felfordulás és learatható minden babér. Főzzetek sokszor, de ne sokáig! És persze, azért még mindig PACAL FOREVER, gyerekek!',7),('Német újratöltve - Új távlatok újrakezdőknek',39,2025,3,408,5,9786158271202,13990,23,31,1,'Ez a kötet azoknak készült, akik nem az elejéről, de nem is a közepéről vágnak neki a német nyelvnek. Akiknek már ismerős a \"haben\", illetve a \"sein\", de sok minden porosodik, hiányzik, kavarodik. Akik nem akarják újra elölről kezdeni a tanulást, de érzik: kell egy biztos alap, amit aztán már bátran lehet építeni tovább.',2),('Limara Péksége - Házi Pékek Alapkönyve',29,2025,1,188,11,9789630899345,8075,25,20,1,'Kenyér = liszt, só, élesztő, víz + Limara\r\n\r\nLibor Marcsi és a blogja, a Limara Péksége megkerülhetetlen, ha jól bevált, megsüthető, finom kelttészta-recepteket keresünk. A konyhában ő a legjobb barátnőnk.\r\nNaponta tízezernél többen keressük fel a blogját, így megsaccolni sem lehet, hányan készülődünk úgy a sütéshez a nagyvilágban, hogy az ő oldala van nyitva a laptopunkon, kinyomtatott vagy kézzel lefirkált receptjei hevernek a konyhaasztalon. Aztán büszkén terelünk mindenkit a forró tepsihez, hadd csodálják meg a végeredményt, Marcsinak pedig mosolyogva írunk egy kedves üzenetet, hogy beszámoljunk a sikerről. Ő mutatta meg nekünk a kenyérsütés varázsát. Ő inspirált nőket, férfiakat, amatőröket, sütésben jártasakat, hogy fedezzék fel és leljék örömüket a házi kenyér készítésében. És most végre itt a várva várt szakácskönyve! A kezdőket lépésről lépésre megtanítja kelt tésztát sütni, a gyakorlottaknak összegyűjtötte a legkedveltebb recepteket, míg a kísérletező kedvűeknek új finomságokat talált ki.\r\n\r\nLegyél hát te is házi pék!\r\n\r\nTarts Limarával ezen a kenyérillatú úton!',7),('Szörnyen jó szakácskönyv',32,2016,1,96,5,9789630985734,3315,13,20,1,'Ebben a könyvben Bernáth József arra vállalkozott, hogy amolyan nemszeretem alapanyagokból süssön-főzzön. Teszi mindezt lelkes kukták segítségével. Miközben bebizonyítja, hogy a brokkoli vagy a zeller nem is olyan ősellenség a konyhában, azt is megmutatja, hogyan tudják a gyerekek elkészíteni ezeket a fogásokat otthon - akár egyedül is.',7),('Kulcs - Orosz nyelvkönyv kezdőknek - Tankönyv',39,2021,3,203,6,9789631358872,5690,14,31,1,'A tankönyv a kezdetektől az alapfokú tudásig juttatja el a tanulót, a cirill írás-olvasás tanulásától és a nyelvtani alapismeretektől kezdve a legfontosabb szavak és mondatszerkezetek elsajátításáig.',2),('Más-világok - Kihalások és újjászületések a Föld történetében',37,2024,1,463,5,9789631370171,7590,7,29,1,'Kénytelenek vagyunk antropocénnek nevezni a korszakot, amiben élünk, mert a környezetünkre, a Föld élővilágára radikális hatással vagyunk. Thomas Halliday könyvében azzal is szembesülhetünk, bolygónk könnyen kiheveri majd a pusztulásunkat, mindegy, mikor következik be, hiszen jó néhány kataklizmával a háta mögött teremtette meg a lehetőséget az emberiség kialakulására. A könyv lapjain kirajzolódnak a több millió éves ciklusok - kialakulás, felívelés, hanyatlás, kihalás, újjászületés -, hogy a végén föltegyük magunknak a kérdést: a kisszerű hatalmi és gazdasági játszmák helyett nem azon kellene inkább gondolkodnunk, esetleg hogyan élhetné túl az emberiség a következő kihalási szakaszt? A Más-világok eddig 13 nyelven jelent meg, és a magyar mellett hamarosan érkezik a japán, a brazil, az orosz és a török kiadás is.',NULL),('Általános természetföldrajz - A gimnáziumok számára',42,2011,1,256,11,9789631948530,2175,1,30,3,'szerzők: Nemerkényi Antal - Sárfalvi Béla tantárgy:Földrajz évfolyam:9. A tankönyvjegyzéken szerepel. A korábbi, nagysikerű \"Általános természetföldrajz\" című tankönyvet dolgozta át a szerző, hogy megfeleljen a kerettanterv előírásainak. (\"Az általános természetföldrajz\"i fejezeteket kiegészítettük dr. Sárfalvi Béla által írt, a \"Természetföldrajzi övezetesség hatása a rársadalom életére\" című anyagrésszel). Az új tankönyv színes fotókkal, új, színes ábrákkal kiegészítve mutatja be a csillagászati, földtani, éghajlattani fejezeteken túl a földfelszín formakincsét, a vízburok földrajzát, a földrajzi övezetességet. \"Az általános természetföldrajz\"i fejezeteket követi \" A természetföldrajzi övezetesség hatása a társadalom életére\" című anyagrész. Az ismeretek gyakorlására, összefoglalására munkafüzet készül.',7),('Évszakok a vegán konyhában ',30,2024,1,186,NULL,9789632916576,3990,1,20,2,'A növényi étrend szezonális útmutatója Ha eddig úgy gondoltad, hogy a növényi alapú táplálkozásnak csak a nyári hónapok kedveznek, most kellemes meglepetésben lesz részed! Niki végigkísér az évszakokon, miközben - a szezonalitást és fenntarthatóságot is szem előtt tartva - hasznos tanácsokkal és praktikus ötletekkel szolgál. Legyen szó akár ünnepi étkezésről, akár a gyümölcsök, termések vagy fűszernövények begyűjtéséről, minden évszak tartogat valami újdonságot. Mellőzve a száraz adatokat, ez a könyv tökéletes mindazoknak, akik örömmel alkotnak a konyhában. Próbáld ki a több mint 50, mind a négy évszakot lefedő, könnyű vegán receptet - imádni fogod őket!',NULL),('Harry Potter és a Főnix Rendje ',25,2023,1,811,6,9789633244418,5690,25,19,1,'Harry Potter nem hitte volna, hogy egyszer ő fogja megvédeni basáskodó unokatestvérét, Dudley-t. Ám amikor fényes nappal dementorok támadnak kettőjükre, ez történik. De számos más vészjósló esemény is mutatja, hogy a varázsvilág békéjét sötét erők fenyegetik.\r\nHarry nincs egyedül az ellenük vívott küzdelemben: a Főnix Rendje egy titkos főhadiszálláson szervezi a Sötét Nagyúr elleni harcot, ami minden fronton zajlik. Harry például kénytelen különórákat venni Piton professzortól, hogy ki tudja védeni Voldemort erőszakos behatolásait a tudatába.',NULL),('Mondj nemet a műanyagra! - 101 egyszerű ötlet műanyag helyett',37,2019,1,128,7,9789633246702,2270,1,29,2,'Te is szeretnél tenni valamit a környezetedért? Egyszerűbb lesz, mint gondolnád!\r\nMa már közismert tény, hogy a környezetünkben felhalmozódó műanyaghulladék ökológiai katasztrófával fenyeget. De változtathatunk-e a kialakult helyzeten anélkül, hogy gyökeresen átalakítanánk az életmódunkat? Természetesen! Ez a kis könyv 101 egyszerű, könnyen megvalósítható ötletet ad ahhoz, hogy környezetbarát anyagokkal helyettesítsük a műanyagot, és ezzel mi is hozzájáruljunk bolygónk védelméhez.',NULL),('Porcukor és habverő - Sütemények kezdőknek és haladóknak',31,2016,1,192,4,9789633411025,4655,25,26,1,'A nagy sikerű A Nők Lapja Konyha 100 legjobb süteménye című könyv szerzője, Papp Emese megmutatja nekünk, mennyire nagyszerű élmény a sütés. A könyvből kiderül, mi a tökéletes piskóta és kelt tészta titka, mit süthetünk, ha csak fél óránk van, és az is, miként készíthetünk olyan születésnapi tortát, amitől mindenkinek leesik az álla. A könyvet kezdőknek és haladóknak egyaránt ajánljuk, mindenki talál benne neki tetsző receptet, legyen szó klasszikus süteményről vagy egy modernebb íz- és formavilágú desszertről.\r\nA szerző 15 éve dolgozik cukrászként, a legjobb budapesti éttermekben és szállodákban készített süteményeket. Jelenleg az ettlingeni Michelin-csillagos Hotel Erbprinz vezető cukrásza. Első könyve, A Nők Lapja Konyha 100 legjobb süteménye eddig négy kiadást ért meg',7),('Soproni-hegység, Lajta-hegység, Fertő turistatérkép - Sopron belvárásának térképével, és a Soproni Parkerdő ismertetőjével',38,2025,1,2,NULL,9789633538395,3490,12,9,1,'Az aktualizált, új kiadású Soproni-hegység turistatérkép 1:40000 méretarányban részletesen és naprakészen ábrázolja a látnivalókat, a sokrétű szabadidős lehetőségeket, ezáltal nélkülözhetetlen társa az aktív turisztikai formák kedvelőinek.\r\n\r\nTartalom:\r\n- turistautak, tanösvények\r\n- a Soproni Parkerdő fényképes leírása\r\n- kemping, szálloda és egyéb szálláshely\r\n- Sopron belváros térkép\r\n- Lajta-hegység, Fertő tó áttekintő térkép\r\n- kerékpározásra javasolt útvonalak\r\n- kerékpárutak (Harka-Nagycent, Fertő tó kerülő út)\r\n- EuroVelo13 - a Vasfüggöny kerékpáros túraútvonal térségi nyomvonala\r\n- az M85 autópálya átadásra került és az országhatárig épülő nyomvonala\r\n- az autópálya átadásával jelentősen módosuló közúthálózat, turistaúthálózat\r\n- a felújított nagycenki múzeumvasút\r\n- Páneurópai Piknik Emlékpark - Látogatóközpont\r\n\r\n\r\nAz új kiadású térképen aktualizálásra kerültek a turistautak, valamint a tanösvények és bemutatóhelyek. A térképen feltüntetésre kerültek az új, kerékpározásra javasolt útvonalak a túrák sorszámaival, valamint a sífutó- és lovastúra útvonalak. Az M85 autóút új szakasza és az ehhez kapcsolódó közúti fejlesztések ábrázolása.\r\n\r\nA naprakész információi miatt a térkép segítséget ad a Sopron környéki és városi programok szervezéséhez, és a szabadidő hasznos eltöltéséhez.',7),('Velencei-hegység, Velencei-tó turistatérkép ',38,2025,1,2,NULL,9789633539699,3490,18,9,1,'A Cartographia kiadó népszerű turistatérkép-sorozatának tagja 1:25 000 méretarányban ábrázolja a Velenceihegység és a Velencei-tó területét.\r\n\r\nA tájékozódást a települések utcanevei is segítik.\r\n\r\nFőbb jellemzők:\r\n- egylapos, hajtogatott térkép\r\n- 2 nyelvű jelmagyarázat\r\n- a Velencei-hegység bemutatása\r\n- a tó körüli települések fényképes ismertetői\r\n\r\nTartalom:\r\n- turistautak, tanösvények\r\n- kiépített, jelzett és ajánlott kerékpárutak\r\n- védett területek, természeti látnivalók\r\n- múzeumok, tájházak, egyéb épített látnivalók\r\n- szálláshelyek, kempingek, étkezési lehetőségek\r\n- kikötők, hajójárat\r\n\r\nAz új kiadású térképen aktualizálásra kerültek a turistautak és a tanösvények nyomvonalai.\r\n\r\nFelkerültek a térképre az új kerékpárutak, valamint a Budapest-Balaton kerékpárút (EuroVelo14) nyomvonala.\r\n\r\nA térség általános bemutatásán kívül a települések fényképes ismertetői is helyet kaptak a kiadványon.',7),('Az árnyak háza',3,2014,1,224,4,9789633571750,2849,12,16,1,'Hogy kicsoda Joe Carrot? Joe Carrot egy nyúl. De nem akármilyen nyúl: Joe Carrot magánnyomozó! Ügynöksége, a Carrot & Carrot a leghíresebb magánnyomozó iroda egész Tapsivárosban. A történetei pedig egyszerre izgalmasak és szórakoztatóak, és tele vannak rejtélyekkel és vidámsággal.',1),('Mielőtt éjfélt üt az óra',3,2015,1,128,4,9789633576144,2849,12,16,1,'Hogy kicsoda Joe Carrot?\r\nJoe Carrot egy nyúl. De nem akármilyen nyúl, Joe Carrot magánnyomozó! Ügynöksége, a Carrot & Carrot a leghíresebb magánnyomozó iroda egész Tapsivárosban (naná, hiszen az egyetlen!).\r\nJoe Carrot azonban nemcsak nyomozó, de gondos családapa is. A történetei éppen ezért egyszerre izgalmasak és szórakoztatóak, és tele vannak rejtélyekkel és vidámsággal.\r\n\r\nMielőtt éjfélt üt az óra\r\nTi hisztek a boszorkányokban? Nem?! Joe Carrot sem hitt bennük. Ezért, amikor egy este Retek Rúfusz megjelent a Carrot & Carrot magánnyomozó irodában a Horgas orrú boszorkány rejtélyével, Joe rögtön gyanút fogott. Itt bizony valami bűzlik, mint az odakozmált répafőzelék!',NULL),('Percy Jackson és az olimposziak 1. - A villámtolvaj ',1,2015,1,373,6,9789633731154,2849,12,16,1,'egesküdtem a Styx folyóra, hogy ami ebben a könyvben le van írva, az elejétől a végéig kitaláció. Nincs semmiféle Perseus „Percy\" Jackson nevű tizenkét éves fiú. A görög istenek csak régi mítoszok. Egészen biztosan nincsenek gyermekeik halandóktól a huszonegyedik században, és Félvér tábor nevű hely sem létezik, ahol félistenek, fiatal hősök táboroznának, akiket én tanítok és edzek arra, hogyan éljék túl szörnyűséges ellenségeik támadását. Percy sosem találkozott szatírral és Athéné lányával sem. Egyáltalán nem indultak együtt az Alvilág kapujához, hogy megakadályozzák az istenek közötti katasztrofális háború kitörését. Mindezek után figyelmeztetnem kell téged, alaposan gondold meg, elkezded-e olvasni ezt a könyvet. Ha bármi felkavarót érzel olvasás közben - ha gyanítod, hogy ez a történet a te életedhez hasonít - AZONNAL HAGYD ABBA AZ OLVASÁST! A következményekért semmiféle felelősséget nem vállalok.',NULL),('Percy Jackson és az olimposziak 2. - A szörnyek tengere',1,2016,1,256,6,9789633998489,3324,12,16,1,'Percy Jackson hetedik éve az iskolában meglehetősen unalmasan indul. Egyetlen szörny sem akarja betenni a lábát New York-i sulijába. Ám amikor az ártatlan labdázgatás élet-halál harccá válik egy csapat emberevő óriás ellen, a dolgok, hogy is mondjam. kezdenek eldurvulni. Váratlanul érkező barátja, Annabeth is csak rossz hírekkel szolgálhat: a Félvérek táborát védő határokat egy titokzatos ellenség lerombolta, és amíg ezeket újra helyre nem állítják, a félisteneknek nincs hová rejtőzniük. A villámtolvaj lendületes, humoros és rendkívül népszerű folytatásában Percynek és a barátainak át kell szelniük a Szörnyek Tengerét, hogy megmentsék a táborukat. De Percynek mindezek előtt még szembesülnie kell egy a származását érintő titokkal: rá vár a feladat, hogy eldöntse, áldás-e, avagy átok Poszeidón fiának lenni.',NULL),('Percy Jackson és az olimposziak 3. - A Titán átka',1,2016,1,285,6,9789633998502,3324,12,16,1,'Amikor Percy Jackson megkapja Groover segélyhívását, készülődni kezd a harcra. Jól tudja, hogy szüksége lesz erős szövetségeseire, Annabeth-re ás Tháliára, a félistenekre; valamint hűséges bronzkardjára, Árapályra is... és egy fuvarra a mamájától. A félistenek Grover megmentésére sietnek, aki mint később kiderül fontos felfedezést tett: két félistenre bukkant, kiknek származása egyelőre még ismeretlen, de igen nagy erővel rendelkeznek... De ez még nem minden. A Titán úr, Kronosz felállítja számukra eddigi legfondorlatosabb csapdáját, és az ifjú hősök majdnem belesétálnak. A sorozat mulattató, és izgalmas harmadik kalandjában Percynek a legveszélyesebb kihívással kell szembenéznie: a Titán Átkának hátborzongató próféciájával...',NULL),('Percy Jackson és az olimposziak 4. - Csata a labirintusban',1,2016,1,344,6,9789633998526,3790,13,16,1,'Percy Jackson semmi jót nem várt az iskolai nyílt naptól,\r\nde amikor titokzatos halandó ismerőse után két pompomlány démonnal is találkozik,\r\na dolgok még a vártnál is rosszabbra fordulnak.\r\nA sikersorozat negyedik kötetében a küszöbön áll az olimposziak és a Titán isten közötti háború már. Még az eddig biztonságos menedéknek számító Félvér Tábor is sebezhetőnek bizonyul, amikor Kronosz és hadserege megpróbál varázshatárán belülre kerülni. Hogy a támadásnak elejét vegyék, Percy és félisten barátai egy küldetésre indulnak a Labirintusba - a hatalmas, földalatti világba, ami minden fordulóban újabb vérfagyasztó meglepetést tartogat számukra.',NULL),('Solitaire - Pasziánsz',1,2023,1,336,6,9789633999783,3609,7,19,1,'Nem emlékszem olyanra, amikor nem voltam komoly.\r\nLegjobb tudomásom szerint cinizmust harsogva és esőt\r\nkívánva jöttem ki az anyaméhből.\r\n\r\nA nevem Tori Spring. Szeretek aludni és szeretek blogolni. Tavaly még voltak\r\nbarátaim. A dolgok nagyon mások voltak, azt hiszem, de mindennek már vége.\r\n\r\nMost itt van a Pasziánsz. És Michael Holden.\r\n\r\nNem tudom, mit akar a Pasziánsz. És nem érdekel Michael Holden. Tényleg nem.\r\n\r\nSzereted Charlie nővérét a HEARTSTOPPER-kötetekben?\r\nAkkor van egy jó hírünk: ez a regény róla szól.\r\nGyere, és ismerd meg, mi rejlik a hirtelen felbukkanó,\r\nmindig cukormentes limonádét iszogató lány fejében!',NULL),('Goriot apó ',3,2025,1,288,1,9789634059035,2564,5,16,1,'Balzac maga nevezte regényének hősét, Goriot apót ,,az apaság krisztusának\". A mű ma is úgy él a köztudatban, mint egy szenvedő, kiszolgáltatott, mártírumot vállalt apa története, a lányai által kisemmizett, őket mégis az utolsó pillanatig szerető öregember regénye. A regény megértéséhez tudni kell, hogy a magára hagyott Goriot apót egyedül szánó, temetésén egyedül részt vevő Rastignac más Balzac-regényekben nagy karrieristaként szerepel, szalonok hőse, a legszebb nők kegyeltje, az élet igazi császára. Itt azok a vonásai állnak előtérben, amelyek megmagyarázhatják, hogy e talán legfontosabb balzaci hős miért egyúttal a leginkább komplex, jóból és rosszból legbonyolultabban ,,kikevert\" alakja a szerző embergalériájának. Rastignac ugyanazon penzió lakója mint Goriot apó, éles szemmel hamar észreveszi azt is, hogy miért nem viszonozzák, miért nem viszonozhatják lányai apjuk szeretetét, milyen társadalmi - kötelező érvényű - mozgások irányítják még a legkisebb, legmeghittebb sejt, a család belvilágát is. Ugyancsak a penzió minuciózus leírásából kapunk először képet arról a Párizsról, amely a további darabok legfőbb színhelye, a ,,nagy\" társadalomnak mintegy szimbóluma lesz. A regény vége, utolsó jelenete a világ regényirodalmának legtávlatosabb, legsejtelmesebb zárásai közé tartozik: Goriot apót eltemetve egy egész világ temetődik el. Rastignac híres szavai a temető hegyéről látható esti Párizshoz: ,,Most mirajtunk a sor!\" - nemcsak saját pályája további küzdelmeit jelzik, nemcsak kihívást jelentenek, de új világok születésének próféciáját is.',NULL),('Gucci',10,2024,1,183,NULL,9789634064305,2490,5,27,2,'Patrizia Gucci titokban született: szerelemgyerek volt, akinek születése könnyen romba dönthette volna édesapja, Aldo Gucci karrierjét. Az 1960-as években történt, a Hollywood és a királyi sarjak must-have divatmárkájának számító Gucci cég boldog, szép napjaiban. Ugyanakkor ez még az az időszak is volt, amikor a házasságon kívüli gyermekvállalás illegálisnak számított Olaszországban. Aldo nem engedhetett meg magának egy nyilvános botrányt, azonban nem volt képes ellenállni Patrizia édesanyja iránti hatalmas szerelmének. Szerelmét, Brunát akkor ismerte meg, amikor a fiatal lány munkát vállalt az első római Gucci-üzletben. Teherbe esése után Aldo Gucci, a problémákat elkerülendő, Londonba menekítette Brunát, hogy később újszülött gyermekével együtt diszkréten visszacsempéssze Rómába, az olasz hatóságok, a média és a Gucci család előtt teljes titokban. Ez a könyv Patrizia szüleinek elhallgatott szerelmi történetét tárja elénk a szerző személyes emlékeire, szüleinek összegyűjtött szerelmes leveleire és az édesanyjával folytatott beszélgetésekre, valamint a korábban nem publikált archív fényképekre támaszkodva. Szüleinek viharos történetét édesapjához fűződő személyes viszonyának elbeszélésével szövi át: attól kezdve, hogyan töltötte életének első évtizedét legnagyobb részt rejtőzködve, elszigetelten a világtól, majd hogyan vált a Gucci szóvivőjévé és apjának, Aldónak legfiatalabb tanítványává, egészen addig a pillanatig, amikor a hírhedt puccs után Aldo kitagadja mindhárom fiát, és egyetlen, egyetemes örökösévé a valaha bűnös kis titokként kezelt Patriciát teszi meg. Az Olaszországon, Anglián és Amerikán átívelő történet szerelemről és veszteségről, árulásról és hűségről szól, amely a Gucci családi vállalkozásként megélt hatvan évének legviharosabb időszakában játszódik.',NULL),('Frakk a macskák réme ',3,2025,1,86,7,9789634156109,2374,25,16,1,'„Hol volt, hol nem volt, volt egyszer egy szép kis kertes ház. Abban lakott két kövér macska. Rajtuk kívül ott lakott még Károly bácsi és Irma néni is.\" A kövér macskák boldogan éltek a szép kertes házban, igaz, hogy Irma néni nagyon elkényeztette őket. Ebből lett a baj. Károly bácsi addig álmodozott egy olyan kutyáról, amelyik macskát reggelizik, ebédel, vacsorázik, amíg egyszer csak valóban egy eleven kutya jelent meg a házban: Frakk, a macskák réme. Így kezdődött a kutya-macska háború, amelynek minden epizódját jól ismeri tévénézők apraja és nagyja. Irma néni és Károly bácsi, Lukrécia, Szerénke és Frakk, a macskák réme személyes ismerősként köszöntik az Olvasót.',1),('Abigél ',27,2024,1,349,5,9789634158493,4794,1,15,3,'Gina, a regény hősnője 1943-ban elbúcsúzik otthonától és azoktól, akiket szeret, mert apja beadja a híres árkodi intézetbe. A kis ötödikes gimnazistát a rideg világ, a szokatlan, kegyetlen törvények lázadásra késztetik. Ám megtud valamit, ami maradásra bírja, és önként vállalja a rabságot... Hogyan igazodik el egy tizenöt éves kislány ebben a felnőtt-titkoktól terhes világban?\r\nA modern és olvasóbarát formátumú könyv élvezetes olvasmány lehet fiataloknak és felnőtteknek egyaránt.',NULL),('A kiválasztott - Az éhezők viadala 3.',8,2019,1,352,11,9789634196693,4731,25,19,1,'Bár minden ellene szólt, Katniss Everdeennek kétszer is sikerült élve kikerülnie az Éhezők Viadalából. Túlélt minden megpróbáltatást, de még mindig nincs biztonságban. Mert a Kapitólium bűnbakot keres a lázadás miatt. Snow elnök pedig egyértelművé tette: Kapitólium haragja elől senki sem menekülhet. Sem Katniss családja, sem a barátai, sem pedig a 12. Körzet lakói. De közeledik a végső forradalom ideje. Amikor a nép végre szembeszáll a Kapitólium zsarnokságával. És ebben a forradalomban Katnissnak döntő szerepe lesz. Az ő bátorságától, kitartásától és eltökéltségétől függ Panem jövője. Mert ő a kiválasztott. De maradt-e elég ereje hozzá, hogy megvívja az utolsó, mindent eldöntő harcot? Suzanne Collins Az éhezők viadala című trilógiája az utóbbi évek legnagyobb szenzációja az ifjúsági regények műfajában. Az immáron világszerte több mint tízmillió példányban értékesített sorozatról azt mondják, hogy méltó folytatása a Harry Potter- és Twilight-könyveknek, tovább népszerűsítve, illetve megszerettetve az olvasást a fiatalokkal. Az éhezők viadalának nemrég elkészült a filmváltozata, amit március 22-étől, a hivatalos nemzetközi premierrel egyidőben fognak vetíteni Magyarországon is. A szereposztás meglehetősen impozáns: a főszereplő Katnisst az a Jennifer Lawrence fogja alakítani, akit a Winter\'s Bone A hallgatás törvénye c. filmben nyújtott alakításáért Oscar-díjra és Golden Globe-díjra jelöltek, de játszott az X-Men: Az elsők című filmben is. Mellette a legnagyobb szerepekben Woody Harrelsont, a rocksztár Lenny Kravitzet, Stanley Tuccit, Elizabeth Bankset, Donald Sutherlandet és Toby Jonest láthatjuk majd.',NULL),('Énekesmadarak és kígyók balladája ',8,2024,1,448,6,9789634198154,5206,26,19,1,'Az Éhezők Viadala hivatalos előzményregénye! A becsvágy hajtja. A küzdelem élteti. De a hatalomnak megvan az ára. Annak az aratásnapnak a reggelén járunk, amely a tizedik Éhezők Viadalát előzi meg. A Kapitóliumban a tizennyolc éves Coriolanus Snow élete nagy dobására készülődik, a mentori posztjára a Viadalban. Az egykor nagy hatalmú Snow-házra nehéz idők járnak: a jövőjük azon múlik, hogy Coriolanus képes lesz-e elbűvölőbbnek, ravaszabbnak és taktikusabbnak bizonyulni diáktársainál, és győztest tud-e faragni a saját kiválasztottjából. Az esélyek azonban ellene szólnak. Azt a megalázó megbízatást kapja ugyanis, hogy a 12. körzet lány kiválasztottját mentorálja, a legaljának a legalját. Sorsuk ezzel végleg összefonódik - Coriolanus minden döntése kedvezményekhez vagy kudarchoz, csillogáshoz vagy csődhöz vezethet. Az arénán belül életre-halálra szóló harc következik, az arénán kívül pedig Coriolanus elkezd együttérezni megpecsételt sorsú kiválasztottjával... és mérlegelnie kell, hogy a szabályok követése a fontosabb, vagy a túlélés. Kerül, amibe kerül.',NULL),('A pápa zsoldosa ',15,2023,1,351,4,9789634266754,4274,13,8,1,'Ezernégyszázötvenegy. Világrengető események készülnek mindörökre megváltoztatni Európa sorsát. Az ifjú Mohamed szultán eltökélten készíti fel seregét az addig legyőzhetetlennek hitt Konstantinápoly elleni támadásra. A várost talán meg lehetne menteni, de ehhez a Nyugat nemzeteinek összefogására lenne szükség. Csakhogy királyai, fejedelmei ügyet sem vetnek a fenyegető veszedelemre, és pillanatnyi érdekeiknek megfelelően inkább sorsára hagyják a létéért küzdő, valaha hatalmas birodalom maradékát. Egyetlen katonai erő marad, amely a szorongatott Konstantinápoly felmentésére siethetne, ám a belső széthúzás és a határokon túlról szőtt ármány megakadályozza, hogy Magyarország kormányzója hadjáratot indíthasson a Török Birodalom ellen. Sőt Hunyadi Jánosnak élete egyik legnehezebb döntését is meg kell hoznia ezekben a hónapokban: tartja magát esküjéhez és harcba indul a gyermek V. László kiszabadításáért, amivel lemondana kormányzói posztjáról, vagy elkezdi kiépíteni a Hunyadi-ház eljövendő királyi hatalmát.\r\n',NULL),('Ördögi erő ',15,2023,1,330,4,9789634266914,4274,7,8,1,'Bónizs Róbert A kőfaragó és a Szent László íja című kötetek után az eddig általa feldolgozott korszak két legendás történelmi szereplőjének, Nagy Lajos királynak és Toldi Miklósnak életét dolgozza fel új sorozatában.  A sorozat első kötete gyerekkorától, 1330-tól Nagy Lajos első nápolyi hadjáratáig, 1348-ig követi nyomon Toldi Miklós és a trónörökös, illetve később ifjú uralkodó életének eseményeit. Toldi menekülni kénytelen szülőházából, de egy véletlen folytán felkelti Károly Róbert király és Lajos herceg figyelmét, és az utóbbi apródjává válva a királyi udvarba kerül. A herceg mellett részt vesz az uralkodó hadjárataiban, újra és újra kitüntetve magát vitézségével.  A pusztán erős ifjúból igazi lovaggá érő Toldi és az ígéretes, de atyja árnyékából még előtörni nem tudó Anjou Nagy Lajos között konfliktusoktól sem mentes, mégis bizalmi kapcsolat alakul ki, amit azonban nem mindenki néz jó szemmel, és amikor a király ellenségei szövetkeznek Toldi ellenségeivel, súlyos megpróbáltatások várnak barátságukra...  A szerző a nagy elődök irodalmi alkotásai mellett kiterjedt kutatásokkal alapozza meg sorozata hitelességét, átfogó betekintést nyújtva a korszak európai politikai és történelmi eseményeibe, s így a korábbiaknál tágabb kontextusba helyezve szereplői történetét.',NULL),('Esztergom oroszlánja',15,2025,1,332,4,9789634267263,5499,4,8,1,'Bónizs Róbert A kőfaragó és a Szent László íja című kötetek után az eddig általa feldolgozott korszak két legendás történelmi szereplője, Nagy Lajos király és Toldi Miklós életét mutatja be új sorozatában. Ezerháromszázötvenhárom. Toldi visszanyeri a király kegyét és barátságát. Lajos arra kéri, hogy lépjen Vásári Miklós esztergomi érsek szolgálatába. Toldi ezután az érsek oroszlános zászlaja alatt vonul hadba Litvániában, ahol továbbra is élen jár a harcokban, ám egyre inkább nyomasztja a véget nem érő öldöklés és lényének sötétebb oldala. Peleskei Urdung Julianna és a Venus Rend Toldi Györggyel összefogva igyekszik beteljesíteni a király és Toldi Miklós elveszejtésére szőtt tervét, és céljaik elérése érdekében a legkegyetlenebb eszközöktől sem riadnak vissza. Lajos király mindeközben kevés időt hagy Toldinak a pihenésre, a litván hadjárat után szinte azonnal Velence ellen indul. Miklós egyre inkább belefásul a harcba, ám a hadjárat befejezése után egy találkozás egy régi haragosával új értelmet ad életének... A szerző a nagy elődök (Arany János, Ilosvai Selymes Péter és Benedek Elek) irodalmi alkotásai mellett kiterjedt kutatásokkal alapozza meg sorozata hitelességét, átfogó betekintést nyújtva a korszak európai politikai és történelmi eseményeibe, így a korábbiaknál tágabb kontextusba helyezve szereplői történetét.',NULL),('A penge éle',15,2025,1,336,4,9789634267508,5499,3,8,1,'Ezerháromszázhatvanöt. Toldi testben-lélekben megtörve szenved a sienai tömlöcben. Démonai nem hagyják nyugodni, lassan saját maga is kételkedni kezd elméje épségében. Hű társai azonban nem feledkeznek meg róla, és saját életüket gondolkodás nélkül kockára téve a kiszabadítására indulnak. Lajos királyt egyre jobban aggasztja az Oszmán Birodalom jelentette fenyegetés, és elhatározza, hogy keresztes hadjáratot indít a törökök megfékezésére. Ehhez azonban a pápa jóváhagyására is szüksége lenne, ennek elnyeréséhez megpróbálja rávenni a szorongatott helyzetben lévő V. János bizánci császárt, hogy térjen át a katolikus hitre. Erőfeszítéseit nem koronázza siker, és hamarosan kénytelen megütközni a törökkel - természetesen Toldival az oldalán. Az erejét visszanyerő Toldi tovább szolgálja királyát, újabb birtokokat és címeket kap, majd az 1370-es években ismét Itáliában hadakozik. A szerző a nagy elődök (Arany János, Ilosvai Selymes Péter és Benedek Elek) irodalmi alkotásai mellett kiterjedt kutatásokkal alapozza meg sorozata hitelességét, átfogó betekintést nyújtva a korszak európai politikai és történelmi eseményeibe, s így a korábbiaknál tágabb kontextusba helyezve szereplői történetét.',NULL),('Halott kislány a jó kislány',35,2025,1,563,6,9789634379942,4274,7,17,1,'\"Egy kéz tapadt szájára, belé fojtotta a sikolyt, mielőtt kiszabadulhatott volna. Egy kar fonódott a nyaka köré, a támadó könyökhajlata egyre szorosabbra zárult körülötte. Pip ellenállt. De nem jutott levegőhöz. Megpróbálta letépni a kart a nyakáról, a kezet a szájáról, de egyre gyengült, kiürült a feje. Az árnyékok csak mélyültek körülötte. Hiába küzdött. Lélegezz, csak lélegezz! De nem tudott.\" A Jó kislányok kézikönyve gyilkossághoz és a Jó kislányok, rossz viszonyok című könyvek izgalmas folytatása. SIESS! VAGY MEGHALSZ... Pip Fitz-Amobit még mindig kísérti a legutóbbi nyomozása. De hamarosan új bűnesettel kénytelen szembesülni, ami nagyon is közelről érinti, ugyanis ezúttal valaki őrá vadászik. Valaki, aki folyton egy kérdéssel zaklatja: Téged ki fog keresni, ha eltűnsz? Pip hamarosan kapcsolatot fedez fel a zaklatója és egy helyi sorozatgyilkos között, de a rendőrség nem hajlandó cselekedni. A veszélyes macska-egér játék során Pipnek mihamarabb meg kell találnia a választ, mert immár az élete a tét...',NULL),('Cukrásztitkok - Útmutató a sikeres sütéshez',31,2025,1,183,7,9789634439790,9405,23,26,1,'Ez egy nem klasszikus értelemben vett gasztronómiai könyv. Német-magyar cukrászként olyan segítséget szeretnék adni az olvasóknak, amit eddig nem kaptak meg: a mai cukrászvilág titkainak könyvét. Többek között olvashatsz arról, hogyan hozhatunk helyre egy elrontott krémet, mi a különbség a lisztek között, miért nem szükséges felfuttatni az élesztőt, honnan tudjuk megállapítani, hogy romlott-e a tojás, anélkül, hogy feltörnénk, és hogy mi a hasonlóság a churros és a magyar képviselőfánk között. Ha eddig nem mertél belevágni a sütésbe, vagy ha sok kudarc ért egy-egy sütemény elkészítésekor, akkor ez a könyv neked szól! Tippek, trükkök és módszerek, klasszikus és különleges receptekkel ötvözve, amelyekkel a sütés nemcsak élmény, de siker is lesz!',7),('A vörös mancs rejtélye',4,2017,1,121,4,9789634470557,2849,12,16,1,'Hogy kicsoda Joe Carrot? Joe Carrot egy nyúl. De nem akármilyen nyúl, Joe Carrot magánnyomozó! Ügynöksége, a Carrot & Carrot a leghíresebb magánnyomozó iroda egész Tapsivárosban (naná, hiszen az egyetlen!). Joe Carrot azonban nemcsak nyomozó, de gondos családapa is. A történetei éppen ezért egyszerre izgalmasak és szórakoztatóak, és tele vannak rejtélyekkel és vidámsággal. A vörös mancs rejtélye Hamarosan kezdetét veszi a Nagy Répa Kerékpáros Körverseny. A versenyzők közt ott van Jane Carrot is. Joe és a gyerekek teljes erőbedobással szurkolnak neki. Ám ekkor feltűnik a színen egy titokzatos tolvaj, aki abban mesterkedik, hogy ellopja Jane kerékpárját. Nincs más hátra, Joe-nak fülön kell őt csípnie.',2),('Kirké',7,2025,1,424,5,9789634525653,5215,12,18,1,'Az Akhilleusz dala szerzőjének merész, káprázatos és várva várt új regénye, amely kiválóan rajzolja újra az Odüsszeiából ismert hatalmas varázslónő, Kirké életét. A leghatalmasabb titán, a Napisten, Héliosz házában egy kislány születik. Kirké furcsa gyermek - nem rendelkezik hatalommal, mint az apja, sem azzal a rosszindulatú vonzerővel, mint az anyja. Ám amikor társaságért a halandók világa felé fordul, felfedezi, hogy mégiscsak van egy különleges tehetsége: a varázslás képessége, amelynek révén szörnyekké tudja változtatni a riválisait, ráadásul még az istenekre is veszélyt jelenthet. Fenyegetettségében Zeusz száműzi őt egy lakatlan szigetre, ahol az istennő tökéletesíti titkos tudományát, vadállatokat szelídít, és a híres mitológiai alakok közül többel is találkozik: a vérszomjas Minótaurosszal, az ügyes kezű Daidalosszal, a gyilkos Médeiával és persze a fortélyos Odüsszeusszal is. Ám egy nőnek veszélyes egyedül élni, Kirké pedig akaratlanul is magára vonja mind az emberek, mind az istenek haragját, és végül az egyik legrettegettebb olümposzi istennel találja szemközt magát. Hogy megvédje, amit a leginkább szeret, minden erejét össze kell szednie, és egyszer s mindenkorra választania kell az istenek és a halandók világa között. Madeline Miller regénye mámorító eposz a családi vetélkedésről, intrikáról, szerelemről és veszteségről, illetve a férfiak uralta világban is rendíthetetlen női erőről. A Goodreads Choice Awards 2018 kategóriagyőztese.',NULL),('Akhilleusz dala ',7,2024,1,397,5,9789634526421,4740,12,14,1,'Gyönyörű történet istenekről és istennőkről, királyokról és királynőkről, halhatatlanságról és az emberi szívről. A fiatal Patroklosz királyok sarja, mégis száműzik otthonából, amikor akaratlanul egy fiú halálát okozza. Az ifjú a híres-neves hős, Péleusz király udvarába kerül, ahol együtt nevelkedik a király fiával, Akhilleusszal. Az aranyszőke hajú herceg már gyermekként is erős, gyors és vonzó - ellenállhatatlan mindazok számára, akik találkoznak vele. Arra rendeltetett, hogy egy napon ő legyen a legkiválóbb görög. Patroklosz és Akhilleusz nem is különbözhetne jobban egymástól, mégis különleges, eltéphetetlen kötelék szövődik közöttük. Amikor Parisz, a trójai királyfi elrabolja a gyönyörű Helenét Spártából, Hellász minden hősét harcba szólítják a trójaiak ellen. Akhilleusz nem tud ellenállni az istenek által neki ígért dicsőség és hírnév csábításának, így csatlakozik a görög seregekhez. Patroklosz pedig félelem és a barátja iránt érzett szeretet között őrlődve követi őt Trója falai alá, noha tudja, a sors szörnyű áldozatot követel majd mindkettőjüktől... Az eredeti kiadás 10. évfordulójára, a szerző új előszavával.',NULL),('Percy Jackson és az olimposziak 5. - Az utolsó olimposzi',1,2017,1,356,6,9789634571292,3790,14,16,1,'A félvérek egész évben harcra készülődtek, de tudták, hogy nem sok esélyük van a győzelemre. Kronosz serege erősebb volt, mint valaha, és minden átállt istennel és félistennel nagyobb lett.\r\n\r\nAmíg az olimposziak a pusztító Tüphónt próbálták megállítani, addig Kronosz bevonult New Yorkba, ahol az Olimposz gyakorlatilag őrizetlenül állt. Az Idő Urának megállítása Percy Jacksonra és a fiatal félistenek csapatára várt.\r\n\r\nA világszerte sikeres sorozat izgalommal várt befejező részében beteljesül a Percy tizenhatodik születésnapjára jövendölt prófécia. Miközben Manhattan utcáin tovább dúl a nyugati világ megmentéséért vívott harc, Percyn az a szörnyű gyanú lesz úrrá, hogy a saját sorsa ellen küzd.',NULL),('Pusztulás és felemelkedés',1,2019,1,386,1,9789634577775,3799,12,13,1,'Katona. Idéző. Szent.\r\n\r\nAz ország sora egy megtört idézőn, egy kegyvesztett nyomkeresőn és egy egykori nagy mágikus sereg szétvert maradványain múlik.\r\nAz Éjúr árnytrónján ülve uralkodik, míg a meggyengült és sebesült Alina Sztarkov igyekszik felépülni, az őt szentként imádó Apparátus kétes védelme alatt. Minden reményét egy rég eltűnt ősi lény mágiájába veti, és abba az esélybe, hogy egy bizonyos törvényen kívüli herceg még életben van.\r\nAhogy a szövetségesei és az ellenségei a háborúba sodródnak, egyedül Alina áll az ország és világ örök rabságával fenyegető, áradó sötétség között. Hogy megnyerje ezt a harcot, meg kell szereznie egy legendás lény hatalmát - ám a tűzmadár utáni hajsza váratlan fordulatot tartogat.\r\n\r\nKövesd végig sorsa minden fordulatát!',NULL),('This Winter - Az idei tél',1,2023,1,104,6,9789634578857,1899,12,19,1,'- Gyűlölöm a karácsonyt - mondja Tori.\r\n- Nem, nem gyűlölöd - felelem.\r\n- Az ideit gyűlölöm.\r\n- Az ideit mindenki gyűlöli.\r\n\r\n\r\nAz idei tél kemény Tori, Charlie és Oliver Spring számára. Mindannyian igyekeznek a lehető legkevesebb drámával átvészelni a karácsony napját. Olivernek ez azt jelenti, hogy Mario Kart-ozik a bátyjával és a nővérével,\r\nTori és Charlie számára pedig azt, hogy maguk mögött hagyják az elmúlt néhány hónapot.\r\n\r\n\r\nVajon ez a karácsony szétszakítja a Spring családot, vagy elkezdi összekovácsolni őket?\r\n\r\n\r\nÉrzékeny látkép a 21. századi diszfunkcionális családokról, akik szeretik egymást, de fogalmuk sincs, miként fejezzék ezt ki.\r\n\r\n\r\nOlvasd el ezt az újabb megható Heartstopper-történetet!',6),('Ha stílus van: minden van - A stílusos férfi kézikönyve',27,2021,1,80,NULL,9789634755425,3490,1,27,2,'Manapság egy öltönyt, zakót, igényes cipőt viselő férfi feltűnést kelt - nem kifejezetten a különcségével, sokkal inkább a jelenlétével. A klasszikus férfistílust lehet nem szeretni: egészen addig, amíg egy férfi ki nem próbálja, milyen érzés viselni. Egy jól szabott öltönyt nem felvenni kell: azt csak viselni lehet. Kiegyenesíti a hátat, tartást ad, felemeli a fejet, és a férfi hirtelen igazi férfinak érzi magát. De nem csak ő érzi a különbséget: innentől kezdve a nők is más szemmel néznek rá. Bihari Ádám stílustanácsadó, a férfiöltözködés szabályait és annak felrúgását is kívülről-belülről, széltében-hosszában jól ismerő, szórakoztató, különleges észjárású és folyamatosan vibráló személyiség a Ha stílus van: minden van című könyvében foglalja össze mindazt, amit az igazi férfiról tud, tudni lehet és tudni érdemes. Kívülről halad befelé: az öltözködés alapjaitól indulva eljutunk egészen az olasz férfiak összetéveszthetetlen megjelenésének filozófiájáig, a sprezzaturáig. Ezután veszi górcső alá azt az alapot, amire egy jól megválasztott napi viselet felkerül: az igazi férfiasság belső tényezőit, a lelkierő, az önbizalom, a nyitottság és az őszinteség sajátosságait. Mert hiába öltözik fel ízlésesen valaki, ha az a ruha nehéz rá: a saját stílusunkat képviselni is tudni kell. Lehet, hogy ma még sokan legyintenek arra, hogy ugyan, mit számít ez, hiszen ezer más dolgom van, lefőtt a kávé, kezdődik a meccs, ki kell vinni a kutyát, várnak a haverok az edzőteremben - de egyre többen vannak azok, akik számára egyértelmű, hogy reggel, indulás előtt az a férfi, aki visszanéz rájuk a tükörben, ma sem fog csalódást okozni. És mi lehet fontosabb annál, hogy jól érezzük magunkat a saját társaságunkban? Bihari Ádám a Stílusőrjárat című YouTube-csatorna megálmodója és megvalósítója. Magyarország legnépszerűbb stílustanácsadója, kiemelkedő social media-szereplő, rengeteg fiatal példaképe. Többmilliós nézettségű a YouTube-csatornája, ahol a jelen és a jövő generációját tanítja csípős, önironikus humorral és kérlelhetetlen szakmaisággal. Közép- és nagyvállalatok gyakran felkért előadója, üzletemberek és magánszemélyek privát stílustanácsadója. A Sprezzatura by Bihari alapítója, arca és szakmai vezetője, amely Magyarország első számú nápolyi stílusú bespoke csúcsszabósága.',NULL),('Sprezzatura - Öltözködni és élni',27,2023,1,304,4,9789634757672,5699,10,27,1,'A férfiakból kiveszett a férfi. Kiveszett az erő, az alázat, a szolgálat, az elkötelezettség, az önismeret, a lelki és szellemi gazdagság, és mindezt lejáró szavatosságú luxustárgyakkal, inflálódó pénzzel, hiteltelen akarnoksággal és hatalomnak látszódó rettegéssel próbálják pótolni - sikertelenül. Elfelejtettek felnőni, minden vágyuk az, hogy beleolvadjanak a tapétába, és onnan magyarázzanak az uniformizált és elsilányult férfikultúra mindenhatóságáról. A sprezzatura, a szabad öltözködési stílus sokkal többet jelent, mint hogy milyen színű díszzsebkendőt tegyél a szivarzsebedbe. Azt jelenti, hogy legyen elég hatalmad önmagad felett, hogy azt vedd fel, ami tetszik. Hogy te döntsd el, mi a jó neked, hogy megvalósítsd önmagad, hogy úgy töltsd el a mindennapjaidat, ahogyan az a legtöbb örömet okozza neked. Hogy megéld a saját férfiasságod minden porcikáját faltól falig. Ez a könyv azoknak a férfiaknak és nőknek szól, akik hisznek abban, hogy egy férfi lehet férfi, hogy a férfiak hatalmának a lényege, hogy képesek szeretni saját magukat, és ez minden erőt megad nekik ahhoz, hogy legmerészebb álmaikat is megvalósítsák. Ez a könyv a férfi emancipációjáról szól, a férfiasság autonómiájáról, felnőttségéről, gazdagságáról. Aki ilyen férfivá szeretne válni, és aki ilyen férfit szeretne szeretni, az ezt a könyvet is szeretni fogja. BIHARI ÁDÁM Magyarország legnépszerűbb stílustanácsadója, kiemelkedő social media-szereplő, rengeteg fiatal példaképe. Stílusőrjárat című, többmilliós nézettségű YouTube-csatornáján a jelen és a jövő generációját tanítja csípős, önironikus humorral és kérlelhetetlen szakmaisággal. Közép- és nagyvállalatok gyakran felkért előadója, üzletemberek és magánszemélyek privát stílustanácsadója. A Sprezzatura by Bihari alapítója, arca és szakmai vezetője, amely Magyarország első számú nápolyi stílusú bespoke csúcsszabósága.',NULL),('Mentes táplálkozás',27,2024,1,114,NULL,9789634758990,3999,1,25,2,'Egészséget, szépséget, fogyást ígérő diétákkal Dunát lehet rekeszteni - de valahogy mindig kiderül, hogy hosszú távon nem működnek. Hiába a megváltást ígérő étrendek, újabb és újabb táplálkozási elvek és irányvonalak, ha van egy közös pontjuk: a szélsőség.\r\nCsak húst egyél, csak zsírt egyél, csak zöldséget egyél, csak gyümölcsöt egyél - halljuk és olvassuk, miközben nemcsak a tapasztalat, de a megbízható tudományos eredmények is mind azt mutatják, hogy a megoldás ebben is az arany középút. A kiegyensúlyozott étrend, mely nem a megvonásokról szól, hanem amelynek segítségével mértékletesen, észszerűen, a tudomány legújabb kutatási eredményeire alapozva tudjuk megválogatni az ételeinket, és nem dőlünk be egy diétának csak azért, mert éppen az a legdivatosabb.\r\nA szerző, MOLNÁR DÁVID táplálkozási és életmód-tanácsadó saját magán is megtapasztalta a szélsőséges étrendek pusztító hatását, és most már évek óta segít azoknak a klienseinek, akik a különböző divatos fogyókúrák és elhibázott tanácsok következtében nemcsak nem érték el a kitűzött céljukat, de gyakran az egészségük és a pénztárcájuk bánta a szélsőséges étrendet. Könyvében rendet tesz a rengeteg téves elképzelés és félreértelmezett tudományos eredmény között, amelyekkel a tanácsadásai során találkozott. Amellett, hogy bemutatja, miért olyan károsak a hirtelen felkapott diéták, azt is megtudjuk, hogy egy kiegyensúlyozott, a középutat megtaláló, szerethető táplálkozás segítségével hogyan tudunk lefogyni és egészségesen élni.',NULL),('Cinkostársak',6,2020,1,300,NULL,9789634795094,1999,1,16,2,'Tommy és Tuppence fiatalok, jól szituáltak, és boldogan élnének, ha végre történne valami az életükben. Tuppence a vásárlással töltött, egyhangú hétköznapokon izgalomra vágyik, kalandokról ábrándozik, amikor váratlanul betoppan Tommy főnöke, Mr. Carter, és megmenti az unatkozó házaspárt: kinevezi Tommyt a Nemzetközi Nyomozóiroda vezetőjének, és egyből meg is bízza egy titkos feladattal. Egy kék levél orosz bélyeggel - ez lesz az áruló jel, ami segít majd leleplezni egy bolsevik titkosügynököt. Az újdonsült nyomozók nagy lendülettel vetik bele magukat az érdekesnek ígérkező kihívásba. Miközben küldetésük sikeres teljesítése lebeg a szemük előtt, a nagy elődök - Holmes és Watson, az Okewood testvérek, Hastings kapitány - szerepébe bújva sorra leplezik le az útjukba akadó bűntényeket.  A korábban Bűnszövetkezetben címmel napvilágot látott regény most új kiadásban jelenik meg.',NULL),('A világ bizonyos szimmetriája - A kora újkori csillagászat története válogatott források tükrében ',42,2022,1,320,NULL,9789634931379,3190,1,30,2,'Bizonyára a kedves olvasó is hallott már Copernicusról, Keplerről, Galileiről és Newtonról: ők a tudomány történetének legnagyobb hősei. De vajon olvasta-e is őket? Némelyiket aligha, hiszen ez idáig (szinte) semmilyen művük sem volt elérhető magyarul. Másokat esetleg igen, ám feltehetőleg régebbi és elavult fordításban. Bár az egyetemes kultúra történetének kiemelkedően fontos szövegeiről van szó, az érdeklődőket eddig nem kényeztette el a hazai könyvkiadás. Ezt az űrt kívánjuk részlegesen betölteni a jelen kötettel. Hat kora újkori szerző tudományos - jórészt csillagászati - szövegeiből ismerhetünk meg szemelvényeket, melyek fontos felfedezésekről, belátásokról, elgondolásokról számolnak be. Találkozhatunk a kozmosz leírását kifejtő Copernicusszal, a hagyományos csillagászati világkép kihívásait felsorakoztató Mästlinnel, a Napból kiáradó mozgatóerőt elemző Keplerrel, a Holdat távcsővel felmérő Galileivel, a kozmikus törvényekről és örvényekről értekező Descartes-tal, valamint a tudás határait feltérképező Newtonnal. A szemelvényeket bevezető tanulmányokkal, részletes jegyzetanyaggal, fogalomtárral és bibliográfiával egészítettük ki.',NULL),('Éltető víz - III. Vízgazdálkodás és rendszerelmélet',37,2024,1,328,6,9789634932857,6555,1,29,2,'Manapság sok szó esik a vízről, és a problémákat egészen másképpen látják a hidrogeológusok, a meteorológusok, a mérnökök vagy a politikusok. Az elmúlt évszázadok során sikerült olyan rendszereket kialakítanunk, amelyekkel a földfelszínen és a felszín alatt található vízkészleteinket mind mennyiségi, mind minőségi szempontból veszélybe sodortuk. Sajnos a megoldási alternatívákról kevés szó esik, pedig léteznek ilyenek, csak éppen kényelmetlennek érezzük őket, és a kényelmünket a biztonságunk érdekében sem szeretnénk feláldozni.\r\nTikkasztó jövő elé nézünk. A felborult vízháztartás és a kiszáradó szárazföldek miatt akkor is ez vár ránk, ha most éppen bele akarunk fulladni a csapadékba. Hol sok a víz, hol pedig kevés, sokszor ugyanazon a helyen, csak más időszakban. Minek köszönhetjük mindezt? Az éghajlatnak? Az időjárásnak? Netán saját magunknak? Nem tudja a jobb kéz, mit csinál a bal. Mi minden lehetne másképpen, ha nem dugnánk homokba a fejünket? A kötet a rendszerelmélet sorvezetőjével keresi a választ a látszólag megoldhatatlan kérdésekre.',7),('Grammatica semplice - Olasz képes nyelvtan ',39,2021,3,271,6,9789634994640,4446,3,31,1,'Az olasz nyelvtan elsajátítása sokak számára jelent nagy kihívást. Ezen változtat ez az újszerű, színes, illusztrált olasz nyelvtankönyv, melynek segítségével könnyedén átláthatja az összefüggéseket, megértheti az olasz nyelv szabályait, és alkalmazhatja is azokat az élő nyelvben. Az olasz nyelvtant\r\n204 önálló pontra osztottuk, majd a Közös Európai Referenciakeret A1-A2, B1 és B2 szintjeinek megfelelően nehézségi fokuk szerint rendszereztük, így a kiadványt a kezdőtől a középfokú nyelvvizsgára vagy az emelt szintű érettségire készülő tanulóig bárki sikeresen használhatja. A könyv felépítése átlátható, bármilyen információ könnyedén azonosítható vagy visszakereshető. A szabályok magyarázatakor kerültük a bonyolult megfogalmazást, így azok a kezdők számára is azonnal érthetőek. A kötetet minden olaszul tanulónak ajánljuk kezdőtől a haladó szintig, ha érettségire vagy nyelvvizsgára készül, vagy fejleszteni, tökéletesíteni szeretné nyelvtantudását.',1),('King of Wrath',41,2025,1,423,5,9789634998990,4999,1,19,2,'Ő a feleség, akit sosem akart... és a gyenge pont, amire sose számított.\r\nKegyetlen. Irgalmatlan. Arrogáns.\r\nDante Russo minden helyzetben irányít - a magánéletében éppúgy, mint a munkájában. A milliárdos cégvezér sose akart megnősülni - mígnem egy zsarolás fenyegetése bele nem kényszeríti egy eljegyzésbe egy olyan nővel, akit alig ismer. Vivian Lau ráadásul nemcsak egy gazdag örökösnő, hanem legújabb ellenségének lánya. És nem számít, mennyire gyönyörű és bájos. Dante mindent meg fog tenni, hogy eltüntesse a bizonyítékokat, és felbontsa az eljegyzésüket.\r\nEgyetlen problémája akad: most, hogy a nő az övé... már nem tudja elengedni.\r\nElegáns. Nagyra törő. Jól nevelt.\r\nVivian Lau a tökéletes lánygyermek, és a családjának egyetlen reménye, hogy elérjék a társadalmi ranglétra legmagasabb fokait. Ha beházasodna a kékvérű Russo családba, az olyan ajtókat nyitna ki, amelyek egyébként elérhetetlenek lennének újgazdag családja számára. Így ugyan a goromba és visszahúzódó Dante nem az esete, kötelességtudóan beleegyezik az előre elrendezett házasságba.',NULL),('King of Sloth - A restség',41,2025,1,542,5,9789634999362,6999,1,19,2,'Soha nem akart annyira senkit, hogy fusson\r\n\r\nutána... amíg nem találkozott vele.\r\n\r\nSármos. Laza. Hihetetlenül gazdag.\r\n\r\nXavier Castillónak a lábai előtt hever a világ, de esze ágában sincs átvenni a családi nagyvállalat irányítását, persze ettől függetlenül imádják a nők... kivéve egyvalakit, a PR-menedzserét. Akit egyébként folyamatosan felbosszant, de egy tragédia közelebb hozza őket egymáshoz. Xaviernek szembe kell néznie a jövőjével, és azzal a felismeréssel, hogy arra a nőre vágyik igazán, aki nem olvad el tőle.\r\n\r\nFegyelmezett. Intelligens. Ambiciózus.\r\n\r\nSloane Kensington jól menő PR-menedzser, aki remekül megtalálja a hangot még a nehezebb ügyfelekkel is. De egyik sem képes úgy kihozni a sodrából, mint egy bizonyos milliárdos örökös a maga szívdöglesztő gödröcskéivel és a felettébb lezser életfilozófiájával. Együtt dolgoznak ugyan, de soha nem fog beleszeretni... bármennyire is megdobogtatja a szívét, bármennyire is vonzó a higgadtsága a bulizós álarc alatt. Mert Xavier számára csakis egy ügyfél lehet. Nem igaz?',NULL),('Amikor összetört a világ ',15,2025,1,415,5,9789634999867,5999,1,8,2,'A kilencvenegy éves Gretel Fernsby évtizedek óta ugyanabban az elegáns londoni épületben lakik. Mélyen felkavaró, sötét múltja ellenére csendes, kényelmes életet él. Nem beszél arról, hogy tizenkét évesen megszökött a náci Németországból, sem azokról a háború utáni küzdelmes évekről, amelyeket az anyjával Franciaországban töltött. De legfőképpen nem beszél az apjáról, aki a Harmadik Birodalom egyik leghírhedtebb haláltáborának volt a parancsnoka.\r\nAmikor új család költözik az alatta lévő lakásba, Gretel akarata ellenére is összebarátkozik a kisfiúval, Henryvel, jóllehet a fiú jelenléte olyan emlékeket idéz fel benne, amelyeket legszívesebben örökre elfelejtene. Aztán egyik este szemtanúja lesz egy megrendítő, erőszakos vitának Henry szülei között, amely veszélybe sodorja a nehezen kivívott, magának való életét.\r\nGretel olyan válaszút elé kerül, amilyennel egyszer régen már találkozott. Akkoriban tagadta saját felelősségét, de most, amikor megkérdőjeleződik benne bűnösség, gyász és bűntudat, dönthet úgy, hogy megment egy kisfiút. Ám ha így tesz, akkor kénytelen lesz felfedni azokat a titkokat, amelyeket egy életen át rejtegetett.',NULL),('Lingea Német zsebszótár - ...nem csak kezdőknek',40,2024,3,694,NULL,9789635050505,2460,1,32,2,'Új német-magyar és magyar-német zsebszótár, melyben a mai német nyelv szókincsét találja meg. Nem csak utazáskor vagy munkavégzéskor, hanem nyelvtanuláskor is hasznos társnak bizonyul majd.',7),('Norvég nyelvtani áttekintés ',40,2024,3,176,1,9789635051434,4265,12,32,1,'A nyelvtani áttekintésről:\r\n- a mai nyelvtani jelenségek használata\r\n- világos és tömör magyarázat\r\n- praktikus példák\r\n- megjegyzések, kivételek, érdekességek\r\n- keresztutalások\r\n- részletes szójegyzék\r\n- áttekinthető szerkezet\r\n- színes nyomtatás',7),('Lingea angol társalgás - Szótárral és nyelvtani áttekintéssel',40,2025,3,290,1,9789635051489,2840,3,32,1,'Lehetővé tesszük Önnek a kommunikációt utazásai során a mindennapi helyzetekben és vészhelyzetekben egyaránt, még akkor is, ha az adott nyelvben teljes kezdőnek számít. A hangsúlyt az aktív kommunikációra, az áttekinthetőségre és a szövegben való könnyű tájékozódásra fektettük.',7),('Lingea román társalgás - Szótárral és nyelvtani áttekintéssel',40,2025,3,280,1,9789635051502,3315,4,32,1,'Lehetővé tesszük Önnek a kommunikációt utazásai során a mindennapi helyzetekben és vészhelyzetekben egyaránt, még akkor is, ha az adott nyelvben teljes kezdőnek számít. A hangsúlyt az aktív kommunikációra, az áttekinthetőségre és a szövegben való könnyű tájékozódásra fektettük.',7),('Lingea szlovák társalgás - Szótárral és nyelvtani áttekintéssel',40,2025,3,320,NULL,9789635051663,3315,1,32,2,'Lehetővé tesszük Önnek a kommunikációt utazásai során a mindennapi helyzetekben és vészhelyzetekben egyaránt, még akkor is, ha az adott nyelvben teljes kezdőnek számít. A hangsúlyt az aktív kommunikációra, az áttekinthetőségre és a szövegben való könnyű tájékozódásra fektettük.',7),('A csodálatos hóember - és más mesék',34,2020,1,47,7,9789635200511,2660,1,28,3,'Három karácsonyi illetve téli mesét tartalmaz a könyv, mely a mesék kedves stílusa mellett a klasszikus orosz gyerekkönyv illusztráció egyik színvonalas példája. A mesék a barátságról és az igaztalan előítéletekről szólnak, így nevelgetve a mese élvezete mellett a kis olvasókat vagy hallgatókat.',7),('Ír tündérmesék ',33,2022,1,186,NULL,9789635593767,1990,1,28,2,'Az ír és kelta mitológia manapság az egyik legkedveltebb, legburjánzóbb és leghatásosabb, legkedveltebb kultúrkör az egész világon. A hihetetlen népszerűség a helyből táplálkozik, az ír sziget szemet gönyörködtető, lelket rabul ejtő, gondolatokat megbabonázó szépségéből, melyet több ezer éve népesítenek be csodálatos hősök, nagy királyok, félelmetes druidák, huncut manók, ártó szellemek, rosszcsont koboldok. Életük és harcaik, szerelmeik és küzdelmeik, szövetségeik és hőseik, vágyaik és félelmeik változatossága egyesül az ír sziget pazar tájaival és alkotja meg ezt a semmihez sem hasonlítható, egyedi tündérvilágot. Ebben a környezetben játszódnak a mesék, történetek, amiket Yeats gondos kézzel válogatott össze, és fésült szét fejezetekre, majd kiegészítette saját történeteivel. Yeats mellett további hét szerző írásaiból áll össze az a tizennégy történet, amelyet Yeats ebbe a kötetbe gyűjtött össze, finoman egyensúlyozva és adagolva az eltérő stílusú, eredetű, korú és hosszúságú meséket. Bátran rábízhatjuk magunkat William Butler Yeats kezére és szellemére: a hihetetlenül gazdag ír monda- és mesevilág színes keresztmetszetét kapjuk ettől a kötettől, ami első ízben jelenik meg magyar nyelven. Ez a gyűjtemény megerősíti Yeats meggyőződését, hogy a képzelet minden élet és művészet forrása. Remélem, hogy Magyarország gyermekei úgy élvezik majd ezeket a nagyszerű történeteket, ahogy az én gyermekeim, és ahogy őket, úgy a magyar gyermekeket is elröpíti a képzelet és álmok világába, a hajdani és mitikus Írország földjére.--Ronan Gargan, Írország magyarországi nagykövete.',NULL),('Árnyék és Csont',1,2021,1,373,1,9789635616770,4084,12,13,1,'Alina Starkova sosem várt túl sokat az élettől.\r\n\r\nA határháborúk során elveszítette a szüleit. Árvaként csupán egyvalakire számíthatott. Egy másik kis földönfutóra, Malra, a legjobb barátjára. Ám mostanra már ő sem lehet a támasza. Mindkettőjüket besorozták hazájuk, Ravka anyácska hadseregébe. A két fiatalnak életveszélyes küldetésre kell indulnia az Árnyzónába. Ezen az iszonyatos helyen a földöntúli sötétség az úr, ahol valósággal hemzsegnek az emberevő szörnyetegek.\r\n\r\nAmikor támadás éri a katonai konvojukat, mindannyiuk élete veszélybe kerül. Ám Alina ekkor olyan titokzatos erőnek adja tanújelét, amiről mindaddig még ő sem tudott. Csodálatos megmenekülésük váratlan következményekkel jár. Meg sem áll a fővárosig, az uralkodó udvaráig, ahol az árva lány a Grisa testvériség tagja lesz. Vezetőjük, a titokzatos Éjúr úgy véli, Alina az, akire oly régóta vár Ravka sokat szenvedett népe. A legfőbb varázsló szerint az Alinában rejtőző erő képes lesz elpusztítani az Árnyzónát.\r\n\r\nA cári udvar fényűző forgatagában sokan az Éjúr új kegyeltjének tartják a lányt, aki csak nehezen tud beilleszkedni Mal nélkül. Miközben hazája egyre nagyobb veszélybe kerül, feltárul előtte egy hajmeresztő összeesküvés. Döntenie kell. Szembeszáll a birodalom leghatalmasabb nagyuraival?\r\nEgyedül a múltja adhat reményt...\r\nMert csupán ez az árva lány mentheti meg a jövőt.',NULL),('Régi receptek, mai desszertek - 30 klasszikus kreatívan',30,2020,1,175,12,9789635650149,6175,10,26,1,'Dobos-torta, mákos guba, zserbó, hókifli és isler - mindenki ismeri és szereti őket, és óhatatlanul emlékeket idéznek fel. A nagymama utánozhatatlan, pihepuha mézes krémese; a kókuszkocka, amelyet kisgyerekként is boldogan mártogattunk a csokiba, majd meghempergettünk a kókuszreszelékben; a családi ünnepek elmaradhatatlan Esterházy-tortája...\r\nA szerző 30 jól ismert, klasszikus receptet alakít át a mai ízlésnek megfelelően, nagyrészt a francia cukrászatra épülő technikákkal, többféle izgalmas textúrával, légiesebb állaggal, a megszokottnál kevesebb cukorral, de annál több természetes alapanyaggal. Az egyszerű pohárdesszertektől kezdve az aprósütemények és komplex torták alapreceptjei mellett izgalmas ízbeli variációs lehetőségeket is találunk.\r\nÖtvös Zsuzsanna klasszika-filológia szakos doktori hallgatóként 10 éve indította el Praliné Paradicsom blogját. Először a csokoládé világa varázsolta el, majd olyannyira magával ragadta a cukrászat, hogy 2014-ben pályát váltott. Azóta több neves fine dining étteremben is dolgozott. 2018-ban jelent meg nagy sikerű első könyve Kreatív desszertiskola címmel. Jelenleg a Laurel Budapest cukrászséfje.\r\n\r\n\"Zsuzsi számomra a desszertek egyik hazai királynője. Lenyűgöz az az elegancia és finom arányérzék, ahogyan alkot, és pont ugyanilyen módon tudja felfrissíteni és vonzóvá tenni a klasszikus süteményeket is.\"\r\nMautner Zsófia\r\n\r\n\"Ötvös Zsuzsanna az egyik legkreatívabb magyar cukrászséf, aki képes arra, hogy még a méltán elfeledett klasszikusokból is könnyű és izgalmas, modern süteményt varázsoljon, ami visszahozza a legszebb nosztalgikus emlékeinket.\"\r\nJókuti András, Világevő',7),('Több mint desszert - 6 kedvenc alapanyagom 31 izgalmas receptben',30,2024,1,188,7,9789635655496,7125,20,26,1,'Puncskocka malátás piskótával, Eszterházy-torta miszóval, sajttorta kecskesajttal, leheletvékonyan rétegelt briós és sfogliatelle, citromtarte kamillával és madeleine hibiszkusszal megbolondítva...\r\nA kreativitásáról és művészi süteményeiről is ismert cukrászséf könyvében hat olyan alapanyagot választott főszereplőnek, amelyek meghatározóak a pályáján. A kakaóbab, a maláta, a miszó, a vaj, a sajtok és az ehető virágok köré épített receptekhez több nemzet desszertjei adtak ihletet: az elmaradhatatlan francia és olasz különlegességek mellett keleti édességek és természetesen újjáalkotott magyar desszertek is helyet kaptak.\r\nA megszokott ízvilággal sokszor szakító változatok nemcsak különleges kulináris élményt nyújtanak, de arra inspirálnak, hogy saját recepteket kreáljunk, és magunk is átéljük az alkotás örömét.\r\n\r\nÖtvös Zsuzsanna bölcsészként végzett. Hobbicukrászként indult, de olyannyira magával ragadta a desszertek világa, hogy 2014-ben pályát módosított. Több neves fine dining étteremben dolgozott, az ország legjobb cukrászséfjei között tartják számon. Korábbi két nagy sikerű könyve a Kreatív desszertiskola (2018) és a Régi receptek, mai desszertek (2020).\r\n\r\n,,Ötvös Zsuzsi a nyelvtudományok doktora, de aztán pályát módosított. Azóta a nyelv másfajta területeire - az ízlelőbimbókra - fókuszál. És milyen jól tette! Kivételes, őszinte szenvedély az övé... Nagy szerencsénk, hogy a legfinomabb >>nyelvtudományban',7),('Stonehenge - Az idő katedrálisa',15,2025,1,632,4,9789635668748,7990,12,8,1,'Seft, a bányászfiú a Nagy Síkságon járja útját a nyári hőségben, hogy ott legyen a szertartáson, mely az új év kezdetét jelzi. Azért tart az ünnepre, hogy elcserélje kovaköveit egyéb hasznos dolgokra, és megkeresse Neent, a pásztorlányt, akit szeret.',NULL),('Éltető étrend ',28,2024,1,90,NULL,9789635724079,5599,1,25,2,'Joia, Neen húga elbűvölve figyeli a nyárközepi szertartást. Minden vágya, hogy ő is a papnők egyike lehessen, és részt vehessen különleges rituális táncaikon, amelyeket egy nagy, fából készült kör körül járnak el.',NULL),('Jövőnk a Földön - Megoldások egy összeomló bioszférában',37,2024,1,463,5,9789635726387,5999,13,29,1,'Ám a dombokon és az erdők lombjai alatt már feszültség gyülemlik. Aszály pusztítja a földeket, egyre nő a bizalmatlanság a pásztorok, a földművesek és az erdőlakók között - mígnem egy kegyetlen tett nyílt háborúhoz vezet...',NULL),('Menekülés Budapestről ',4,2025,1,399,6,9789635828999,5999,1,8,2,'Joia a békésebb jövő lehetőségét látja meg egy olyan, hatalmas kőkörökből álló szentélyben, amelyet a síkság megosztott népei együtt hoznak létre. Ennek az elképzelésnek a megvalósítása lassan élete céljává válik, melynek elérésében Seft nyújt neki segítő kezet.',NULL),('Mindketten meghalnak a végén',2,2022,1,403,NULL,9789635842247,2799,12,14,2,'ADAM SILVERA gyönyörűen szívszaggató regénye fiatalok százezreit érintette meg. A TikTokon több mint 74 millió bejegyzés szól erről a könyvről, valamint a The New York Times sikerlistáján is bérelt helye van. ,,Mi, a Végső Barát Zrt. csapata, borzasztóan sajnáljuk, hogy elveszítünk. Őszinte részvétünk mindazoknak, akik szerettek, és azoknak, akik már sosem ismerhetnek meg téged. Reméljük, ma értékes, új barátra lelsz, és vele töltöd végső óráidat.\" Szeptember 5-én, kicsivel éjfél után a Halál-Hírek felhívja Mateo Torrezt és Rufus Emeteriót. Rossz hírei vannak számukra: még aznap meghalnak. Mateo és Rufus nem ismerik egymást, és más-más okokból ugyan, de mindketten szeretnének egy új barátot találni a Végnapjukon. A jó hír: erre is létezik egy alkalmazás, a neve: Végső Barát. Rufus és Mateo ennek segítségével akarnak találkozni, hogy együtt még egy utolsó, nagyszerű kalandban legyen részük - egyetlen nap alatt akarnak leélni egy egész életet. Adam Silvera bemutatkozó regényét a New York Times komoly, érzékeny műként jellemezte, most pedig itt az elismert író újabb virtuóz alkotása, a felemelő és megsemmisítő, elbűvölő és megragadó Mindketten meghalnak a végén. Ez a történet emlékeztet rá, hogy halál nélkül nincs élet, veszteség nélkül nincs szeretet - és egyetlen nap alatt is megváltoztathatjuk az egész világunkat.',NULL),('Az első, aki meghal a végén',2,2022,1,605,NULL,9789635843046,3499,12,14,2,'A New York Times-sikerlista első helyét meghódító, Mindketten meghalnak a végén előzménytörténetében hét évet ugrunk vissza az időben, és jelen lehetünk a Halál-Hírek első hívásánál. Ma éjjel kezd élesben a Halál-Hírek, így mindenkit ugyanaz a kérdés foglalkoztat: tényleg meg tudják jósolni, hogy valaki meg fog halni, vagy csak egy aprólékosan kitervelt átverés az egész? Orion Pagan évek óta várja, mikor közlik vele, hogy meg fog halni. Komoly szívbetegséggel él, és azért iratkozott fel a Halál-Híreknél, hogy tudja, mire számítson. Valentino Prince New Yorkban akarja újrakezdeni az életét. Hosszú, ígéretes jövő vár rá, és csak azt követően regisztrált a Halál-Híreknél, hogy az ikertestvére kis híján odaveszett egy autóbalesetben. Orion és Valentino a Times Square-en akadnak össze, és azonnal érzik, hogy közük van egymáshoz. Ám a legelső Végnapi hívások örökre megváltoztatják az életüket - egyiküket felhívják, míg a másikat nem. Noha azt egyik fiú sem tudja, miként végződik majd számukra ez a nap, abban biztosak, hogy együtt akarják tölteni... még ha utána keserves is lesz a búcsú. Az elismert író, Adam Silvera rá jellemző keserédes stílusban mesél arról, milyen óriási hatással vannak egymásra az emberek, és újra bebizonyítja, hogy mindig érdemes kihasználni életünk minden pillanatát. 18 éven felülieknek. ',NULL),('A Rettentő görög vitéz ',3,2025,1,54,11,9789635878208,4740,10,16,1,'A rettentő görög vitéz története ismert mitológiai témát dolgoz fel: az ifjú Thészeusz vándorlását meséli újra, küzdelmeit különféle útonállókkal és szörnyetegekkel, így a bunkós emberrel, a fenyőhajlítóval vagy éppen az alvilági kocával egészen az Ariadnéval való találkozásig és a Minótaurosz legyőzéséig. A mese tehát régi, de a szöveg nagyon is friss a nyelv, a forma, a szemléletmód új, modern és groteszk, sőt, szemtelen és pimasz, mint maga Thészeusz, az ifjú hős, a tizenéves durrbele kamasz. Baranyai András görög vázarajzokat idéző rajzai tökéletesen egészítik ki Zalán Tibor mesejátékát, hasonlóan keveredik bennük hagyományos és modern, mint magában a szövegben. A Stúdió K Színház többszörösen díjnyertes bábelőadásának könyv változata.',1),('Heartstopper 2. - Szívdobbanás - Fülig beléd zúgtam 2.',1,2022,1,320,1,9789635972968,3514,13,11,1,'\"Teljességgel elragadó. Aranyos, romantikus, kedves. A történet csodás tempóban halad. Imádom ezt a könyvet.\"\r\n-RAINBOW ROWELL, A Carry On szezrője\r\n\r\nNick\r\n\r\nAzért átjössz\r\nholnap?? :D\r\nMert lenne egy\r\nötletem\r\nMit szólnál egy\r\nigazi randihoz?\r\n\r\nOmg... hát PERSZE\r\nMit csináljunk? :)\r\n\r\nLehet meglepetés??\r\n\r\nOmg oké! Nagyon\r\nizgulok alkjdfldsg',4),('Heartstopper - Fülig beléd zúgtam - Szívdobbanás 1.',1,2022,1,263,1,9789635973828,3134,24,11,1,'Két fiú találkozik.\r\n\r\nKét fiú összebarátkozik.\r\n\r\nKét fiú egymásba szeret.\r\n\r\nCharlie és Nick egy suliba járnak, de nem ismerik egymást... mígnem egy napon egymás mellé ültetik őket. Egykettőre összebarátkoznak, Charlie pedig hamarosan belezúg Nickbe. Kár, hogy semmi esélye nála: Nick tipikus rögbis fiú, és biztos, hogy csak a lányok érdeklik...\r\n\r\nÁm a szerelem útjai kifürkészhetetlenek, és mintha Nick egyre közvetlenebb lenne Charlie-val...\r\n\r\nSzereted a Vörös pöttyös könyveket?\r\n\r\nVidd haza nyugodtan! Tetszeni fog.\r\n',4),('Heartstopper 3. - Szívdobbanás - Fülig beléd zúgtam 3.',1,2023,1,392,1,9789635974313,4274,30,11,1,'CARTE POSTALE\r\n\r\nSzia Tori!\r\nPárizs csodálatos!\r\nÉn, Nick és a barátaink szuperül érezzük magunkat! Viszont... volt némi dráma Taóval, és... hát, csomó minden történt. Majd otthon\r\nelmesélem!!\r\n\r\nCharlie\r\nx x x\r\n\r\n\" Teljességgel elragadó. Aranyos, romantikus, kedves. A történet csodás tempóban halad. Imádom ezt a könyvet.\"\r\n\r\n- RAINBOW ROWELL, a Carry On szerzője',4),('Heartstopper 4. - Szívdobbanás - Fülig beléd zúgtam 4.',1,2023,1,384,1,9789635974320,4274,5,11,1,'Nick naplója\r\n\r\nAzt hiszem, szerelmes vagyok Charlie-ba. Csodálatos volt együtt tölteni vele és a barátainkkal ezt a nyarat, és annyira\r\nszeretném kimondani neki, hogy szeretem, de... azt hiszem, vannak más dolgok, amik jobban aggasztanak mostanában...\r\n\r\nHa boldogságra van szükséged, lapozz bele!\r\n\r\n\"Az volt a célom, hogy olyan történetet írjak, amilyet én is szerettem volna olvasni, amikor én voltam tini.\"\r\n- Alice Oseman',4),('Nick és Charlie - Pasziánsz 1,5',1,2023,1,122,6,9789635976898,2184,23,19,1,'A hiánytól jobban szeret\r\na szív, igaz?\r\nMindenki tudja, hogy Nick és Charlie a\r\ntökéletes pár, és elválaszthatatlanok.\r\nDe Nick most egyetemre megy, Charlie pedig\r\nvégzősként a suliban marad. Ahogy közeledik\r\na búcsú ideje, mindkét fiúban felmerül a\r\nkérdés: vajon elég erős a szerelmük\r\nahhoz, hogy túléljék a különválást?\r\nElvégre az első szerelem\r\nritkán tart örökké...\r\nGyere, és olvasd el Nick és Charlie\r\ntörténetének újabb fejezetét!\r\nNem titok, hogy abszolút imádom\r\na Heartstopper-képregényeket, és ez a\r\nszerelem itt nem ért véget. A Nick és Charlie\r\nremek kiegészítője a sorozatnak, jó volt\r\nvégre belelátni a srácok lelkivilágába.\"\r\n- Young Creative Press',6),('Rule of Wolves - Farkasok törvénye ',1,2024,1,530,1,9789635977628,5034,23,13,1,'A sebhelyes cár várva várt lezárása megérkezett!\r\n\r\n\r\nFjerda hatalmas serege támadásra készül, Nyikolaj Lancov pedig minden leleményét és sármját - sőt, a benne rejlő szörnyeteget is - beveti, hogy megnyerje a háborút. Csakhogy mindeközben egy olyan sötét erő is\r\nfenyegeti, amely még az ifjú cár számára is végzetes lehet.\r\n\r\n\r\nZója Nazjalenszkaja túl sokat veszített a korábbi háborúban. Végignézte, ahogy a mentora meghal, és a legnagyobb ellensége feltámad, és nem hajlandó eltemetni még egy barátot. A kötelesség most azt követeli tőle, hogy használja a legtitkosabb képességét is, mert az országának minden fegyverre szüksége van. Bármi lesz is az ára.\r\n\r\n\r\nNyina Zenyik a lebukást és az életét kockáztatja azzal, hogy kémként beépült Fjerda fővárosi elitjébe. Összetört szíve még nem gyógyult be, és ha nem vigyáz, a bosszúvágya miatt az országa minden esélyét elveszti a háborúban.\r\n\r\n\r\nA világsikerű sorozat zseniálisan megírt befejező része.',NULL),('Heartstopper 5. - Szívdobbanás - Fülig beléd zúgtam 5.',1,2024,1,336,1,9789635977994,3514,7,11,1,'Nick és\r\nCharlie\r\nszerelmesek\r\nEGYETEMI\r\nTÚRATERV\r\nÍrta: Tara, Elle és Nick :)\r\nDe most hogyan tovább?',4),('Loveless - Szerelem nélkül',1,2024,1,399,6,9789635979776,4084,10,19,1,'Mikor kezdődik már az ő szerelmi története?\r\nA fanficmegszállott Georgia még sosem volt szerelmes, sosem csókolózott, még csak bele sem zúgott senkibe, soha. De örök romantikusként biztos benne, hogy egy nap meg fogja találni az Igazit. Amikor elkezdi az egyetemet, készít egy tervet, hogy miként találhat rá a szerelemre. Ám a tettei fájdalmat okoznak a barátainak, így felteszi magának a kérdést, miért tűnik olyan könnyűnek a romantika mások számára, míg neki nem az.\r\nÚj címkéket aggatnak rá - aszexuális, aromantikus -, és ezek miatt Georgia még inkább elbizonytalanodik\r\naz érzéseiben. Az a sorsa, hogy szeretet nélkül éljen? Vagy mindvégig rossz dolog után kutatott?\r\nEbben az önazonosságról és önelfogadásról szóló bölcs, együttérző és szellemes történetben Alice Oseman csúcsformában tündököl, miközben Georgia és a barátai felfedezik, hogy az igaz szeretet nem korlátozódik a romantikára.\r\nHagyd, hogy elvarázsoljon!',NULL),('Az Éhezők Viadala - Az Éhezők Viadala-trilógia 1. kötete',8,2025,1,303,6,9789635980840,4731,23,19,1,'A győztes jutalma hírnév. A vesztes büntetése halál. A közeljövő egy sötét világában tizenkét fiú és tizenkét lány küzd egymással egy élő televíziós show-ban, aminek a címe Az éhezők viadala. Egyetlen szabály van: ölj vagy megölnek. Amikor a tizenhat éves Katniss Everdeen a húgát mentve önként jelentkezik, hogy részt vegyen a viadalon, az felér egy halálos ítélettel. De Katniss már nem fél a haláltól. A túlélés a vérében van.',NULL),('A nappá vált lány ',8,2023,1,447,5,9789635981175,5206,12,13,1,'A Mulan és az Akhilleusz dala találkozik ebben a költői bemutatkozó regényben, ami háborúról és végzetről szól egy alternatív, lenyűgöző Kínában.\r\n\r\nEgy poros, sárga síkság éhínségtől sújtott falujában két gyerek két sorsot kap. A fiúé lesz a nagyszerűség. A lányé pedig a semmilét...\r\n\r\n1345-ben Kínát kemény kézzel vezetik a mongolok. A Középső Síkság éhező földművesei a nagyszerűséget csupán a mesékből ismerik - amikor azonban a Csu család nyolcadik fiának, Csu Csungpának mégis e sorsot jósolják, senki sem érti, az vajon miként válik majd valóra. A semmilét sorsa azonban, amit a család okos és leleményes másodszülött lánya kap, egyáltalán nem meglepő.\r\n\r\nAmikor útonállók támadása miatt árván marad a két gyerek, Csu Csungpa az, aki megadja magát a kilátástalanságnak, és meghal. A lány, aki kétségbeesetten szeretne menekülni megjövendölt halála elől, a bátyja személyazonosságát használva novíciusnak áll egy kolostorban. Ott a túlélés iránti, égető vágyától ösztökélve megtanulja, nem számít, milyen könyörtelen dologról van szó, bármit képes megtenni azért, hogy elrejtőzzön a végzete elől. Sőt, Csu idővel megpróbálja kihasználni a lehetőséget, hogy egy teljesen más jövőt szerezzen meg magának: a bátyja gazdátlanná vált nagyszerűségét.',NULL),('A sötétségbe fojtott világ',8,2024,1,576,2,9789635982448,6631,12,13,1,'Mennyit áldoznál fel azért, hogy megszerezd a világot?\r\n\r\nCsu Jüancsang, a Fénylő Király, csodálatos győzelmet aratott, amikor elszakította Kína déli részét mongol uraiktól. Most új vágytól ég: meg akarja szerezni a trónt, és császárrá akarja koronázni magát.\r\n\r\nNem ő azonban az egyetlen, akit efféle becsvágy hajt. Déli szomszédja, Csang asszony, a kurtizán, a férjének akarja megszerezni a trónt - és elég erős hozzá, hogy eltörölje Csút a Föld színéről. Ahhoz, hogy játékban maradjon, a fiatal nőnek kockára kell tennie mindent, és szövetségre kell lépnie egy régi ellenségével, a tehetséges, ám kiszámíthatatlan eunuchhal, Oujang tábornokkal, aki már mindent feladott azért, hogy bosszút állhasson apja gyilkosán, a nagykánon.\r\n\r\nA déliek tudtán kívül egy új szereplő még közelebb került a trónhoz. A lenézett tudós, Vang Paohsziang addig mesterkedett, amíg el nem jutott a fővárosba, és most halálos udvari játékai azzal fenyegetnek, hogy térdre kényszerítik a birodalmat. Paohsziang ugyanis szintén bosszúra éhezik: ő akar lenni a történelem legelfajzottabb nagykánja, hogy ezzel űzzön gúnyt az értékekből, amelyeket mongol harcosokból álló családja jobban szeretett nála.\r\n\r\nA trónkövetelők eltökélték, hogy bármit megtesznek a győzelemért. Csakhogy amikor az ember vágyának tárgya az egész világ, az még a legkegyetlenebbek számára is túl sokba kerülhet...',NULL),('Jó kislányok kézikönyve gyilkossághoz',35,2025,1,473,6,9789635992201,4794,12,17,1,'Öt évvel ezelőtt Andie Bellt, a Little Kilton-i gimnázium diákját megölte a barátja. A rendőrség így tudja. A városban mindenki így tudja. A gyilkosság emléke azóta kísérti a kisváros lakóit, bár az élet látszólag nyugodt mederben folyik tovább. Pippa, a gimnázium egyik végzős diákja elhatározza, hogy egy iskolai projekt keretében előveszi az ügyet, és kideríti, mi történt valójában. Ő sosem hitte el, hogy Sal Singh a gyilkos. De ha nem ő az, akkor ki? És vajon meddig fogja tétlenül nézni, hogy Pippa egyre közelebb kerül a megdöbbentő igazsághoz?\r\nKegyetlen társasjáték, ahol egy kisváros a játéktábla, és fogalmad sincs, ki nevet a végén...\r\n\r\nA Londonban élő Holly Jackson magyarul most debütáló regénye igazi adrenalinlöket, tele meglepő csavarokkal és sokkoló lezárással. Az olvasó együtt nyomoz a főhőssel: e-mailek, sms-ek, Facebook-posztok, interjúk és naplóbejegyzések rántanak a történet mélyére és tartanak lebilincselve.\r\n2019-es megjelenése óta a regény csak az angol nyelvterületen több mint 180 ezer példányban kelt el, és számos díjat nyert. 2020-ban Holly Jackson krimijének ítélték a rangos British Book Awards díjat, és fél évig vezette a New York Times sikerlistáját is, kiadási jogát 19 ország vásárolta meg. A Jó kislányok kézikönyve gyilkossághoz folytatása (Good Girl, Bad Blood) szintén eladási rekordokat döntöget.\r\n',NULL),('Rachel Price visszatérése ',35,2025,1,210,NULL,9789635995851,3899,1,16,2,'A tizennyolc éves Bel egész életében egy rejtély árnyékában élt.Tizenhat évvel ezelőtt az édesanyja, Rachel Price különös körülmények közt eltűnt, halottnak hiszi mindenki.Ám amikor a Price család beleegyezik, hogy dokumentumfilm készüljön a megoldatlan esetről, megtörténik az elképzelhetetlen: Rachel Price hirtelen visszatér, és egy furcsa történettel áll elő.Bel biztos benne, hogy az anyja hazudik. De ha igaza van, akkor hol volt Rachel egész idő alatt? Miközben a kamerák még forognak, Bel nyomozni kezd: miért tért vissza Rachel Price? És miért érzi úgy, hogy veszélyt jelent az egész családjára?\"- Ki vagy te? - kiáltott át neki.A nő megállt, lassan felé fordult, pislogva igyekezett védekezni a napfény ellen.Felelnie sem kellett.Bel tudta. A csontjaiban, az ösztöneiben, olyan módon, amit nem lehet tanulni, csak tudni, érezni. A szíve lebukfencezett egy sziklaszirtről, egyenesen savtól kavargó gyomrába.A kékesszürke szempár éppen olyan volt, mint az övé. Az álla finom ívű, hegyes. Hamuszürke bőre világosabb, mint amire emlékezett, ráncosabb is, hiszen tizenhat év hagyta rajta a nyomát. A homlokán a kicsi, világosbarna anyajegy.A nő úgy nézett rá, mintha szintén tudna valamit.Rachel Price.Visszatért.\"',NULL),('Jó kislányok, rossz viszonyok',35,2025,1,427,6,9789635995929,4274,6,17,1,'A Londonban élő Holly Jackson magyarul most debütáló regénye igazi adrenalinlöket, tele meglepő csavarokkal és sokkoló lezárással. Az olvasó együtt nyomoz a főhőssel: e-mailek, sms-ek, Facebook-posztok, interjúk és naplóbejegyzések rántanak a történet mélyére és tartanak lebilincselve.',NULL),('Még nem egészen halott ',35,2025,1,445,6,9789635996223,5999,7,17,1,'2019-es megjelenése óta a regény csak az angol nyelvterületen több mint 180 ezer példányban kelt el, és számos díjat nyert. 2020-ban Holly Jackson krimijének ítélték a rangos British Book Awards díjat, és fél évig vezette a New York Times sikerlistáját is, kiadási jogát 19 ország vásárolta meg. A Jó kislányok kézikönyve gyilkossághoz folytatása (Good Girl, Bad Blood) szintén eladási rekordokat döntöget.',NULL),('A fiú, aki nem akart meghalni',35,2024,1,203,NULL,9789635996810,2799,1,16,2,'Péter Makón él, összetartó nagy család szeretetében, a tisztes családi vállalkozás nyújtotta biztonságban, viszonylagos jólétben. Ám eljön 1944 márciusa, és a kisfiúnak szembesülnie kell azzal, hogy zsidónak lenni sokak szemében megbocsáthatatlan bűnnek számít. Még nincs ötéves, amikor el kell indulnia a nyolc vonatozásból és két buszozásból álló \"nagy utazásra\", amelynek legtávolabbi pontja a bergen-belseni koncentrációs tábor, ahonnan csak azért térhet vissza élve, mert okos, erős édesanyja a legnagyobb szörnyűségek közepette is hősiesen óvja, védi. Elgondolkodtató, szívszorító történet arról, hogyan élte túl a vidéki kisgyerek a XX. század egyik legrémesebb gaztettét, a holokausztot. Azon a napsütötte márciusi délutánon 1944-ben még nem tudtam, hogy a következő néhány hónap során az életem mindenestől felfordul majd. A fűrésztelepünkön sétáltam anyu kezét fogva. Még ötéves sem voltam, de már eleget láttam és hallottam ahhoz, hogy érzékeljem: a dolgok megváltozhatnak. * A vagon ismét nagyon zsúfolt volt, apu szerint legalább hetvenen voltunk bent, de talán többen is. Az a kevés ennivaló, amit hoztunk, hamar elfogyott, és utána nagyon éhes lettem. Soha életemben nem voltam még annyira éhes. Ráadásul elfáradtam az ácsorgástól. Anyu azt javasolta, hogy üljek le közte és apu között, a cipőjükre. Így sokkal jobb volt. * A hosszú csendben elkezdtem összeszámolni a család halottait. Huszonegyig jutottam, amikor kitört belőlem a zokogás, és csak akkor nyugodtam meg, amikor anyu átölelt',NULL),('A főzés tudománya - Konyhai praktikák izgalmasan és látványosan',32,2023,1,256,7,9789636042486,7599,5,20,1,'Rántsuk le a leplet a konyhai mítoszokról!\r\n\r\nZúzzuk vagy vágjuk a fokhagymát?\r\nHogyan őrizhetjük meg a zöldségek tápértékét főzéskor?\r\nMikor adjuk az ételhez a zöldfűszereket?\r\nHogyan marad a hal szaftos sütéskor?\r\n\r\nA főzés tudománya forradalmian új szemléletű kötet, amely segít, hogy jobban megértsük a konyhai folyamatokat, és ezáltal jobban, kreatívabban főzhessünk.\r\n\r\n- Praktikus, kutatási eredményekkel alátámasztott válasz 160 alapvető konyhai kérdésre.\r\n- A leggyakoribb főzési eljárások, alapanyagok és konyhai eszközök közérthető elemzése.\r\n- Látványos, informatív illusztrációk.\r\n\r\nDr. Stuart Farrimond orvosból lett élelmiszerkutató, aki előadásaiban, illetve írásaiban a tudomány és a főzés titkaiba avatja be olvasóit és hallgatóit.',7),('Harry Potter és a bölcsek köve ',25,2025,1,335,6,9789636140540,5690,22,19,1,'A Harry Potterről szóló, hétkötetesre tervezett regényfolyam első része. A könyvben megismerkedhetünk többek között a Roxfort varázslóiskolával, Harryvel, a varázslópalántával, és tanúi lehetünk csodálatosan izgalmas kalandjainak. \"Harry Potter kisfiú, történetünk kezdetén 11 éves, valamint varázsló is, talán a leghatalmasabb varázsló, a kiválasztott, aki meg tud küzdeni a gonosz erőivel, erről azonban fogalma sincs. (..) Harry aztán egy napon levelet kap, pontosabban néhány tízezer levelet, a biztonság kedvéért, mivel a nagybácsi elkobzós kedve magasra hág, amelyből megtudja, hogy a következő szemesztert Roxfortban kezdheti, a világ legnevesebb bentlakásos varázslóiskolájában, amely nem kis mértékben hasonlít a brit iskolarendszer hírhedett public schooljaira, talán attól eltekintve, hogy koedukált. Harry, a kifosztott árva ekkor belép abba a világba, amelyhez szülei is tartoztak, hogy megküzdjön azzal a Ki-Ne-Mondd-A-Nevét sötét erővel, amely árvává tette. Harry kiválasztott, homlokán a jegy, de egyben közönséges nebuló is, akinek minden kiválasztottsága ellenére fel kell mutatnia valamit, esetünkben kiemelkedő sportteljesítményt és kellő csapatszellemet, hogy elnyerje az egyszerű diáktársat megillető tiszteletet, és megússza valahogy a vizsgáit. A Gonosz Erőt nem könnyű legyőzni, de egy elitiskola hierarchiájában kiküzdeni valami helyet, főként, ha az alsóbbrendű muglik között nevelkedett az ember, és mit sem tud a magasabb bűbájról, az még nehezebb. Több tucatnyi sajtótermék próbált már magyarázatot találni Harry Potter sikerére. Kezdjük talán azzal, hogy a könyv jó, szellemes, technikás, sodorja az olvasót, és ez elmondható a magyar kiadásról is, amely eltalálta a helyes középutat a máris nemzetközi kultusz tárgyát alkotó invenciók (Muggle: a tökfej normális világ, Quidditsch: a nagy nemzeti varázsló sport) túlzott magyarítása és elvtelen átvétele között.\" Babarczi Eszter, MagyarNarancs, 2000',NULL),('Harry Potter és a Halál ereklyéi ',25,2025,1,651,6,9789636140564,5690,23,19,1,'Amikor a tizenhetedik évét betöltő Harry ezúttal Hagrid motorjának oldalkocsijában utoljára hagyja el a Privet Drive-ot, az őt védő bűbáj szertefoszlik, és a halálfalók azonnal a nyomába erednek. A Főnix Rendje azon fáradozik, hogy biztos helyre szöktesse őt, csakhogy Harrynek a bujkáláson kívül egyéb tervei is vannak: Dumbledore professzortól kapott feladatát kell végrehajtania. Így a tanév nélküle kezdődik el a Roxfortban. Vajon sikerül-e a folytonos életveszély közepette teljesítenie a küldetést, amitől a végső összecsapás kimenetele függ?',NULL),('Harry Potter és a Tűz Serlege',25,2024,1,623,6,9789636140571,5690,21,19,1,'Harry Potter vakációja a szokásosnál jobbnak ígérkezik: részt vehet a varázsvilág legnagyobb sportünnepén, a Kviddics Világkupán. Ám az egybegyűltek szórakozása korántsem alakul felhőtlenül: baljós történések zavarják meg az eseményt. A Roxfort Boszorkány- és Varázslóképző Szakiskolába visszatérő diákok azonban hamar elfeledkeznek a meccsről, mivel kiderül, hogy ez évben a Roxfortban rendezik meg a Trimágus Tusát. Harry csak szurkolni készül a bajnokoknak, ám váratlanul maga is köztük találja magát. A próbák életveszélyesek, így gyanítható, hogy aki tudtán kívül benevezte Harryt a tusára, az bizony az életére tör.',NULL),('Harry Potter és az azkabani fogoly',25,2020,1,478,6,9789636140878,4645,24,19,1,'A Sötét Nagyúr most erőtlen s magányos. Hívei elfordultak tőle. Szolgája tizenkét éve rabságban senyved. Ma este, még éjfél előtt, a szolga kiszabadul, és visszatér urához. Segítségével a Sötét Nagyúr erőre kap, s hatalma rettentőbb lesz, mint valaha.\r\nHarry Potter szokásos rémes vakációját tölti Dursley-éknél, ám a helyzet úgy elfajul, hogy Harry elviharzik a Privet Drive-ról. Így köt ki a Kóbor Grimbuszon, ami elviszi őt abba a világba, ahová egész nyáron vágyott. Az Abszol úton ijesztő hírek járják: az Azkabanból, a gonosz varázslókat őrző rettegett börtönből megszökött egy fogoly. A Mágiaügyi Minisztériumban tudják, hogy a veszélyes szökevény a Roxfort Boszorkány- és Varázslóképző Szakiskolába tart. Harry pedig egy véletlen folytán tudomást szerez róla, hogy az illető az ő nyomát követi.\r\nHarry harmadik évét a Roxfortban baljós ómenek kísérik. Egyre inkább feltárul előtte saját múltja, és Voldemort leghűségesebb szolgájával is farkasszemet kell néznie.\r\nA Kate Greenaway-díjjal kitüntetett Jim Kay pazar illusztrációkkal jeleníti meg J.K. Rowling varázslatos világát az immár klasszikus sorozat harmadik kötetében.',NULL),('Harry Potter és a Titkok Kamrája ',25,2025,1,365,6,9789636141479,4075,20,19,1,'Harry Potter, aki éppen egy éve tudta meg magáról, hogy varázslónak született, Dobby figyelmeztetése ellenére tovább folytatja tanulmányait a Roxfort Boszorkány- és Varázslóképző Szakiskolában. Mivel lekési a különvonatot, barátjával, Ronnal együtt egy repülő autón érkezik tanulmányai színhelyére. S a java csak ezután következik! Hamarosan bebizonyosodik, hogy Dobby nem a levegőbe beszélt, amikor óvni próbálta őt.',NULL),('Harry Potter és az elátkozott gyermek',25,2025,1,319,5,9789636142216,5405,12,19,1,'Harry Potter élete sosem volt könnyű - és most sem az, amikor a Mágiaügyi Minisztérium túlhajszolt dolgozójaként, férjként és három iskoláskorú gyermek apjaként kell helytállnia.\r\nMiközben Harry a múlttal viaskodik, kisebbik fiának, Albusnak is meg kell küzdenie a reá nehezedő családi örökséggel. A múlt és a jelen vészjósló összeolvadása azzal a ténnyel szembesíti apát és fiát, hogy a sötétség néha egészen váratlan helyekről támad.\r\n\r\nEz a kötet a londoni West Enden bemutatott Harry Potter és az elátkozott gyermek című díjnyertes színielőadás teljes és hivatalos szövegkönyve.\r\nTartalmazza a végleges párbeszédeket és rendezői utasításokat, egy beszélgetést a színdarab írója, Jack Thorne és a rendező John Tiffany között, a Potter-családfát, valamint egy idővonalat, amelyen végigkövethetjük a varázsvilág eseményeit, amelyek elvezettek a Harry Potter és az elátkozott gyermek történetéhez.',NULL),('Harry Potter és a Félvér Herceg',25,2024,1,618,6,9789636144913,6165,26,19,1,'A Voldemort elleni harc állása aggasztó; a baljós jeleket már a muglikormány is észleli. Szaporodnak a rejtélyes halálesetek, katasztrófák. Harry azt gyanítja, hogy esküdt ellensége, Draco Malfoy is a halálfalók jelét viseli. Az élet azonban háborús időkben sem csak harcból áll. A Weasley-ikrek üzleti tevékenysége egyre kiterjedtebb. Szerelmek szövődnek a felsőbb évesek között, a Roxfort házai pedig továbbra is versengenek egymással. Harry Dumbledore segítségével igyekszik minél alaposabban megismerni Voldemort múltját, ifjúságát, hogy rátaláljon a Sötét Nagyúr sebezhető pontjára.',NULL),('Mert többen nincsenek',6,2024,1,301,NULL,9789636205355,2599,1,16,2,'Agatha Christie leghíresebb és legnépszerűbb krimijében, amely korábban Tíz kicsi néger címen jelent meg magyarul, nyolc ember kap meghívást egy kis szigetre - ahol aztán az időjárás szeszélye elvágja őket a külvilágtól, a szakácsnővel és az inassal együtt. Rejtélyes meghívójuk furcsa módon nem bukkan fel, de a vendégeket ez eleinte nem zavarja: a szakácsnő remekül főz, és a portói bor kiváló. A vacsora után azonban megszólal egy hang, amely mindannyiukat megvádolja. Éspedig azzal, hogy gyilkosságban vétkesek. Egyikük nem sokkal később meghal... és az ebédlőasztalon a tíz kicsi katonafigurából egy eltűnik.\r\nVajon igazak a vádak? Mindannyian bűnösök? És ki lehet az, aki úgy döntött, a szigetre csalja őket, és egyenként, művészi tökéllyel végrehajtja rajtuk a lehető legszigorúbb ítéletet?',NULL),('Halloween és a halál ',6,2025,1,346,1,9789636207007,3799,12,17,1,'\"A szép dolgokat nézni kellemes elfoglaltság, de az ember már-már elvből utasítja el a szépséget magát. Egy nő, persze, megengedheti magának, hogy szép legyen, gondolta Hercule Poirot, abban azonban egyáltalán nem volt biztos, mit gondoljon a férfiúi szépségről. Ő a maga részéről sohasem vágyott rá, hogy szép fiatalember lehessen, nem mintha erre bármiféle esélye lett volna valaha is.\" Mrs. Drake Woodleigh Common-i házában Mindenszentek előestéjén halloween-partit rendeznek. Ez idő tájt a kisvárosban vendégeskedik az ismert krimi-írónő, Mrs. Ariadne Oliver is, aki szintén segédkezik Mrs. Drake-nek a gyerekzsúr előkészületeiben. A sürgés-forgás közben a tizenhárom éves Joyce Reynolds azzal henceg Mrs. Olivernek és a többi gyereknek, hogy régebben ő már szemtanúja volt egy igazi gyilkosságnak. A jelenlévők, kivétel nélkül, csak egyszerű szájhősködésnek tartják Joyce állítását, egészen addig, míg a zsúr végén holtan nem találják a kislányt. A könyvtárszobában valaki az almahorgászáshoz használt vödör vízbe fojtotta. Mrs. Oliver régi barátjához, a zseniális Hercule Poirot-hoz fordul segítségért.',NULL),('Jó cukor, rossz cukor',26,2024,1,103,NULL,9789636331061,3299,1,25,2,'A Leszokni a dohányzásról? Így könnyű! szerzőjének új könyve 16 millió eladott példány világszerte Az Allen Carr-féle Easyway minden idők legsikeresebb módszere, számos függőség leküzdésében segít. A Jó cukor, rossz cukor a modern táplálkozás legveszélyesebb jelenségével, a finomított cukortól és a feldolgozott szénhidrátoktól való függéssel foglalkozik. Ez utóbbi felelős az elhízás és a 2-es típusú cukorbetegség világjárványának kirobbanásáért. A kötet segítségével az olvasó energikusabb, egészségesebb, boldogabb és kiegyensúlyozottabb életet élhet. Allen Carr módszerét követve nemcsak könnyen megszabadulhatsz a ROSSZ CUKORTÓL, hanem élvezni is fogod a leszokás folyamatát. Nem egyszerűen szabaddá válsz, hanem boldogság tölt el, hogy szabad lehetsz. Biztosan úgy érzed: túl szép, hogy igaz legyen, de olvass csak tovább. Veszítenivalód nincs, annál többet nyerhetsz. Allen Carr (1934-2006) brit szerző önsegítő könyveiben a függőségekkel foglalkozik, módszere többek közt a dohányzásról és az alkoholról való leszokásban segít. Az általa alapított Easyway klinikák több mint 50 országban működnek, és eddig mintegy 50 millió embernek segítettek megszabadulni szenvedélybetegségétől.',NULL),('Két könyv között... minden, ami csirke! ',29,2025,1,153,NULL,9789636397999,2990,1,20,2,'Két könyv között... ... minden, ami csirke! Egy újabb sztorizós szakácskönyv - ezúttal A Magyar Könyv is Magyar Termék Mozgalom hivatalos bloggereitől. Aki olvasta a Most főzünk, vagy dumálunk? vagy a Most főzünk, vagy bulizunk? című szakácskönyveket, már sejtheti, hogy mire készüljön ismét! Ezúttal az én ,,csibéimmel\", azaz a bloggerekkel fogok egy különleges szakácskönyv-sorozatot az útjára indítani. Lesz itt minden: receptek, történetek, könyves élmények, saját írások! Első alkalommal a csirke kerül az asztalra - meg a tepsibe, fazékba. Mellé kínálunk rengeteg kacagtató sztorit, még ha nem is köretnek, de felhőtlen szórakozásnak! Üdvözlettel a konyhából és a könyvek mellől: Sky S.T. - Sütő Éva (Sky) és szerzőtársai: Elena Honoria (Elena), Haupt-Kutas Mónika (Móni), Lexy Könyv Otthona (Lexy), Menyhei Mónika (Moncsi), Nagy Dóra (Dóri), Oláh Timi (Timi), Pálinkás Angéla (Angi), Társszerzők: Elena Honoria, Haupt-Kutas Mónika, Lexy Könyv Otthona, Menyhei Mónika, Nagy Dóra, Oláh Timi, Pálinkás Angéla,',NULL),('I Was Born For This - Erre születtem',1,2024,1,364,6,9789636751494,3514,8,19,1,'- Meg fogok halni. Tökre meg fogok halni!\r\n- Ezt nem javasolnám - mondja Juliet, mintha kéthetes nyaraláson járt volna a Túlvilágon, és a TripAdvisoron ötből két pontot adott volna neki.\r\n\r\nAngel számára az élet egyetlen dologról szól: a The Arkról, egy tinédzserfiúkból álló pop-rock trióról, akik rohamléptekkel hódítják meg a világot. Mindent, amit szeret, a The Ark-fandomnak köszönhet: a barátját, Julietet, az álmait, a helyét a világban.\r\n\r\nJimmy mindent a The Arknak köszönhet. Ő a frontemberük - és egy bandában játszani a haverjaival minden, amiről valaha álmodott.\r\n\r\nDe az álmok nem mindig úgy alakulnak, ahogyan azt gondoljuk, és amikor Jimmy és Angel váratlanul\r\ntalálkoznak, rájönnek, milyen furcsa és meglepő lehet szembenézni a valósággal.\r\n\r\nVicces és bölcs. Lenyűgözően mutatja meg, milyen ereje van annak, ha hiszünk valamiben - különösen önmagunkban.\r\n\r\nHagyd, hogy magával ragadjon!',NULL),('Percy Jackson és az olimposziak 6. - Az istenek kelyhe ',1,2025,1,256,7,9789636751944,3999,15,16,1,'Félig halandó. Félig isten. Ízig-vérig hős.\r\nPercy Jackson és barátai legújabb története megérkezett!\r\nA villámtolvaj hősei újra összeállnak, hogy szembenézzenek eddigi legnagyobb kihívásukkal, és az istenek akadékoskodása ellenére bejuttassák Percyt az egyetemre.\r\nPercy Jackson, miután többször is megmentette a világot, reméli, hogy rendesen leérettségizhet. Sajnos az istenek még nem végeztek vele.\r\nPercynek három küldetést kell teljesítenie ahhoz, hogy megszerezze az Olimposz-hegyről a továbbtanuláshoz szükséges három ajánlólevelet.\r\nElső küldetése során Zeusz pohárnokának kell segítenie visszaszerezni az aranykelyhet, mielőtt az rossz kezekbe kerülne. Vajon Percy, Grover és Annabeth időben sikerrel jár?\r\nA könyv önállóan is élvezhető. Az új olvasók és azok a rajongók, akik már több mint egy évtizede kísérik figyelemmel hőseink kalandjait, egyformán örülni fognak a görög mitológia legújabb remek, poéndús feldolgozásának.\r\nIsmerd meg te is Percy Jackson legújabb kalandjait!',NULL),('Európa Comfort térkép - Autótérkép',38,2025,1,2,NULL,9789636800024,4990,10,9,1,'Egylapos, hajtogatott, két oldalon laminált, 1:4M méretarányú térkép. Tartós, könnyen kezelhető, vízálló, felülete írható és törölhető (ideális útvonaltervezéshez). Ötnyelvű jelmagyarázattal.\r\n\r\nJellemzők:\r\n\r\n- A térkép az európai törzsterületet egyben ábrázolja Kelet-Európával együtt\r\n- Skandinávia és Izland melléktérképek 1:10 300 000-es méretarányban\r\n- Autópályák, főutak, fontosabb utak\r\n- Autószállító kompok, alagutak\r\n- Európai és helyi útszámozás\r\n\r\nA speciális kivágás miatt könnyen hajtogatható térkép, mely cseppálló fóliával van ellátva. Alkoholos filctollal írható és letörölhető.\r\n\r\nVáltozások az előző kiadáshoz képest:\r\n\r\nÚj autópályák, gyorsforgalmi utak és elkerülő utak a teljes kontinensen:\r\n- Magyarország: M6, M44, M85\r\n- Románia: A3, A10, M4 csatlakozása, Szatmárnémeti elkerülő út, Temesvár elkerülő út\r\n- Horvátország: A5\r\n- Szlovákia: D1, D4, R7\r\n- Norvégia: Rogfast alagút\r\n- Törökország: O-7 autópálya Isztambulnál új Boszporusz híddal, O-6 autópálya új híddal a Dardanelláknál\r\n- nagyvárosi elkerülő utak',7),('Börzsöny turistatérkép - Nagy-Hideg-hegy és Csóványos térképével',38,2025,1,2,NULL,9789636800055,3490,7,9,1,'Az aktualizált, új kiadású Börzsöny turistatérkép 1:40000 méretarányban részletesen és naprakészen ábrázolja a látnivalókat, a sokrétű szabadidős lehetőségeket, ezáltal nélkülözhetetlen társa az aktív turisztikai formák kedvelőinek.\r\n\r\nÍzelítő az aktualizált Börzsöny turistatérkép újdonságaiból:\r\n- az új Ipoly-hidak Ipolydamásd-Helemba és Drégelypalánk-Ipolyhídvég között\r\n- az új Szob-Ipolydamásd(-Letkés) kerékpárút (az EuroVelo6 nyomvonala)\r\n- a \"Horizont\" kerékpáros kalandtúra-útvonal térségi szakasza (Nagymaros-Nagyoroszi)\r\n- az Ipoly menti víziturisztikai táborozóhelyek\r\n- a Börzsöny naprakész turistaút- és kerékpáros útvonal-hálózata\r\n- új, teljesen megváltozott turistaútjelzés-rendszer Királyrét és a Csóványos között\r\n- a Naszály új, leegyszerűsített turistaúthálózata\r\n- az új szobi hajóállomás\r\n\r\nA térkép előoldalán kapott helyet a Nagy-Hideg-hegy-Csóványos (1:25.000) és a Naszály (1:40.000) melléktérképe, a hátoldalon Nagybörzsöny településismertetője és a Szob-Nagybörzsöny kisvasút ismertetője mellett partnereink turisztikai szolgáltatásainak hirdetései sorakoznak.\r\n\r\nA térség természeti és kultúrtörténeti látnivalóit, az Országos Kéktúra mellett a hegység legérdekesebb pontjait felfűző turistaútjainak leírását, egyéb hasznos információkat (pl. kerékpártúrák, közlekedés, kisvasutak, télisport és vízisport lehetőségek, a hegység turistaúthálózata, a turistajelzések rendszere, ill. a települések látnivalói stb.) a térkép társkiadványa, a Börzsöny, Ipoly völgye turistakalauz ismerteti.\r\n\r\nA Cartographia ezentúl egy mobiltelefonos applikációval is támogatja vásárló partnereit. Minden térkép hátulján megtalálható egy QR kód, aminek segítségével az adott tájegység ajánlott túráit mutatjuk be képekkel és természetesen térképpel kiegészítve. Az alkalmazás a nagymúltú német Rother céggel együttműködve jött létre, ennek köszönhetően az applikáció használói hozzáférhetnek a Rother cég külföldi hasonló túraleírásaihoz is.',7),('Bükk turistatérkép - Szilvásvárad térképével, ismertetőjével',38,2025,1,2,NULL,9789636800130,3490,3,9,1,'Az aktualizált, új kiadású Bükk turistatérkép 1:40000 méretarányban részletesen és naprakészen ábrázolja a látnivalókat, a sokrétű szabadidős lehetőségeket, ezáltal nélkülözhetetlen társa az aktív turisztikai formák kedvelőinek.\r\n\r\nKiemelt jellemzők:\r\n\r\nturistautak, zarándokutak, tanösvények, kerékpáros útvonalak, látnivalók\r\nszálláshelyek, kempingek, étkezési lehetőségek\r\na turisztikai szolgáltatók ismertetői\r\nSzilvásvárad utcaneves településtérképe\r\na Bükki NP és az Északerdő Zrt. Bemutatóhelyeinek és létesítményeinek ismertetése\r\n\r\nÍzelítő az aktualizált Bükk turistatérkép újdonságaiból:\r\n\r\n\r\n- Eger és Miskolc fontosabb helyi járatainak aktuális hálózata\r\n- egész évben hétvégén közlekedő Miskolc, Tiszai pu. - Bánkút buszjárat\r\n- a felújított lillafüredi kisvasút új megállói\r\n- az épülő Miskolc-Eger bükkaljai kerékpárút/kerékpáros útvonal nyomvonala\r\n- a lillafüredi, újjáépített Zsófia-kilátó és a hozzá vezető új turistautak\r\n- a jelentős bükkaljai turistaútjelzés-változások\r\n- a Bükk naprakész turistaút- és kerékpáros útvonal-hálózata\r\n- a csanyiki kardio ösvény\r\n- a noszvaji meseutak\r\n- aktuális hegyvidéki vendégfogadó szolgáltatások\r\n\r\n\r\nA térkép hátoldala Szilvásvárad településtérképe és ismertetője mellett széleskörű tájékoztatást nyújt térségi partnereink turisztikai szolgáltatásairól.\r\nA térség természeti és kultúrtörténeti látnivalóit, az Országos Kéktúra mellett a hegység legérdekesebb pontjait felfűző turistaútjainak leírását, egyéb hasznos információkat (pl. kerékpártúrák, télisport-lehetőségek, közlekedés, kisvasutak, a hegység természetjárásának múltja, a turistajelzések rendszere, a települések látnivalói stb.) a térkép társkiadványa, a Bükk turistakalauz ismerteti.\r\n\r\n\r\nA Cartographia ezentúl egy mobiltelefonos applikációval is támogatja vásárló partnereit. Minden térkép hátulján megtalálható egy QR kód, aminek segítségével az adott tájegység ajánlott túráit mutatjuk be képekkel és természetesen térképpel kiegészítve. Az alkalmazás a nagymúltú német Rother céggel együttműködve jött létre, ennek köszönhetően az applikáció használói hozzáférhetnek a Rother cég külföldi hasonló túraleírásaihoz is.',7),('Für Elise',27,2026,1,432,5,9789636872557,4949,1,15,3,'Szabó Magda elmúlt nyolcvanéves, amikor lánytestvére született: írt magának egyet. Mert bár a Für Elise önéletrajzi ihletésű mű, a regénybeli fogadott testvér, Bogdán Cecília korábban ismeretlen volt az olvasók előtt.\r\n\r\nCili trianoni árva, Zentáról származik, árvaházból kerül Debrecenbe négyévesen. Ő a bájos, szeretni való szőke gyermek, akit minden bajtól óvnak, dédelgetnek ismerősök, ismeretlenek egyaránt. Ígéretes énekesi karrier előtt áll, várja Olaszországban az ünnepelt karmester férjjelölt, és a nagy lehetőség, a Scala. Cili mégis szomorúan megy férjhez.\r\nMagdolna okos, művelt már kisgyerekkorában is. Esti meseként bibliai történeteket hallgat, s még iskolába sem jár, már latinul veszekszik nagybátyjával. Szülei nem korlátozzák, nem nevelik, csak \"civilizálják\". Nyelveket tanul, képzelete szárnyal: \"olyan szabálytalan voltam, mint maga a szabálytalanság\". Szerencsére mindig akad, aki egyengeti útját, mert látja benne a tehetséget, a későbbi sikeres írót.\r\nA pár soros szöveg végül sosem születik meg Beethoven dallamára. De megszületik a két testvér befejezetlen története, melyben életüknek és Cili korai halálának sok részlete mégis homályban marad. Ennek oka lehet az is, hogy Szabó Magda Magdaléna címmel a regény folytatását tervezte.\r\nA Jaffa Kiadó a szöveggondozáson túl új arculattal, rövid jegyzetekkel, és új, minden korosztály számára jól befogadható külsővel igyekszik segíteni abban, hogy Szabó Magda művei kultúrtörténeti rangjuknak és töretlen népszerűségüknek megfelelő helyre kerülhessenek.',NULL),('King of Pride',41,2025,1,502,5,9789636900946,4999,1,19,2,',,Ez a nő mindenben az ellentéte... és egyben a legnagyobb kísértés is az életében.\r\nA visszafogott, fegyelmezett és jól nevelt.\r\nKai Youngnak sem ideje, sem energiája arra, hogy felfordulás legyen az életében - márpedig Isabella a lila hajával és a kínosan vicces beszólásaival maga a megtestesült káosz. Ráadásul karrierje is fordulóponthoz érkezett, és egy milliárdos vállalat örököseként nem engedheti meg magának, hogy egy nő miatt ne a legfontosabb feladataira koncentráljon. Isabella egy személyben megtestesít mindent, amit a férfi nem akarhat, mégis minden egyes pillantás, minden egyes érintés hatalmas kísértés, hogy megszegje a saját szabályait... és magáévá tegye.\r\nA vakmerő, impulzív és életvidám.\r\nIsabella Valencia még soha nem volt olyan buliban, ahol ne érezte volna jól magát, és soha nem találkozott olyan férfival, akit ne tudott volna levenni a lábáról... kivéve Kai Youngot. Mit számít? Hiszen egyáltalán nem is az esete. Ráadásul Kai annak az exkluzív klubnak az egyik vezetője, ahol ő csaposként dolgozik, így szigorúan tiltott gyümölcs. Ugyanakkor a hűvös külső alatt olyan férfi rejtőzik, akinek egyetlen érintésétől is elolvadna.\r\nIsabella és Kai hiába is próbálnak ellenállni, képtelenek felülkerekedni a vágyaikon. Még ha ezért mindent fel is kell áldozniuk.\"',NULL),('King of Greed',41,2025,1,366,5,9789636900977,4999,1,19,2,'Az övé volt, a felesége volt, de elvesztette...\r\nÉs most bármire képes, hogy visszaszerezze.\r\nBefolyásos. Zseniális. Nagyratörő.\r\nDominic Davenport nem véletlenül lett a Wall Street királya. A semmiből küzdötte fel magát a csúcsra. Mindene megvan: csodálatos otthona, gyönyörű felesége és több pénze, mint amennyit egy élet alatt el tudna költeni. De hiába, mert neki soha semmi nem elég. A kapzsisága viszont elűzi az egyetlen személyt, aki feltétel nélkül szerette. Ez a valaki pedig a felesége. Volt. Csak amikor Alessandra elhagyja, akkor döbben rá, hogy az élet sokkal többről szól, mint a gazdagságról és a hírnévről... de ekkor már talán túl késő.\r\nKedves. Intelligens. Figyelmes.\r\nAlessandra Davenport éveken át játszotta a másodhegedűs szerepét a házasságában. Kitartott férje mellett, amíg ő a birodalmát építette, de most, hogy elérték a csúcsot, rá kell döbbennie, hogy ez a férfi már nem ugyanaz, akibe ő annak idején beleszeretett. Így végül úgy dönt, saját kezébe veszi az irányítást. Az életét és önmagát helyezi az első helyre, még ha ez azt is jelenti, hogy el kell hagynia az egyetlen férfit, akit valaha szeretett. Arra viszont nem számított, hogy a férje nem fogja elengedni... arra meg végképp nem, hogy még harcolni is fog a házasságukért. Kerül, amibe kerül.\r\nVajon sikerül visszatalálniuk egymáshoz, vagy Alessandra és Dominic élete végérvényesen különválik?',NULL),('King of Envy - Az irigység ',41,2025,1,638,5,9789636901912,7499,1,19,2,'Mindene megvolt, amit csak akart... kivéve őt.\r\nVeszélyes. Befolyásos. Zárkózott.\r\nVuk Markovic megrögzött embergyűlölő. A sebhelyes arcú milliárdos csak akkor szólal meg, ha elkerülhetetlen, és a szűk, megbízható körén kívül senkivel sem tart fenn személyes kapcsolatot. Ez alól egyetlen kivétel van: Ayana. A gyönyörű szupermodell, aki a megszállottságának tárgya, az igazi szépség a ő szörnyeteg szemében. Ő látta meg először. Ő akarta először. Ayana mégis az egyetlen barátjának menyasszonya lett - és ahogy közeledik az esküvő, Vuk lelkét a hűség és a vágy szinte kettészakítja. Úgy lenne helyes, ha Ayana az övé lenne... De ahhoz, hogy megszerezze, mindent kockára kell tennie.\r\nGyönyörű. Sikeres. Elbűvölő.\r\nKívülről Ayana Kidane a szupermodellek tökéletes életét éli. A szakma legjobbjai közt tartják számon, ráadásul most már New York egyik legkapósabb agglegényének a menyasszonya. De azt senki sem tudja, hogy az eljegyzésük csupán üzleti megállapodás, ami segíthet Ayanának megszabadulni az őt kizsigerelő modellügynökségtől. Egészen addig nem nehéz eljátszania a szerelmes menyasszonyt, amíg egyre jobban vonzódni nem kezd a vőlegény legjobb barátjához, aki a férfi tanúja is egyben. Kölcsönös vonzalmuk hamarosan perzselő szenvedélybe csap át, ami mindkettejük életét felforgatja.\r\nDe Vuk múltja utoléri a szerelmeseket. Vajon kettejük kapcsolata kibírja az ezzel járó veszélyeket?',NULL),('The Striker - A csatár',41,2025,1,559,5,9789636901974,7499,1,19,2,'Ő az egyetlen nő, aki akar...\r\nÉs az egyetlen, akit nem kaphat meg.\r\n\r\nAsher Donovan élő legenda, a Premier League kedvence, a világ legjobb focistája. Ám egy ellentmondásos átigazolás után legnagyobb riválisa, Vincent DuBois csapattársa lesz. És a két játékos összeférhetetlensége a csapat bajnoki címébe kerül. Ha újra nyerni akarnak, együtt kell dolgozniuk. Kezdetnek részt kell venniük egy szezonon kívüli tréningen.\r\nNem tűnik nehéznek... Aztán Asher megismeri azt, aki a tréninget tartja. A nő gyönyörű, tehetséges, és Asher képtelen kiverni a fejéből. Az egyetlen gond? Ő Vincent húga, és egyértelműen tiltott terület.\r\nScarlett DuBois egykori prímabalerina, akinek a karrierjét derékba törte egy tragikus baleset. Most egy neves tánciskolában tanít, de még mindig kísérti a múltja, és arra vágyik a legkevésbé, hogy a nyáron pont Asher Donovannek tartson tréninget.\r\nMegesküdött, hogy sosem jár focistával, ám amikor a bátyja egy vészhelyzet miatt elhagyja a várost, veszélyesen közel kerül a jóképű, sármos csatárhoz. A tréninggel meg tud birkózni, de mi a helyzet egy szenvedéllyel teli szerelemmel? Az kizárt, főleg, hogy a férfi az egyetlen, aki össze tudja törni a szívét.',NULL),('Erdély - Székelyföld - Kis-Küküllő és vidéke',42,2007,1,120,11,9789638641359,6555,1,30,3,'Ajánló: A Kis-Küküllő, jelentése: kökényes vidék. A kistáj településeit Kibédtől Balavásárig mutatjuk be. A folyó menti dombság a Nyárád és a Kis-Küküllő vízválasztója, 450-600 méter körüli magaslatokkal, mely székely ősvárak nyomait s hozzáfűződő mondavilágot rejti. A Kis-Küküllő völgyéből a Balavásár fölötti szakasz Marosszékhez tartozik. Zöldség- és gyümölcstermesztő vidékhez értünk, melyet a Küküllő menti borvidék is érint. Itt helyezkedett el egykor a szomorú véget ért, elárasztott Bözödújfalu. Szorosan kötődtek e táj történelméhez a Dózsák, a Rédeyek, a Wesselényiek s a Péterffyek széjjelszóródott családjai. Érintették e tájegységet Petőfi Sándor és Jókai Mór is.',7),('Kőzetek és ásványok - Képes ismertető a világ több mint 500 kőzetéről és ásványáról',42,2008,1,256,11,9789638779939,2660,1,30,3,'A Határozó Kézikönyvek a természeti tárgyak legvilágosabb és legpontosabb felismerésében segítik az Ólvasót. Az egyes állat-, növény-, vagy ásványfajok meghatározása biztos, egyszerű és egyértelmű. Minden kötetben csodálatos, jegyzetekkel ellátott fényképek találhatók, amelyeket több, mint 500 faj tömör, tartalmas leírása kísér. A könnyen használható és gyönyörködtető Határozó Kézikönyvek szervesen épülnek be abba a természettudományos könyvtárba, amely bármely korosztályú természetrajongó számára nélkülözhetetlen.',7),('Francia 1x1 - A1 szint - Tanulás egyedül, könnyedén és gyorsan',39,2023,3,306,6,9789638836939,4370,8,31,1,'\"Ez a tankönyv kezdő szintről indul és az alapfokú, A1-es szintig jut el. A leckék felépítése azonos. Terjedelme nem túl hosszú, így alkalmas akár az iskolába vagy a munkába való ingázás, a tömegközlekedésen hasznosan eltöltött idő során is a nyelvtanulásra. A leckék hatalmas szókészlettel rendelkeznek. Minden leckében van egyszerű, mindenki számára könnyen megérthető, majd azt a használatba átültető nyelvtani magyarázat. A leckék végén feladatok találhatóak.\r\nA tankönyvben a tanulók megoldókulcsot is találnak.\"',2),('Ostrom és vihar',1,2016,1,414,2,9789639492806,3799,12,13,1,'\"A sötétség nem hal meg soha.\r\n\r\nAz Igaz-tengeren át menekülő Alina, akit kísértenek a Zónában meggyilkoltak szellemei, új életet kezd Mallal egy ismeretlen földön, miközben igyekszik titokban tartani napidéző voltát. Ám sokáig nem hagyhatja maga mögött sem a múltját, sem a sorsát.\r\nAz Éjúr rettenetes új hatalom birtokában hagyta el az Árnyzónát, és veszedelmes tervet sző, ami a végsőkig próbára teszi a természeti világ határait. Alina egy hírhedt kalóz segítségével visszatér a szeretett országba, hogy elszántan szembeszálljon a Ravkára törő erőkkel. De a ahogy hatalma növekszik, Alina úgy süllyed egyre mélyebbre a tiltott mágiába és az Éjúr játszmájába, és távolodik el egyre jobban Maltól. Választania kell hazája, a hatalom és a szerelem között, amiről mindig úgy hitte, az vezérli különben azt kockáztatja, hogy mindent elveszít a közelgő viharban.\"',NULL),('15 Nap az Egészséges Táplálkozásért',28,2025,1,125,NULL,9789781994951,4790,1,25,2,'Fedezd fel az egyszerű, gyakorlati és hatékony módszert, amellyel mindössze 15 nap alatt átalakíthatod étkezési szokásaidat. Ebben a lépésről-lépésre útmutatóban Ranjot Chahal végigvezet az egészséges táplálkozás útján, könnyen követhető napi étkezési tervekkel, tippekkel és stratégiákkal, amelyek bármilyen életstílushoz illeszkednek. Minden nap konkrét célokra összpontosít -- az energia növelésétől és az emésztés javításától az immunrendszer erősítéséig és az egészséges szokások hosszú távú kialakításáig. Legyél kezdő vagy szeretnéd finomítani étrendedet, ez a könyv kiegyensúlyozott ételeket, okos nassolási ötleteket és gyakorlati útmutatást kínál, hogy energikusnak, tápláltnak és magabiztosnak érezhesd magad. Ranjot Chahal szakértői útmutatásával nemcsak azt tanulod meg, mit egyél, hanem azt is, hogyan tedd az egészséges táplálkozást fenntartható életmódbeli változássá. Ünnepeld a wellness felé vezető utadat, és érezd a különbséget mindössze 15 nap alatt.',NULL),('15 Nap a Fogyáshoz ',28,2025,1,110,NULL,9789781995712,3490,1,25,2,'A 15 nap a fogyáshoz: Egy egyszerű és fenntartható terv egy gyakorlati, tudományosan megalapozott 15 napos programot kínál a fogyás beindításához és az egészséges szokások kialakításához. Minden szint számára ideális, bemutatja a kiegyensúlyozott tányér képletét (50% zöldség, 25% fehérje, 25% szénhidrát) és a tudatos étkezést, hogy rugalmas, bűntudat nélküli megközelítést teremtsen a táplálkozásban. A napi lépések egyszerűvé és fenntarthatóvá teszik az egészséges étkezést. Minden nap új stratégiát hoz, a HIIT és az erősítő edzésektől a stresszkezelésen és alvásoptimalizáláson át, hogy fokozza a zsírégetést és az energiaszintet. Tápanyagban gazdag receptek, eszköz nélküli gyakorlatok és tippek az étvágy csökkentésére vagy a stagnálás leküzdésére tartják fent a motivációt. Opcionális eszközök, mint az időszakos böjt vagy az alacsony szénhidráttartalmú napok lehetővé teszik, hogy a tervet az életstílusodhoz igazítsd. A 15. napra visszatekinthetsz az eredményeidre, és személyre szabott 4 hetes tervet készíthetsz az eredmények fenntartására. Étkezési tervek, naplóíró ösztönzők és tudatos gyakorlatok segítségével ez a könyv felhatalmaz arra, hogy átalakítsd tested és elméd. Ünnepeld a sikereidet, és lépj magabiztosan és könnyedén az egészségesebb jövő felé!',NULL),('Hikaru Nakamura Story: The Boy Who Loved The Board',16,2019,2,78,9,9798343106930,2999,3,23,1,'Hikaru Nakamura Story: The Boy Who Loved the Board is an inspiring children’s book about the early life of chess prodigy Hikaru Nakamura. It follows his journey from discovering chess as a young boy to developing the passion, creativity, and determination that would one day make him one of the world’s most exciting and influential players. Through engaging storytelling, the book highlights dedication, perseverance, and the joy of following your dreams—on and off the chessboard.',NULL),('A Hedgehog Story - The Trip away from the Trouble',34,2022,2,62,2,9798449618450,2660,1,28,3,'The true story of a hedgehog who is forced to flee the Ukraine with his human owners seen from the hedgehog\'s perspective.\r\nIt was inspired by the unlikely appearance of a hedgehog refugee in the author\'s life. It is deliberately neutral in regards to the rights and wrongs of the war because hedgehogs, like most erinaceinae and the nation of Switzerland,maintain a policy of neutrality in regards to human politics.',1),('The Works of Edgar Allen Poe: Volume One',18,2013,2,350,9,9798869262998,9500,3,16,1,'The Works of Edgar Allan Poe: Volume One presents a collection of Poe’s most iconic early writings, showcasing his mastery of gothic atmosphere, psychological tension, and dark imagination. This volume includes some of his best-known tales and poems—rich with mystery, suspense, and the supernatural—highlighting why Poe remains one of the most influential voices in American literature.',NULL),('The Works of Edgar Allen Poe: Volume Two',18,2013,2,380,9,9798869263032,11000,2,16,1,'The Works of Edgar Allan Poe: Volume Two continues the collection of Poe’s influential tales and poems, featuring stories that delve deeper into mystery, horror, and the human psyche. This volume includes some of his most celebrated works of detective fiction, supernatural intrigue, and lyrical poetry, further demonstrating his unmatched skill in crafting suspenseful and haunting narratives.',NULL),('Fate/Grand Order -mortalis:stella- 4 (Manga) - Fate/Grand Order (Manga) 4',14,2023,2,235,6,9798888772119,7000,3,11,1,'The official manga adaptation of one of the most popular mobile games in the world makes its long-awaited return! Continue the time-traveling fantasy story that has enthralled millions, in a new adaptation from 28, the artist behind Tales of Zestiria!\n\n \n\nLet the Festivities Begin\n\nThe second singularity is back in the Roman Empire, where a ruler that should be dead is back to life and challenging Nero Claudius, the fifth emperor. Mash and Ritsuka lend Nero their assistance, but before the battle can begin, Caligula--Nero’s uncle and the third emperor--stands in their way! The stage is set for a new Grand Order in ancient Rome! \n\n \n\nThe official adaptation of the 9 phenomenon that has become one of the most popular mobile games in the world!',4),('Fate/Grand Order -mortalis:stella- 5 (Manga) - Fate/Grand Order (Manga) 5',14,2023,2,220,6,9798888775899,6700,6,11,1,'The official manga adaptation of one of the most popular mobile games in the world makes its long-awaited return! Continue the time-traveling fantasy story that has enthralled millions, in a new adaptation from 28, the artist behind Tales of Zestiria!\n\n \n\nLet the Festivities Begin\n\nThe second singularity is back in the Roman Empire, where a ruler that should be dead is back to life and challenging Nero Claudius, the fifth emperor. Mash and Ritsuka lend Nero their assistance, but before the battle can begin, Caligula--Nero’s uncle and the third emperor--stands in their way! The stage is set for a new Grand Order in ancient Rome! \n\n \n\nThe official adaptation of the 9 phenomenon that has become one of the most popular mobile games in the world!',4);
